INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u1-C1','math',5,1,'u1',2,'혼합 계산식과 계산 순서 약속 — 두 번 이상의 계산이 필요한 상황을 한 줄 식으로 나타내고, 계산 순서에 따라 답이 달라질 수 있어 순서를 하나로 약속해 두었음을 알기',ARRAY['6수01-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u1-C2','math',5,1,'u1',2,'덧셈과 뺄셈이 섞여 있는 식 — 일이 일어난 차례대로 앞에서부터 계산하고, 순서를 바꾸면 답이 달라질 수 있음을 알기',ARRAY['6수01-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u1-C3','math',5,1,'u1',3,'곱셈과 나눗셈이 섞여 있는 식 — 곱셈과 나눗셈은 서로를 되돌리는 같은 자리의 계산이라 앞에서부터 차례로 계산하기',ARRAY['6수01-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u1-C4','math',5,1,'u1',4,'덧셈, 뺄셈, 곱셈이 섞여 있는 식 — 곱셈 부분이 이미 하나의 양(덩어리)이므로 곱셈을 먼저 계산하고 덧셈·뺄셈은 앞에서부터 하기',ARRAY['6수01-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u1-C5','math',5,1,'u1',5,'덧셈, 뺄셈, 나눗셈이 섞여 있는 식 — 나눗셈 부분도 하나의 양이라 나눗셈을 먼저 계산하고, 곱셈과 나눗셈은 덧셈·뺄셈보다 함께 먼저임을 알기',ARRAY['6수01-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u1-C6','math',5,1,'u1',6,'( )가 있는 식 — ( )는 여기까지가 한 덩어리라는 표현이라 ( ) 안을 가장 먼저 계산하고, 상황에 맞게 ( )를 넣어 식을 세우기',ARRAY['6수01-01']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u1-C7','math',5,1,'u1',7,'덧셈, 뺄셈, 곱셈, 나눗셈이 섞여 있는 식 — ( ) 안 → 곱셈·나눗셈 → 덧셈·뺄셈의 세 층 순서로 계산하고 같은 층끼리는 앞에서부터 하기',ARRAY['6수01-01']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u1-C8','math',5,1,'u1',8,'문제 해결 — 부가 가치세가 공급 가격을 10으로 나눈 몫임을 알고, 여러 물건을 산 상황을 혼합 계산식 하나로 나타내며 식을 세우는 방법이 여러 가지일 수 있음을 알기',ARRAY['6수01-01']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u1-X01','math',5,'u1',ARRAY['M5-1-u1-C1','M5-1-u1-C2','M5-1-u1-C7']::text[],'덧셈과 뺄셈이 섞인 식에서 덧셈을 먼저 하거나 뒤에서부터 계산한다(40 − 15 + 5를 40 − 20으로)','덧셈·뺄셈만 있으면 앞에서부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u1-X02','math',5,'u1',ARRAY['M5-1-u1-C3','M5-1-u1-C7']::text[],'곱셈과 나눗셈이 섞인 식에서 곱셈을 먼저 한다(36 ÷ 6 × 2를 36 ÷ 12로)','곱셈과 나눗셈은 한 자리 — 앞에서부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u1-X03','math',5,'u1',ARRAY['M5-1-u1-C4','M5-1-u1-C7']::text[],'덧셈·뺄셈에 곱셈이 섞였는데 앞에서부터 계산한다(5 + 3 × 4를 8 × 4로)','곱셈 부분은 이미 하나의 양 — 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u1-X04','math',5,'u1',ARRAY['M5-1-u1-C5','M5-1-u1-C7']::text[],'덧셈·뺄셈에 나눗셈이 섞였는데 앞에서부터 계산한다(18 + 12 ÷ 3을 30 ÷ 3으로)','나눗셈 부분도 하나의 양 — 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u1-X05','math',5,'u1',ARRAY['M5-1-u1-C3','M5-1-u1-C5','M5-1-u1-C7']::text[],'「곱셈은 먼저, 나눗셈은 나중」 또는 「곱셈이 나눗셈보다 힘이 세다」고 여긴다','곱셈과 나눗셈은 함께 먼저, 둘끼리는 앞에서부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u1-X06','math',5,'u1',ARRAY['M5-1-u1-C6','M5-1-u1-C7','M5-1-u1-C8']::text[],'( )를 보지 않고 ( )가 없는 식처럼 계산한다','( ) 안이 가장 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u1-X07','math',5,'u1',ARRAY['M5-1-u1-C6','M5-1-u1-C7']::text[],'( ) 밖의 곱셈·나눗셈을 ( ) 안보다 먼저 한다','( )는 곱셈·나눗셈보다도 앞') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u1-X08','math',5,'u1',ARRAY['M5-1-u1-C7']::text[],'네 가지가 섞인 식에서 덧셈·뺄셈을 곱셈·나눗셈보다 먼저 하거나 순서를 뒤바꿔 외운다','( ) → 곱셈·나눗셈 → 덧셈·뺄셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u1-X09','math',5,'u1',ARRAY['M5-1-u1-C1','M5-1-u1-C4','M5-1-u1-C5','M5-1-u1-C6','M5-1-u1-C8']::text[],'상황을 식으로 세울 때 한 덩어리를 묶지 않거나 연산을 잘못 고른다(함께 산 두 물건값을 ( ) 없이 뺀다)','무엇이 한 덩어리인지 먼저 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u1-X10','math',5,'u1',ARRAY['M5-1-u1-C1','M5-1-u1-C2','M5-1-u1-C3','M5-1-u1-C4','M5-1-u1-C5','M5-1-u1-C6','M5-1-u1-C7','M5-1-u1-C8']::text[],'계산 순서는 맞았는데 한 걸음의 셈을 잘못한다','한 걸음씩 다시 셈해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u1-X11','math',5,'u1',ARRAY['M5-1-u1-C8']::text[],'부가 가치세를 공급 가격에 10을 곱하거나 100으로 나누어 구한다','공급 가격 ÷ 10') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u1-X12','math',5,'u1',ARRAY['M5-1-u1-C8']::text[],'공급 가격과 실제로 내는 돈(공급 가격 + 부가 가치세)을 같은 것으로 본다','내는 돈 = 공급 가격 + 세금') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u1-X13','math',5,'u1',ARRAY['M5-1-u1-C2','M5-1-u1-C4','M5-1-u1-C5','M5-1-u1-C6','M5-1-u1-C7','M5-1-u1-C8']::text[],'□가 있는 식에서 거꾸로 계산을 잘못한다(더한 것을 또 더하거나 계산 순서를 거꾸로 되돌리지 않는다)','나중에 한 계산부터 거꾸로 되돌리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u1-X14','math',5,'u1',ARRAY['M5-1-u1-C1','M5-1-u1-C2','M5-1-u1-C3','M5-1-u1-C4','M5-1-u1-C5','M5-1-u1-C6','M5-1-u1-C7','M5-1-u1-C8']::text[],'묻는 말을 거꾸로 읽는다 — 옳은↔잘못된, 같은↔다른, 큰↔작은','물음의 「잘못·다른·가장」에 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_basic#1','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C1',1,'mc','auto','알뜰 시장에서 연우는 3000원을 들고 가서 500원짜리 지우개 2개를 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u1-X09']::text[],true,'{"seq":1,"concept":"M5-1-u1-C1","difficulty":1,"kind":"mc","stem":"알뜰 시장에서 연우는 3000원을 들고 가서 500원짜리 지우개 2개를 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3000 − 500 × 2","correct":true},{"t":"3000 + 500 × 2","mis":"M5-1-u1-X09"},{"t":"3000 × 2 − 500","mis":"M5-1-u1-X09"},{"t":"3000 − 500 + 2","mis":"M5-1-u1-X09"}],"explanation":["지우개 값은 500원이 2개 — 500 × 2예요.","남은 돈은 가진 돈 3000원에서 지우개 값을 빼요.","두 계산을 한 줄로 이으면 3000 − 500 × 2예요."],"variant_rule":{"alt":[{"stem":"민서는 5000원을 들고 가서 800원짜리 공책 3권을 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"5000 − 800 × 3","correct":true},{"t":"5000 + 800 × 3","mis":"M5-1-u1-X09"},{"t":"5000 × 3 − 800","mis":"M5-1-u1-X09"},{"t":"5000 − 800 + 3","mis":"M5-1-u1-X09"}],"explanation":["공책 값은 800 × 3이에요.","가진 돈 5000원에서 공책 값을 빼요.","한 줄로 이으면 5000 − 800 × 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_basic#2','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C2',1,'mc','auto','25 − 8 + 6에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X01']::text[],true,'{"seq":2,"concept":"M5-1-u1-C2","difficulty":1,"kind":"mc","stem":"25 − 8 + 6에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"25 − 8","correct":true},{"t":"8 + 6","mis":"M5-1-u1-X01"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X01"}],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","그래서 가장 먼저 계산할 것은 25 − 8이에요.","① 25 − 8 = 17 → ② 17 + 6 = 23이에요."],"variant_rule":{"alt":[{"stem":"63 − 20 + 7에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"63 − 20","correct":true},{"t":"20 + 7","mis":"M5-1-u1-X01"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X01"}],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","가장 먼저 계산할 것은 63 − 20이에요.","① 63 − 20 = 43 → ② 43 + 7 = 50이에요."]},{"stem":"48 − 19 + 5에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"48 − 19","correct":true},{"t":"19 + 5","mis":"M5-1-u1-X01"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X01"}],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","가장 먼저 계산할 것은 48 − 19예요.","① 48 − 19 = 29 → ② 29 + 5 = 34예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_basic#3','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C2',1,'sa','auto','24 − 9 + 3을 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-1-u1-C2","difficulty":1,"kind":"sa","stem":"24 − 9 + 3을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 24 − 9 = 15 → ② 15 + 3 = 18이에요.","그래서 24 − 9 + 3 = 18이에요."],"variant_rule":{"alt":[{"stem":"40 − 15 + 7을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 40 − 15 = 25 → ② 25 + 7 = 32예요.","그래서 40 − 15 + 7 = 32예요."]},{"stem":"36 − 12 + 8을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 36 − 12 = 24 → ② 24 + 8 = 32예요.","그래서 36 − 12 + 8 = 32예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_basic#4','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C1',1,'mc','auto','여러 계산이 섞인 식에서 계산 순서를 하나로 약속하지 않으면 어떤 일이 생길까요?',ARRAY['M5-1-u1-X09','M5-1-u1-X14']::text[],false,'{"seq":4,"concept":"M5-1-u1-C1","difficulty":1,"kind":"mc","stem":"여러 계산이 섞인 식에서 계산 순서를 하나로 약속하지 않으면 어떤 일이 생길까요?","options":[{"t":"사람마다 다른 답이 나올 수 있다","correct":true},{"t":"계산이 더 빨라진다","mis":"M5-1-u1-X09"},{"t":"식을 한 줄로 쓸 수 없게 된다","mis":"M5-1-u1-X09"},{"t":"아무 일도 생기지 않는다","mis":"M5-1-u1-X14"}],"explanation":["3000 − 500 × 2를 곱셈 먼저 하면 2000, 앞에서부터 하면 5000이에요.","순서에 따라 답이 달라질 수 있어요.","그래서 누구나 같은 답을 얻도록 순서를 하나로 약속해 두었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_basic#5','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C2',2,'mc','auto','지갑에 3000원이 있었어요. 공책을 사느라 1200원을 쓰고, 심부름을 하고 500원을 받았어요. 지금 지갑에 있는 돈은 얼마인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X09']::text[],true,'{"seq":5,"concept":"M5-1-u1-C2","difficulty":2,"kind":"mc","stem":"지갑에 3000원이 있었어요. 공책을 사느라 1200원을 쓰고, 심부름을 하고 500원을 받았어요. 지금 지갑에 있는 돈은 얼마인가요?","options":[{"t":"2300원","correct":true},{"t":"1300원","mis":"M5-1-u1-X01"},{"t":"1700원","mis":"M5-1-u1-X09"},{"t":"4700원","mis":"M5-1-u1-X09"}],"explanation":["쓴 돈은 빼고 받은 돈은 더해요 — 3000 − 1200 + 500.","덧셈과 뺄셈만 섞였으니 앞에서부터 — 3000 − 1200 = 1800, 1800 + 500 = 2300.","지금 있는 돈은 2300원이에요. 뒤의 1200 + 500부터 하면 1300원으로 틀려요."],"variant_rule":{"alt":[{"stem":"지갑에 5000원이 있었어요. 간식을 사느라 2500원을 쓰고, 용돈으로 1000원을 받았어요. 지금 지갑에 있는 돈은 얼마인가요?","options":[{"t":"3500원","correct":true},{"t":"1500원","mis":"M5-1-u1-X01"},{"t":"2500원","mis":"M5-1-u1-X09"},{"t":"8500원","mis":"M5-1-u1-X09"}],"explanation":["5000 − 2500 + 1000으로 나타내요.","앞에서부터 — 5000 − 2500 = 2500, 2500 + 1000 = 3500.","3500원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_basic#6','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C2',2,'sa','auto','사탕 45개 가운데 18개를 나누어 주고, 나중에 12개를 더 받았어요. 지금 사탕은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u1-C2","difficulty":2,"kind":"sa","stem":"사탕 45개 가운데 18개를 나누어 주고, 나중에 12개를 더 받았어요. 지금 사탕은 몇 개인가요? 숫자로 쓰세요.","answer":["39","39개"],"explanation":["나누어 준 것은 빼고 받은 것은 더해요 — 45 − 18 + 12.","앞에서부터 — 45 − 18 = 27, 27 + 12 = 39.","지금 사탕은 39개예요."],"variant_rule":{"alt":[{"stem":"사탕 30개 가운데 8개를 나누어 주고, 나중에 5개를 더 받았어요. 지금 사탕은 몇 개인가요? 숫자로 쓰세요.","answer":["27","27개"],"explanation":["30 − 8 + 5로 나타내요.","앞에서부터 — 30 − 8 = 22, 22 + 5 = 27.","27개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_basic#7','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C2',2,'error','auto','준서는 40 − 15 + 5를 계산해 20이라고 답했어요. 준서가 잘못한 것은 무엇인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X10','M5-1-u1-X14']::text[],true,'{"seq":7,"concept":"M5-1-u1-C2","difficulty":2,"kind":"error","stem":"준서는 40 − 15 + 5를 계산해 20이라고 답했어요. 준서가 잘못한 것은 무엇인가요?","options":[{"t":"뒤의 15 + 5를 먼저 했다","correct":true,"mis_target":"M5-1-u1-X01"},{"t":"40 − 15를 잘못 뺐다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["덧셈과 뺄셈만 있으면 앞에서부터 계산해요.","40 − 15 = 25, 25 + 5 = 30이 맞아요.","준서는 15 + 5 = 20을 먼저 해서 40 − 20 = 20이 나왔어요."],"variant_rule":{"alt":[{"stem":"하윤이는 52 − 17 + 9를 계산해 26이라고 답했어요. 하윤이가 잘못한 것은 무엇인가요?","options":[{"t":"뒤의 17 + 9를 먼저 했다","correct":true,"mis_target":"M5-1-u1-X01"},{"t":"52 − 17을 잘못 뺐다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["앞에서부터 계산해요.","52 − 17 = 35, 35 + 9 = 44가 맞아요.","하윤이는 17 + 9 = 26을 먼저 해서 52 − 26 = 26이 나왔어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_basic#8','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C2',2,'ox','auto','덧셈과 뺄셈이 섞여 있는 식에서는 덧셈을 먼저 계산해야 해요.',ARRAY['M5-1-u1-X01']::text[],true,'{"seq":8,"concept":"M5-1-u1-C2","difficulty":2,"kind":"ox","stem":"덧셈과 뺄셈이 섞여 있는 식에서는 덧셈을 먼저 계산해야 해요.","answer":"X","reason_options":[{"t":"덧셈과 뺄셈만 섞이면 일이 일어난 차례대로 앞에서부터 계산해서","correct":true},{"t":"덧셈이 뺄셈보다 먼저라서","mis":"M5-1-u1-X01"}],"mis":"M5-1-u1-X01","explanation":["덧셈과 뺄셈은 같은 자리의 계산이에요.","그래서 앞에서부터 차례로 계산해요.","예: 40 − 15 + 5 = 25 + 5 = 30이에요."],"variant_rule":{"alt":[{"stem":"덧셈과 뺄셈이 섞여 있는 식에서는 뒤에서부터 계산해도 언제나 답이 같아요.","answer":"X","reason_options":[{"t":"뒤에서부터 하면 답이 달라질 수 있어서 앞에서부터 계산해요","correct":true},{"t":"덧셈과 뺄셈은 순서를 바꿔도 늘 같아서","mis":"M5-1-u1-X01"}],"explanation":["3000 − 1200 + 500을 앞에서부터 하면 2300이에요.","뒤의 1200 + 500부터 하면 1300이 나와요.","순서를 바꾸면 답이 달라질 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_basic#9','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C2',2,'mc','auto','52 − 17 + 9를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X10']::text[],true,'{"seq":9,"concept":"M5-1-u1-C2","difficulty":2,"kind":"mc","stem":"52 − 17 + 9를 계산하면 얼마인가요?","options":[{"t":"44","correct":true},{"t":"26","mis":"M5-1-u1-X01"},{"t":"54","mis":"M5-1-u1-X10"},{"t":"34","mis":"M5-1-u1-X10"}],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 52 − 17 = 35 → ② 35 + 9 = 44예요.","그래서 52 − 17 + 9 = 44예요."],"variant_rule":{"alt":[{"stem":"70 − 26 + 14를 계산하면 얼마인가요?","options":[{"t":"58","correct":true},{"t":"30","mis":"M5-1-u1-X01"},{"t":"68","mis":"M5-1-u1-X10"},{"t":"48","mis":"M5-1-u1-X10"}],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 70 − 26 = 44 → ② 44 + 14 = 58이에요.","그래서 70 − 26 + 14 = 58이에요."]},{"stem":"85 − 38 + 6을 계산하면 얼마인가요?","options":[{"t":"53","correct":true},{"t":"41","mis":"M5-1-u1-X01"},{"t":"63","mis":"M5-1-u1-X10"},{"t":"43","mis":"M5-1-u1-X10"}],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 85 − 38 = 47 → ② 47 + 6 = 53이에요.","그래서 85 − 38 + 6 = 53이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_basic#10','math',5,1,'u1','L02','g5_1_math_u1_L02_basic','lesson_basic','M5-1-u1-C2',3,'mc','auto','60 − 20 + 10과 60 − 20 − 10의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X14']::text[],true,'{"seq":10,"concept":"M5-1-u1-C2","difficulty":3,"kind":"mc","stem":"60 − 20 + 10과 60 − 20 − 10의 계산 결과의 차는 얼마인가요?","options":[{"t":"20","correct":true},{"t":"0","mis":"M5-1-u1-X01"},{"t":"50","mis":"M5-1-u1-X14"},{"t":"30","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","60 − 20 + 10 = 50 · 60 − 20 − 10 = 30","두 결과의 차는 50 − 30 = 20이에요."],"variant_rule":{"alt":[{"stem":"80 − 30 + 15와 80 − 30 − 15의 계산 결과의 차는 얼마인가요?","options":[{"t":"30","correct":true},{"t":"0","mis":"M5-1-u1-X01"},{"t":"65","mis":"M5-1-u1-X14"},{"t":"35","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","80 − 30 + 15 = 65 · 80 − 30 − 15 = 35","두 결과의 차는 65 − 35 = 30이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_challenge#1','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C2',2,'mc','auto','93 − 45 + 28 − 16을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X10']::text[],true,'{"seq":1,"concept":"M5-1-u1-C2","difficulty":2,"kind":"mc","stem":"93 − 45 + 28 − 16을 계산하면 얼마인가요?","options":[{"t":"60","correct":true},{"t":"4","mis":"M5-1-u1-X01"},{"t":"70","mis":"M5-1-u1-X10"},{"t":"50","mis":"M5-1-u1-X10"}],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 93 − 45 = 48 → ② 48 + 28 = 76 → ③ 76 − 16 = 60이에요.","그래서 93 − 45 + 28 − 16 = 60이에요."],"variant_rule":{"alt":[{"stem":"81 − 37 + 24 − 19를 계산하면 얼마인가요?","options":[{"t":"49","correct":true},{"t":"1","mis":"M5-1-u1-X01"},{"t":"59","mis":"M5-1-u1-X10"},{"t":"39","mis":"M5-1-u1-X10"}],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 81 − 37 = 44 → ② 44 + 24 = 68 → ③ 68 − 19 = 49예요.","그래서 81 − 37 + 24 − 19 = 49예요."]},{"stem":"76 − 28 − 19 + 35를 계산하면 얼마인가요?","options":[{"t":"64","correct":true},{"t":"74","mis":"M5-1-u1-X10"},{"t":"54","mis":"M5-1-u1-X10"},{"t":"66","mis":"M5-1-u1-X10"}],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 76 − 28 = 48 → ② 48 − 19 = 29 → ③ 29 + 35 = 64예요.","그래서 76 − 28 − 19 + 35 = 64예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_challenge#2','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C1',2,'mc','auto','18 + 6 − 4를 계산하면 20이에요. 바르게 계산한 순서는 어느 것인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X14']::text[],false,'{"seq":2,"concept":"M5-1-u1-C1","difficulty":2,"kind":"mc","stem":"18 + 6 − 4를 계산하면 20이에요. 바르게 계산한 순서는 어느 것인가요?","options":[{"t":"18 + 6을 먼저 했다","correct":true},{"t":"6 − 4를 먼저 했다","mis":"M5-1-u1-X01"},{"t":"18 − 4를 먼저 했다","mis":"M5-1-u1-X01"},{"t":"어느 것부터 해도 다르다","mis":"M5-1-u1-X14"}],"explanation":["덧셈과 뺄셈만 섞이면 앞에서부터예요.","18 + 6 = 24, 24 − 4 = 20이에요.","이 식은 6 − 4부터 해도 20이 나오지만, 약속은 앞에서부터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_challenge#3','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C2',3,'mc','auto','70 − □ + 15 = 60에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X01']::text[],true,'{"seq":3,"concept":"M5-1-u1-C2","difficulty":3,"kind":"mc","stem":"70 − □ + 15 = 60에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"25","correct":true},{"t":"45","mis":"M5-1-u1-X13"},{"t":"55","mis":"M5-1-u1-X13"},{"t":"5","mis":"M5-1-u1-X01"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 60이 되어야 해요.","거꾸로 되돌리면 □ = 25예요.","확인: 70 − 25 + 15 → ① 70 − 25 = 45 → ② 45 + 15 = 60"],"variant_rule":{"alt":[{"stem":"90 − □ + 20 = 75에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"35","correct":true},{"t":"55","mis":"M5-1-u1-X13"},{"t":"65","mis":"M5-1-u1-X13"},{"t":"15","mis":"M5-1-u1-X01"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 75가 되어야 해요.","거꾸로 되돌리면 □ = 35예요.","확인: 90 − 35 + 20 → ① 90 − 35 = 55 → ② 55 + 20 = 75"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_challenge#4','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C1',3,'mc','auto','다음 중 계산 순서를 바꾸면 답이 달라지는 식은 어느 것인가요?',ARRAY['M5-1-u1-X14']::text[],false,'{"seq":4,"concept":"M5-1-u1-C1","difficulty":3,"kind":"mc","stem":"다음 중 계산 순서를 바꾸면 답이 달라지는 식은 어느 것인가요?","options":[{"t":"50 − 20 + 10","correct":true},{"t":"50 + 20 + 10","mis":"M5-1-u1-X14"},{"t":"50 − 20 − 10을 앞에서부터만 계산한 것","mis":"M5-1-u1-X14"},{"t":"20 + 10 + 50","mis":"M5-1-u1-X14"}],"explanation":["덧셈만 있는 식은 순서를 바꿔도 답이 같아요.","50 − 20 + 10을 앞에서부터 하면 40, 20 + 10부터 하면 20이에요.","뺄셈 뒤에 덧셈이 오면 순서에 따라 답이 갈려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_challenge#5','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C2',3,'error','auto','「45 − 18 + 12」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X14']::text[],false,'{"seq":5,"concept":"M5-1-u1-C2","difficulty":3,"kind":"error","stem":"「45 − 18 + 12」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「18 + 12를 먼저 해서 45에서 30을 빼면 돼.」","correct":true,"mis_target":"M5-1-u1-X01"},{"t":"서아 — 「45 − 18 = 27을 먼저 하고 12를 더해.」","mis":"M5-1-u1-X14"},{"t":"지호 — 「나누어 준 다음 받았으니 일어난 차례대로 해.」","mis":"M5-1-u1-X14"}],"explanation":["나누어 준 일과 받은 일은 차례로 일어났어요.","그래서 앞에서부터 — 45 − 18 = 27, 27 + 12 = 39예요.","도윤이처럼 18 + 12부터 하면 15가 되어 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_challenge#6','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C2',3,'mc','auto','버스에 34명이 타고 있었어요. 첫 정류장에서 9명이 내리고 15명이 탔어요. 식으로 나타내 계산한 것으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u1-X09','M5-1-u1-X01']::text[],true,'{"seq":6,"concept":"M5-1-u1-C2","difficulty":3,"kind":"mc","stem":"버스에 34명이 타고 있었어요. 첫 정류장에서 9명이 내리고 15명이 탔어요. 식으로 나타내 계산한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"34 − 9 + 15 = 40","correct":true},{"t":"34 − (9 + 15) = 10","mis":"M5-1-u1-X09"},{"t":"34 + 9 − 15 = 28","mis":"M5-1-u1-X09"},{"t":"34 − 9 + 15 = 10","mis":"M5-1-u1-X01"}],"explanation":["내린 사람은 빼고 탄 사람은 더해요.","34 − 9 + 15를 앞에서부터 — 34 − 9 = 25, 25 + 15 = 40.","버스에는 40명이 있어요."],"variant_rule":{"alt":[{"stem":"도서관에 책이 52권 있었어요. 18권을 빌려 가고 7권이 돌아왔어요. 식으로 나타내 계산한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"52 − 18 + 7 = 41","correct":true},{"t":"52 − (18 + 7) = 27","mis":"M5-1-u1-X09"},{"t":"52 + 18 − 7 = 63","mis":"M5-1-u1-X09"},{"t":"52 − 18 + 7 = 27","mis":"M5-1-u1-X01"}],"explanation":["빌려 간 책은 빼고 돌아온 책은 더해요.","52 − 18 = 34, 34 + 7 = 41.","41권이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_challenge#7','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C2',3,'mc','auto','75 − 25 + 15와 75 − (25 + 15)의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],true,'{"seq":7,"concept":"M5-1-u1-C2","difficulty":3,"kind":"mc","stem":"75 − 25 + 15와 75 − (25 + 15)의 계산 결과의 차는 얼마인가요?","options":[{"t":"30","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"65","mis":"M5-1-u1-X14"},{"t":"35","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","75 − 25 + 15 = 65 · 75 − (25 + 15) = 35","두 결과의 차는 65 − 35 = 30이에요."],"variant_rule":{"alt":[{"stem":"64 − 24 + 16과 64 − (24 + 16)의 계산 결과의 차는 얼마인가요?","options":[{"t":"32","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"56","mis":"M5-1-u1-X14"},{"t":"24","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","64 − 24 + 16 = 56 · 64 − (24 + 16) = 24","두 결과의 차는 56 − 24 = 32예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_challenge#8','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C1',4,'essay','teacher','3000 − 1200 + 500을 앞에서부터 계산한 답과 뒤의 1200 + 500부터 계산한 답을 각각 구하고, 지갑 이야기(3000원에서 1200원을 쓰고 500원을 받음)에 맞는 답은 어느 것인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u1-C1","difficulty":4,"kind":"essay","stem":"3000 − 1200 + 500을 앞에서부터 계산한 답과 뒤의 1200 + 500부터 계산한 답을 각각 구하고, 지갑 이야기(3000원에서 1200원을 쓰고 500원을 받음)에 맞는 답은 어느 것인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 앞에서부터 하면 3000 − 1200 = 1800, 1800 + 500 = 2300이고, 뒤부터 하면 1200 + 500 = 1700, 3000 − 1700 = 1300이다. 돈을 먼저 쓰고 나중에 받았으니 일어난 차례대로 계산한 2300원이 맞다.","scoring_points":["앞에서부터 계산한 2300을 구했는가","뒤부터 계산한 1300을 구했는가","일이 일어난 차례대로 계산해야 한다는 까닭을 썼는가"]},"explanation":["앞에서부터 — 2300, 뒤부터 — 1300이에요.","돈은 먼저 쓰고 나중에 받았어요.","일어난 차례대로 계산한 2300원이 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_challenge#9','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C2',4,'essay','teacher','「덧셈과 뺄셈이 섞이면 덧셈을 먼저 해야 해.」라는 지호의 말이 맞는지 판단하고, 52 − 17 + 9를 예로 들어 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u1-C2","difficulty":4,"kind":"essay","stem":"「덧셈과 뺄셈이 섞이면 덧셈을 먼저 해야 해.」라는 지호의 말이 맞는지 판단하고, 52 − 17 + 9를 예로 들어 설명하세요.","answer_guide":{"answer":"예: 틀리다. 덧셈과 뺄셈만 섞이면 앞에서부터 차례로 계산한다. 52 − 17 + 9는 52 − 17 = 35, 35 + 9 = 44이다. 덧셈을 먼저 하면 17 + 9 = 26, 52 − 26 = 26으로 답이 달라진다.","scoring_points":["틀리다고 판단했는가","앞에서부터 계산해 44를 구했는가","덧셈을 먼저 하면 답이 달라짐(26)을 보였는가"]},"explanation":["덧셈과 뺄셈만 있으면 앞에서부터예요.","52 − 17 + 9 = 35 + 9 = 44예요.","덧셈을 먼저 하면 26으로 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L02_challenge#10','math',5,1,'u1','L02','g5_1_math_u1_L02_challenge','lesson_challenge','M5-1-u1-C2',4,'mc','auto','□ − 18 + 25 = 60에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13']::text[],true,'{"seq":10,"concept":"M5-1-u1-C2","difficulty":4,"kind":"mc","stem":"□ − 18 + 25 = 60에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"53","correct":true},{"t":"103","mis":"M5-1-u1-X13"},{"t":"67","mis":"M5-1-u1-X13"},{"t":"17","mis":"M5-1-u1-X13"}],"explanation":["□ − 18을 먼저 하고 25를 더해 60이 되었어요.","거꾸로 되돌리면 60 − 25 = 35, 35 + 18 = 53이에요.","확인: 53 − 18 + 25 = 35 + 25 = 60이에요."],"variant_rule":{"alt":[{"stem":"□ − 24 + 16 = 50에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"58","correct":true},{"t":"90","mis":"M5-1-u1-X13"},{"t":"42","mis":"M5-1-u1-X13"},{"t":"10","mis":"M5-1-u1-X13"}],"explanation":["거꾸로 되돌려요 — 50 − 16 = 34.","34 + 24 = 58이에요.","확인: 58 − 24 + 16 = 34 + 16 = 50이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_basic#1','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',1,'mc','auto','24 ÷ 4 × 3에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X02']::text[],true,'{"seq":1,"concept":"M5-1-u1-C3","difficulty":1,"kind":"mc","stem":"24 ÷ 4 × 3에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"24 ÷ 4","correct":true},{"t":"4 × 3","mis":"M5-1-u1-X02"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X02"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","그래서 가장 먼저 계산할 것은 24 ÷ 4예요.","① 24 ÷ 4 = 6 → ② 6 × 3 = 18이에요."],"variant_rule":{"alt":[{"stem":"36 ÷ 6 × 2에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"36 ÷ 6","correct":true},{"t":"6 × 2","mis":"M5-1-u1-X02"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X02"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","가장 먼저 계산할 것은 36 ÷ 6이에요.","① 36 ÷ 6 = 6 → ② 6 × 2 = 12예요."]},{"stem":"48 ÷ 8 × 5에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"48 ÷ 8","correct":true},{"t":"8 × 5","mis":"M5-1-u1-X02"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X02"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","가장 먼저 계산할 것은 48 ÷ 8이에요.","① 48 ÷ 8 = 6 → ② 6 × 5 = 30이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_basic#2','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',1,'sa','auto','24 ÷ 4 × 3을 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u1-C3","difficulty":1,"kind":"sa","stem":"24 ÷ 4 × 3을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 24 ÷ 4 = 6 → ② 6 × 3 = 18이에요.","그래서 24 ÷ 4 × 3 = 18이에요."],"variant_rule":{"alt":[{"stem":"36 ÷ 9 × 7을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 36 ÷ 9 = 4 → ② 4 × 7 = 28이에요.","그래서 36 ÷ 9 × 7 = 28이에요."]},{"stem":"45 ÷ 5 × 6을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 45 ÷ 5 = 9 → ② 9 × 6 = 54예요.","그래서 45 ÷ 5 × 6 = 54예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_basic#3','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',1,'mc','auto','48 ÷ 8 × 5를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X10']::text[],true,'{"seq":3,"concept":"M5-1-u1-C3","difficulty":1,"kind":"mc","stem":"48 ÷ 8 × 5를 계산하면 얼마인가요?","options":[{"t":"30","correct":true},{"t":"40","mis":"M5-1-u1-X10"},{"t":"20","mis":"M5-1-u1-X10"},{"t":"32","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 48 ÷ 8 = 6 → ② 6 × 5 = 30이에요.","그래서 48 ÷ 8 × 5 = 30이에요."],"variant_rule":{"alt":[{"stem":"56 ÷ 7 × 4를 계산하면 얼마인가요?","options":[{"t":"32","correct":true},{"t":"2","mis":"M5-1-u1-X02"},{"t":"42","mis":"M5-1-u1-X10"},{"t":"22","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 56 ÷ 7 = 8 → ② 8 × 4 = 32예요.","그래서 56 ÷ 7 × 4 = 32예요."]},{"stem":"63 ÷ 9 × 8을 계산하면 얼마인가요?","options":[{"t":"56","correct":true},{"t":"66","mis":"M5-1-u1-X10"},{"t":"46","mis":"M5-1-u1-X10"},{"t":"58","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 63 ÷ 9 = 7 → ② 7 × 8 = 56이에요.","그래서 63 ÷ 9 × 8 = 56이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_basic#4','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',1,'mc','auto','쿠키 24개를 접시 4개에 똑같이 나누어 담고, 그중 3접시를 교실로 가져가요. 가져가는 쿠키 수를 구하는 식은 어느 것인가요?',ARRAY['M5-1-u1-X09','M5-1-u1-X02']::text[],true,'{"seq":4,"concept":"M5-1-u1-C3","difficulty":1,"kind":"mc","stem":"쿠키 24개를 접시 4개에 똑같이 나누어 담고, 그중 3접시를 교실로 가져가요. 가져가는 쿠키 수를 구하는 식은 어느 것인가요?","options":[{"t":"24 ÷ 4 × 3","correct":true},{"t":"24 × 4 ÷ 3","mis":"M5-1-u1-X09"},{"t":"24 ÷ (4 × 3)","mis":"M5-1-u1-X02"},{"t":"24 − 4 × 3","mis":"M5-1-u1-X09"}],"explanation":["한 접시에 담긴 쿠키는 24 ÷ 4예요.","그것을 3접시만큼 모으니 × 3이에요.","이어 쓰면 24 ÷ 4 × 3이에요."],"variant_rule":{"alt":[{"stem":"귤 40개를 바구니 5개에 똑같이 나누어 담고, 그중 2바구니를 할머니께 드려요. 드리는 귤 수를 구하는 식은 어느 것인가요?","options":[{"t":"40 ÷ 5 × 2","correct":true},{"t":"40 × 5 ÷ 2","mis":"M5-1-u1-X09"},{"t":"40 ÷ (5 × 2)","mis":"M5-1-u1-X02"},{"t":"40 − 5 × 2","mis":"M5-1-u1-X09"}],"explanation":["한 바구니의 귤은 40 ÷ 5예요.","2바구니만큼 모으니 × 2예요.","40 ÷ 5 × 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_basic#5','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',2,'sa','auto','쿠키 24개를 접시 4개에 똑같이 나누어 담고, 그중 3접시를 교실로 가져가요. 가져가는 쿠키는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-1-u1-C3","difficulty":2,"kind":"sa","stem":"쿠키 24개를 접시 4개에 똑같이 나누어 담고, 그중 3접시를 교실로 가져가요. 가져가는 쿠키는 몇 개인가요? 숫자로 쓰세요.","answer":["18","18개"],"explanation":["24 ÷ 4 × 3을 앞에서부터 계산해요.","24 ÷ 4 = 6 — 한 접시에 6개, 6 × 3 = 18.","가져가는 쿠키는 18개예요."],"variant_rule":{"alt":[{"stem":"귤 40개를 바구니 5개에 똑같이 나누어 담고, 그중 2바구니를 할머니께 드려요. 드리는 귤은 몇 개인가요? 숫자로 쓰세요.","answer":["16","16개"],"explanation":["40 ÷ 5 × 2를 앞에서부터 계산해요.","40 ÷ 5 = 8, 8 × 2 = 16.","16개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_basic#6','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',2,'error','auto','예린이는 36 ÷ 6 × 2를 계산해 3이라고 답했어요. 예린이가 잘못한 것은 무엇인가요?',ARRAY['M5-1-u1-X02','M5-1-u1-X10','M5-1-u1-X14']::text[],true,'{"seq":6,"concept":"M5-1-u1-C3","difficulty":2,"kind":"error","stem":"예린이는 36 ÷ 6 × 2를 계산해 3이라고 답했어요. 예린이가 잘못한 것은 무엇인가요?","options":[{"t":"뒤의 6 × 2를 먼저 했다","correct":true,"mis_target":"M5-1-u1-X02"},{"t":"36 ÷ 6을 잘못 나눴다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["곱셈과 나눗셈만 섞이면 앞에서부터 계산해요.","36 ÷ 6 = 6, 6 × 2 = 12가 맞아요.","예린이는 6 × 2 = 12를 먼저 해서 36 ÷ 12 = 3이 나왔어요."],"variant_rule":{"alt":[{"stem":"태오는 48 ÷ 4 × 2를 계산해 6이라고 답했어요. 태오가 잘못한 것은 무엇인가요?","options":[{"t":"뒤의 4 × 2를 먼저 했다","correct":true,"mis_target":"M5-1-u1-X02"},{"t":"48 ÷ 4를 잘못 나눴다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["앞에서부터 계산해요.","48 ÷ 4 = 12, 12 × 2 = 24가 맞아요.","태오는 4 × 2를 먼저 해서 48 ÷ 8 = 6이 나왔어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_basic#7','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',2,'ox','auto','곱셈과 나눗셈이 섞여 있는 식에서는 곱셈을 먼저 계산해요.',ARRAY['M5-1-u1-X05']::text[],false,'{"seq":7,"concept":"M5-1-u1-C3","difficulty":2,"kind":"ox","stem":"곱셈과 나눗셈이 섞여 있는 식에서는 곱셈을 먼저 계산해요.","answer":"X","reason_options":[{"t":"곱셈과 나눗셈은 서로를 되돌리는 같은 자리의 계산이라 앞에서부터 계산해서","correct":true},{"t":"곱셈이 나눗셈보다 힘이 세서","mis":"M5-1-u1-X05"}],"mis":"M5-1-u1-X05","explanation":["곱셈이 나눗셈보다 힘이 센 게 아니에요.","둘은 같은 자리라서 일어난 차례대로 — 앞에서부터 해요.","예: 24 ÷ 4 × 3 = 6 × 3 = 18이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_basic#8','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',2,'match','auto','계산식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u1-C3","difficulty":2,"kind":"match","stem":"계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"36 ÷ 4 × 3","r":"27"},{"l":"72 ÷ 8 × 5","r":"45"},{"l":"28 ÷ 7 × 9","r":"36"}],"mis":"M5-1-u1-X02","explanation":["식마다 계산 순서를 지켜 셈해요.","36 ÷ 4 × 3 = 27 · 72 ÷ 8 × 5 = 45 · 28 ÷ 7 × 9 = 36","곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"42 ÷ 6 × 4","r":"28"},{"l":"54 ÷ 9 × 7","r":"42"},{"l":"35 ÷ 5 × 3","r":"21"}],"explanation":["식마다 계산 순서를 지켜 셈해요.","42 ÷ 6 × 4 = 28 · 54 ÷ 9 × 7 = 42 · 35 ÷ 5 × 3 = 21","곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_basic#9','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',2,'mc','auto','7 × 8 ÷ 4를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X10']::text[],true,'{"seq":9,"concept":"M5-1-u1-C3","difficulty":2,"kind":"mc","stem":"7 × 8 ÷ 4를 계산하면 얼마인가요?","options":[{"t":"14","correct":true},{"t":"24","mis":"M5-1-u1-X10"},{"t":"4","mis":"M5-1-u1-X10"},{"t":"16","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 7 × 8 = 56 → ② 56 ÷ 4 = 14예요.","그래서 7 × 8 ÷ 4 = 14예요."],"variant_rule":{"alt":[{"stem":"6 × 9 ÷ 3을 계산하면 얼마인가요?","options":[{"t":"18","correct":true},{"t":"28","mis":"M5-1-u1-X10"},{"t":"8","mis":"M5-1-u1-X10"},{"t":"20","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 6 × 9 = 54 → ② 54 ÷ 3 = 18이에요.","그래서 6 × 9 ÷ 3 = 18이에요."]},{"stem":"9 × 4 ÷ 6을 계산하면 얼마인가요?","options":[{"t":"6","correct":true},{"t":"16","mis":"M5-1-u1-X10"},{"t":"8","mis":"M5-1-u1-X10"},{"t":"4","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 9 × 4 = 36 → ② 36 ÷ 6 = 6이에요.","그래서 9 × 4 ÷ 6 = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_basic#10','math',5,1,'u1','L03','g5_1_math_u1_L03_basic','lesson_basic','M5-1-u1-C3',3,'mc','auto','48 ÷ 4 × 2와 48 ÷ (4 × 2)의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],true,'{"seq":10,"concept":"M5-1-u1-C3","difficulty":3,"kind":"mc","stem":"48 ÷ 4 × 2와 48 ÷ (4 × 2)의 계산 결과의 차는 얼마인가요?","options":[{"t":"18","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"24","mis":"M5-1-u1-X14"},{"t":"6","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","48 ÷ 4 × 2 = 24 · 48 ÷ (4 × 2) = 6","두 결과의 차는 24 − 6 = 18이에요."],"variant_rule":{"alt":[{"stem":"60 ÷ 5 × 3과 60 ÷ (5 × 3)의 계산 결과의 차는 얼마인가요?","options":[{"t":"32","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"36","mis":"M5-1-u1-X14"},{"t":"4","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","60 ÷ 5 × 3 = 36 · 60 ÷ (5 × 3) = 4","두 결과의 차는 36 − 4 = 32예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_challenge#1','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',2,'mc','auto','96 ÷ 8 × 3 ÷ 4를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X02','M5-1-u1-X10']::text[],true,'{"seq":1,"concept":"M5-1-u1-C3","difficulty":2,"kind":"mc","stem":"96 ÷ 8 × 3 ÷ 4를 계산하면 얼마인가요?","options":[{"t":"9","correct":true},{"t":"1","mis":"M5-1-u1-X02"},{"t":"19","mis":"M5-1-u1-X10"},{"t":"11","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 96 ÷ 8 = 12 → ② 12 × 3 = 36 → ③ 36 ÷ 4 = 9예요.","그래서 96 ÷ 8 × 3 ÷ 4 = 9예요."],"variant_rule":{"alt":[{"stem":"84 ÷ 7 × 5 ÷ 6을 계산하면 얼마인가요?","options":[{"t":"10","correct":true},{"t":"20","mis":"M5-1-u1-X10"},{"t":"12","mis":"M5-1-u1-X10"},{"t":"8","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 84 ÷ 7 = 12 → ② 12 × 5 = 60 → ③ 60 ÷ 6 = 10이에요.","그래서 84 ÷ 7 × 5 ÷ 6 = 10이에요."]},{"stem":"72 ÷ 9 × 6 ÷ 4를 계산하면 얼마인가요?","options":[{"t":"12","correct":true},{"t":"22","mis":"M5-1-u1-X10"},{"t":"2","mis":"M5-1-u1-X10"},{"t":"14","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 72 ÷ 9 = 8 → ② 8 × 6 = 48 → ③ 48 ÷ 4 = 12예요.","그래서 72 ÷ 9 × 6 ÷ 4 = 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_challenge#2','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',2,'mc','auto','「곱셈이 나눗셈보다 먼저야.」라는 말을 바르게 판단한 것은 어느 것인가요?',ARRAY['M5-1-u1-X05','M5-1-u1-X02']::text[],false,'{"seq":2,"concept":"M5-1-u1-C3","difficulty":2,"kind":"mc","stem":"「곱셈이 나눗셈보다 먼저야.」라는 말을 바르게 판단한 것은 어느 것인가요?","options":[{"t":"틀리다 · 곱셈과 나눗셈은 앞에서부터 차례로 한다","correct":true},{"t":"맞다 · 곱셈이 언제나 먼저다","mis":"M5-1-u1-X05"},{"t":"맞다 · 곱셈이 뒤에 있어도 먼저 한다","mis":"M5-1-u1-X02"},{"t":"틀리다 · 나눗셈이 언제나 먼저다","mis":"M5-1-u1-X05"}],"explanation":["곱셈과 나눗셈은 서로를 되돌리는 계산이에요.","그래서 같은 자리 — 어느 쪽이 먼저가 아니에요.","둘만 섞이면 앞에서부터 차례로 계산해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_challenge#3','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',3,'mc','auto','□ ÷ 6 × 4 = 32에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X02']::text[],true,'{"seq":3,"concept":"M5-1-u1-C3","difficulty":3,"kind":"mc","stem":"□ ÷ 6 × 4 = 32에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"48","correct":true},{"t":"8","mis":"M5-1-u1-X13"},{"t":"192","mis":"M5-1-u1-X13"},{"t":"12","mis":"M5-1-u1-X02"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 32가 되어야 해요.","거꾸로 되돌리면 □ = 48이에요.","확인: 48 ÷ 6 × 4 → ① 48 ÷ 6 = 8 → ② 8 × 4 = 32"],"variant_rule":{"alt":[{"stem":"□ ÷ 5 × 3 = 27에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"45","correct":true},{"t":"9","mis":"M5-1-u1-X13"},{"t":"135","mis":"M5-1-u1-X13"},{"t":"15","mis":"M5-1-u1-X02"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 27이 되어야 해요.","거꾸로 되돌리면 □ = 45예요.","확인: 45 ÷ 5 × 3 → ① 45 ÷ 5 = 9 → ② 9 × 3 = 27"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_challenge#4','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',3,'mc','auto','다음 중 계산 결과가 가장 큰 것은 어느 것인가요?',ARRAY['M5-1-u1-X14']::text[],false,'{"seq":4,"concept":"M5-1-u1-C3","difficulty":3,"kind":"mc","stem":"다음 중 계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"72 ÷ 6 × 3","correct":true},{"t":"72 ÷ (6 × 3)","mis":"M5-1-u1-X14"},{"t":"72 ÷ 3 ÷ 6","mis":"M5-1-u1-X14"},{"t":"72 ÷ 6 ÷ 3","mis":"M5-1-u1-X14"}],"explanation":["식마다 앞에서부터(또는 ( ) 먼저) 셈해요.","72 ÷ 6 × 3 = 36 · 72 ÷ (6 × 3) = 4 · 72 ÷ 3 ÷ 6 = 4 · 72 ÷ 6 ÷ 3 = 4.","가장 큰 것은 72 ÷ 6 × 3 = 36이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_challenge#5','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',3,'mc','auto','연필 한 타는 12자루예요. 연필 5타를 학생 6명에게 똑같이 나누어 주면 한 명은 몇 자루를 받나요?',ARRAY['M5-1-u1-X02','M5-1-u1-X09']::text[],true,'{"seq":5,"concept":"M5-1-u1-C3","difficulty":3,"kind":"mc","stem":"연필 한 타는 12자루예요. 연필 5타를 학생 6명에게 똑같이 나누어 주면 한 명은 몇 자루를 받나요?","options":[{"t":"10자루","correct":true},{"t":"2자루","mis":"M5-1-u1-X02"},{"t":"72자루","mis":"M5-1-u1-X09"},{"t":"60자루","mis":"M5-1-u1-X09"}],"explanation":["연필은 모두 12 × 5자루예요.","그것을 6명에게 나누니 12 × 5 ÷ 6이에요.","앞에서부터 — 12 × 5 = 60, 60 ÷ 6 = 10자루예요."],"variant_rule":{"alt":[{"stem":"달걀 한 판은 30개예요. 달걀 2판을 5집에 똑같이 나누어 주면 한 집은 몇 개를 받나요?","options":[{"t":"12개","correct":true},{"t":"3개","mis":"M5-1-u1-X02"},{"t":"150개","mis":"M5-1-u1-X09"},{"t":"60개","mis":"M5-1-u1-X09"}],"explanation":["달걀은 모두 30 × 2개예요.","5집에 나누니 30 × 2 ÷ 5예요.","30 × 2 = 60, 60 ÷ 5 = 12개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_challenge#6','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',3,'error','auto','「24 ÷ 4 × 3」을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u1-X02','M5-1-u1-X14']::text[],false,'{"seq":6,"concept":"M5-1-u1-C3","difficulty":3,"kind":"error","stem":"「24 ÷ 4 × 3」을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「4 × 3 = 12를 먼저 해서 24 ÷ 12 = 2야.」","correct":true,"mis_target":"M5-1-u1-X02"},{"t":"민준 — 「한 접시에 6개씩, 3접시면 18개야.」","mis":"M5-1-u1-X14"},{"t":"하린 — 「앞에서부터 24 ÷ 4 = 6, 6 × 3 = 18이야.」","mis":"M5-1-u1-X14"}],"explanation":["곱셈과 나눗셈은 앞에서부터 계산해요.","24 ÷ 4 = 6, 6 × 3 = 18이에요.","수아는 곱셈을 먼저 해서 2가 나왔는데, 쿠키가 접시 하나에도 못 미치니 이상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_challenge#7','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',3,'sa','auto','81 ÷ 9 × 6 ÷ 2를 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-1-u1-C3","difficulty":3,"kind":"sa","stem":"81 ÷ 9 × 6 ÷ 2를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 81 ÷ 9 = 9 → ② 9 × 6 = 54 → ③ 54 ÷ 2 = 27이에요.","그래서 81 ÷ 9 × 6 ÷ 2 = 27이에요."],"variant_rule":{"alt":[{"stem":"64 ÷ 8 × 9 ÷ 3을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 64 ÷ 8 = 8 → ② 8 × 9 = 72 → ③ 72 ÷ 3 = 24예요.","그래서 64 ÷ 8 × 9 ÷ 3 = 24예요."]},{"stem":"90 ÷ 6 × 4 ÷ 5를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 90 ÷ 6 = 15 → ② 15 × 4 = 60 → ③ 60 ÷ 5 = 12예요.","그래서 90 ÷ 6 × 4 ÷ 5 = 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_challenge#8','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',4,'essay','teacher','쿠키 24개를 접시 4개에 똑같이 나누어 담고 그중 3접시를 가져가요. 24 ÷ 4 × 3을 곱셈부터 계산하면 왜 이야기와 맞지 않는지 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u1-C3","difficulty":4,"kind":"essay","stem":"쿠키 24개를 접시 4개에 똑같이 나누어 담고 그중 3접시를 가져가요. 24 ÷ 4 × 3을 곱셈부터 계산하면 왜 이야기와 맞지 않는지 설명하세요.","answer_guide":{"answer":"예: 곱셈부터 하면 4 × 3 = 12, 24 ÷ 12 = 2로 쿠키가 2개뿐이 되어, 한 접시에 담긴 6개보다도 적다. 실제로는 한 접시에 24 ÷ 4 = 6개를 먼저 구하고 3접시를 모아 6 × 3 = 18개이다. 나눈 다음에 모았으니 앞에서부터 계산해야 한다.","scoring_points":["곱셈부터 하면 2가 나옴을 보였는가","앞에서부터 계산해 18을 구했는가","나눈 뒤 모은 차례 때문이라는 까닭을 썼는가"]},"explanation":["곱셈부터 하면 24 ÷ 12 = 2예요.","앞에서부터 하면 6 × 3 = 18이에요.","나눈 다음에 모았으니 앞에서부터가 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_challenge#9','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',4,'essay','teacher','7 × 8 ÷ 4를 앞에서부터 계산한 답과 8 ÷ 4를 먼저 계산한 답을 각각 구하고, 이 식에서 두 답이 같은지 다른지 쓰세요. 그래도 계산 순서는 어떻게 약속되어 있는지 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u1-C3","difficulty":4,"kind":"essay","stem":"7 × 8 ÷ 4를 앞에서부터 계산한 답과 8 ÷ 4를 먼저 계산한 답을 각각 구하고, 이 식에서 두 답이 같은지 다른지 쓰세요. 그래도 계산 순서는 어떻게 약속되어 있는지 함께 쓰세요.","answer_guide":{"answer":"예: 앞에서부터 7 × 8 = 56, 56 ÷ 4 = 14이다. 8 ÷ 4 = 2를 먼저 하면 7 × 2 = 14로 이 식에서는 답이 같다. 그러나 24 ÷ 4 × 3처럼 바꾸면 답이 달라지는 식이 있으므로 곱셈과 나눗셈은 앞에서부터 계산하기로 약속되어 있다.","scoring_points":["앞에서부터 계산해 14를 구했는가","8 ÷ 4를 먼저 해도 14임을 보였는가","그래도 앞에서부터 계산하는 약속을 밝혔는가"]},"explanation":["앞에서부터 7 × 8 ÷ 4 = 56 ÷ 4 = 14예요.","이 식은 8 ÷ 4부터 해도 14예요.","하지만 약속은 언제나 앞에서부터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L03_challenge#10','math',5,1,'u1','L03','g5_1_math_u1_L03_challenge','lesson_challenge','M5-1-u1-C3',4,'mc','auto','어떤 수를 3으로 나눈 다음 8을 곱했더니 56이 되었어요. 어떤 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X02']::text[],true,'{"seq":10,"concept":"M5-1-u1-C3","difficulty":4,"kind":"mc","stem":"어떤 수를 3으로 나눈 다음 8을 곱했더니 56이 되었어요. 어떤 수는 얼마인가요?","options":[{"t":"21","correct":true},{"t":"7","mis":"M5-1-u1-X13"},{"t":"168","mis":"M5-1-u1-X13"},{"t":"18","mis":"M5-1-u1-X02"}],"explanation":["□ ÷ 3 × 8 = 56이에요.","거꾸로 되돌리면 56 ÷ 8 = 7, 7 × 3 = 21이에요.","확인: 21 ÷ 3 × 8 = 7 × 8 = 56이에요."],"variant_rule":{"alt":[{"stem":"어떤 수를 4로 나눈 다음 6을 곱했더니 54가 되었어요. 어떤 수는 얼마인가요?","options":[{"t":"36","correct":true},{"t":"9","mis":"M5-1-u1-X13"},{"t":"216","mis":"M5-1-u1-X13"},{"t":"24","mis":"M5-1-u1-X02"}],"explanation":["□ ÷ 4 × 6 = 54예요.","거꾸로 54 ÷ 6 = 9, 9 × 4 = 36이에요.","확인: 36 ÷ 4 × 6 = 9 × 6 = 54예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_basic#1','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',1,'mc','auto','1000 − 350 × 2에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X03']::text[],true,'{"seq":1,"concept":"M5-1-u1-C4","difficulty":1,"kind":"mc","stem":"1000 − 350 × 2에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"350 × 2","correct":true},{"t":"1000 − 350","mis":"M5-1-u1-X03"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X03"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","그래서 가장 먼저 계산할 것은 350 × 2예요.","① 350 × 2 = 700 → ② 1000 − 700 = 300이에요."],"variant_rule":{"alt":[{"stem":"5 + 3 × 4에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"3 × 4","correct":true},{"t":"5 + 3","mis":"M5-1-u1-X03"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X03"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","가장 먼저 계산할 것은 3 × 4예요.","① 3 × 4 = 12 → ② 5 + 12 = 17이에요."]},{"stem":"20 − 3 × 4에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"3 × 4","correct":true},{"t":"20 − 3","mis":"M5-1-u1-X03"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X03"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","가장 먼저 계산할 것은 3 × 4예요.","① 3 × 4 = 12 → ② 20 − 12 = 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_basic#2','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',1,'mc','auto','지호는 1000원을 들고 문구점에 가서 350원짜리 지우개 2개를 샀어요. 남은 돈은 얼마인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X09']::text[],true,'{"seq":2,"concept":"M5-1-u1-C4","difficulty":1,"kind":"mc","stem":"지호는 1000원을 들고 문구점에 가서 350원짜리 지우개 2개를 샀어요. 남은 돈은 얼마인가요?","options":[{"t":"300원","correct":true},{"t":"1300원","mis":"M5-1-u1-X03"},{"t":"650원","mis":"M5-1-u1-X09"},{"t":"1700원","mis":"M5-1-u1-X09"}],"explanation":["남은 돈은 1000 − 350 × 2예요.","곱셈을 먼저 — 350 × 2 = 700, 1000 − 700 = 300.","앞에서부터 하면 1300원으로 가진 돈보다 많아져 이상해요."],"variant_rule":{"alt":[{"stem":"하은이는 2000원을 들고 가서 450원짜리 풀 3개를 샀어요. 남은 돈은 얼마인가요?","options":[{"t":"650원","correct":true},{"t":"4650원","mis":"M5-1-u1-X03"},{"t":"1550원","mis":"M5-1-u1-X09"},{"t":"3350원","mis":"M5-1-u1-X09"}],"explanation":["남은 돈은 2000 − 450 × 3이에요.","곱셈을 먼저 — 450 × 3 = 1350, 2000 − 1350 = 650.","650원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_basic#3','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',1,'sa','auto','7 + 6 × 5를 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-1-u1-C4","difficulty":1,"kind":"sa","stem":"7 + 6 × 5를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 6 × 5 = 30 → ② 7 + 30 = 37이에요.","그래서 7 + 6 × 5 = 37이에요."],"variant_rule":{"alt":[{"stem":"9 + 4 × 8을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["41"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 4 × 8 = 32 → ② 9 + 32 = 41이에요.","그래서 9 + 4 × 8 = 41이에요."]},{"stem":"6 + 7 × 3을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 7 × 3 = 21 → ② 6 + 21 = 27이에요.","그래서 6 + 7 × 3 = 27이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_basic#4','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',1,'mc','auto','50 − 4 × 6을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X10']::text[],true,'{"seq":4,"concept":"M5-1-u1-C4","difficulty":1,"kind":"mc","stem":"50 − 4 × 6을 계산하면 얼마인가요?","options":[{"t":"26","correct":true},{"t":"276","mis":"M5-1-u1-X03"},{"t":"36","mis":"M5-1-u1-X10"},{"t":"16","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 4 × 6 = 24 → ② 50 − 24 = 26이에요.","그래서 50 − 4 × 6 = 26이에요."],"variant_rule":{"alt":[{"stem":"80 − 9 × 7을 계산하면 얼마인가요?","options":[{"t":"17","correct":true},{"t":"497","mis":"M5-1-u1-X03"},{"t":"27","mis":"M5-1-u1-X10"},{"t":"7","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 9 × 7 = 63 → ② 80 − 63 = 17이에요.","그래서 80 − 9 × 7 = 17이에요."]},{"stem":"60 − 8 × 5를 계산하면 얼마인가요?","options":[{"t":"20","correct":true},{"t":"260","mis":"M5-1-u1-X03"},{"t":"30","mis":"M5-1-u1-X10"},{"t":"10","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 8 × 5 = 40 → ② 60 − 40 = 20이에요.","그래서 60 − 8 × 5 = 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_basic#5','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',2,'error','auto','서아는 5 + 3 × 4를 계산해 32라고 답했어요. 서아가 잘못한 것은 무엇인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X10','M5-1-u1-X14']::text[],true,'{"seq":5,"concept":"M5-1-u1-C4","difficulty":2,"kind":"error","stem":"서아는 5 + 3 × 4를 계산해 32라고 답했어요. 서아가 잘못한 것은 무엇인가요?","options":[{"t":"앞의 5 + 3을 먼저 했다","correct":true,"mis_target":"M5-1-u1-X03"},{"t":"3 × 4를 잘못 곱했다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["덧셈에 곱셈이 섞이면 곱셈을 먼저 해요.","3 × 4 = 12, 5 + 12 = 17이 맞아요.","서아는 5 + 3 = 8을 먼저 해서 8 × 4 = 32가 나왔어요."],"variant_rule":{"alt":[{"stem":"도현이는 9 + 2 × 6을 계산해 66이라고 답했어요. 도현이가 잘못한 것은 무엇인가요?","options":[{"t":"앞의 9 + 2를 먼저 했다","correct":true,"mis_target":"M5-1-u1-X03"},{"t":"2 × 6을 잘못 곱했다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["곱셈을 먼저 해요.","2 × 6 = 12, 9 + 12 = 21이 맞아요.","도현이는 9 + 2 = 11을 먼저 해서 11 × 6 = 66이 나왔어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_basic#6','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',2,'sa','auto','4개들이 사탕 6봉지가 있었어요. 그중 9개를 먹었다면 남은 사탕은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-1-u1-C4","difficulty":2,"kind":"sa","stem":"4개들이 사탕 6봉지가 있었어요. 그중 9개를 먹었다면 남은 사탕은 몇 개인가요? 숫자로 쓰세요.","answer":["15","15개"],"explanation":["사탕은 모두 4 × 6개, 먹은 것은 9개 — 4 × 6 − 9.","곱셈을 먼저 — 4 × 6 = 24, 24 − 9 = 15.","남은 사탕은 15개예요."],"variant_rule":{"alt":[{"stem":"5개들이 귤 7봉지가 있었어요. 그중 8개를 먹었다면 남은 귤은 몇 개인가요? 숫자로 쓰세요.","answer":["27","27개"],"explanation":["5 × 7 − 8이에요.","5 × 7 = 35, 35 − 8 = 27.","27개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_basic#7','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',2,'ox','auto','「350 × 2」는 350원이 2개라는 하나의 값이라서, 1000 − 350 × 2에서는 곱셈을 먼저 해요.',ARRAY['M5-1-u1-X03']::text[],false,'{"seq":7,"concept":"M5-1-u1-C4","difficulty":2,"kind":"ox","stem":"「350 × 2」는 350원이 2개라는 하나의 값이라서, 1000 − 350 × 2에서는 곱셈을 먼저 해요.","answer":"O","reason_options":[{"t":"곱셈 부분이 이미 하나의 양(덩어리)이라 먼저 구해 두어야 해서","correct":true},{"t":"곱셈이 뺄셈보다 힘이 세서","mis":"M5-1-u1-X03"}],"mis":"M5-1-u1-X03","explanation":["350 × 2는 지우개 2개의 값 — 700원짜리 하나인 셈이에요.","덩어리를 먼저 만들고 그다음 빼요.","곱셈이 힘이 세서가 아니라 하나의 양이기 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_basic#8','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',2,'match','auto','계산식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u1-C4","difficulty":2,"kind":"match","stem":"계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"8 + 3 × 7","r":"29"},{"l":"30 − 4 × 5","r":"10"},{"l":"6 × 4 + 9","r":"33"}],"mis":"M5-1-u1-X03","explanation":["식마다 계산 순서를 지켜 셈해요.","8 + 3 × 7 = 29 · 30 − 4 × 5 = 10 · 6 × 4 + 9 = 33","곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"5 + 6 × 3","r":"23"},{"l":"40 − 7 × 4","r":"12"},{"l":"9 × 3 − 8","r":"19"}],"explanation":["식마다 계산 순서를 지켜 셈해요.","5 + 6 × 3 = 23 · 40 − 7 × 4 = 12 · 9 × 3 − 8 = 19","곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_basic#9','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',2,'mc','auto','45 − 3 × 8 + 6을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X01','M5-1-u1-X10']::text[],true,'{"seq":9,"concept":"M5-1-u1-C4","difficulty":2,"kind":"mc","stem":"45 − 3 × 8 + 6을 계산하면 얼마인가요?","options":[{"t":"27","correct":true},{"t":"342","mis":"M5-1-u1-X03"},{"t":"15","mis":"M5-1-u1-X01"},{"t":"37","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 3 × 8 = 24 → ② 45 − 24 = 21 → ③ 21 + 6 = 27이에요.","그래서 45 − 3 × 8 + 6 = 27이에요."],"variant_rule":{"alt":[{"stem":"52 + 4 × 7 − 30을 계산하면 얼마인가요?","options":[{"t":"50","correct":true},{"t":"362","mis":"M5-1-u1-X03"},{"t":"60","mis":"M5-1-u1-X10"},{"t":"40","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 4 × 7 = 28 → ② 52 + 28 = 80 → ③ 80 − 30 = 50이에요.","그래서 52 + 4 × 7 − 30 = 50이에요."]},{"stem":"38 − 5 × 6 + 12를 계산하면 얼마인가요?","options":[{"t":"20","correct":true},{"t":"210","mis":"M5-1-u1-X03"},{"t":"30","mis":"M5-1-u1-X10"},{"t":"10","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 5 × 6 = 30 → ② 38 − 30 = 8 → ③ 8 + 12 = 20이에요.","그래서 38 − 5 × 6 + 12 = 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_basic#10','math',5,1,'u1','L04','g5_1_math_u1_L04_basic','lesson_basic','M5-1-u1-C4',3,'mc','auto','20 − 3 × 4와 (20 − 3) × 4의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],true,'{"seq":10,"concept":"M5-1-u1-C4","difficulty":3,"kind":"mc","stem":"20 − 3 × 4와 (20 − 3) × 4의 계산 결과의 차는 얼마인가요?","options":[{"t":"60","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"8","mis":"M5-1-u1-X14"},{"t":"68","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","20 − 3 × 4 = 8 · (20 − 3) × 4 = 68","두 결과의 차는 68 − 8 = 60이에요."],"variant_rule":{"alt":[{"stem":"30 − 2 × 9와 (30 − 2) × 9의 계산 결과의 차는 얼마인가요?","options":[{"t":"240","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"12","mis":"M5-1-u1-X14"},{"t":"252","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","30 − 2 × 9 = 12 · (30 − 2) × 9 = 252","두 결과의 차는 252 − 12 = 240이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_challenge#1','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',2,'mc','auto','64 − 7 × 8 + 15를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X10']::text[],true,'{"seq":1,"concept":"M5-1-u1-C4","difficulty":2,"kind":"mc","stem":"64 − 7 × 8 + 15를 계산하면 얼마인가요?","options":[{"t":"23","correct":true},{"t":"471","mis":"M5-1-u1-X03"},{"t":"33","mis":"M5-1-u1-X10"},{"t":"13","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 7 × 8 = 56 → ② 64 − 56 = 8 → ③ 8 + 15 = 23이에요.","그래서 64 − 7 × 8 + 15 = 23이에요."],"variant_rule":{"alt":[{"stem":"90 − 6 × 9 + 28을 계산하면 얼마인가요?","options":[{"t":"64","correct":true},{"t":"784","mis":"M5-1-u1-X03"},{"t":"8","mis":"M5-1-u1-X01"},{"t":"74","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 6 × 9 = 54 → ② 90 − 54 = 36 → ③ 36 + 28 = 64예요.","그래서 90 − 6 × 9 + 28 = 64예요."]},{"stem":"75 + 8 × 4 − 46을 계산하면 얼마인가요?","options":[{"t":"61","correct":true},{"t":"286","mis":"M5-1-u1-X03"},{"t":"71","mis":"M5-1-u1-X10"},{"t":"51","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 8 × 4 = 32 → ② 75 + 32 = 107 → ③ 107 − 46 = 61이에요.","그래서 75 + 8 × 4 − 46 = 61이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_challenge#2','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',2,'mc','auto','「섞여 있는 식은 무조건 앞에서부터야.」라는 말을 바르게 판단한 것은 어느 것인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X08']::text[],false,'{"seq":2,"concept":"M5-1-u1-C4","difficulty":2,"kind":"mc","stem":"「섞여 있는 식은 무조건 앞에서부터야.」라는 말을 바르게 판단한 것은 어느 것인가요?","options":[{"t":"틀리다 · 곱셈이 있으면 곱셈이 먼저다","correct":true},{"t":"맞다 · 언제나 앞에서부터 한다","mis":"M5-1-u1-X03"},{"t":"맞다 · 곱셈도 앞에 있으면 나중이다","mis":"M5-1-u1-X03"},{"t":"틀리다 · 뺄셈을 먼저 해야 한다","mis":"M5-1-u1-X08"}],"explanation":["덧셈·뺄셈만, 곱셈·나눗셈만 섞였을 때는 앞에서부터예요.","덧셈·뺄셈에 곱셈이 섞이면 곱셈이 먼저예요.","그래서 「무조건 앞에서부터」는 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_challenge#3','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',3,'mc','auto','50 − □ × 3 = 26에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X03']::text[],true,'{"seq":3,"concept":"M5-1-u1-C4","difficulty":3,"kind":"mc","stem":"50 − □ × 3 = 26에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"24","mis":"M5-1-u1-X13"},{"t":"12","mis":"M5-1-u1-X03"},{"t":"6","mis":"M5-1-u1-X13"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 26이 되어야 해요.","거꾸로 되돌리면 □ = 8이에요.","확인: 50 − 8 × 3 → ① 8 × 3 = 24 → ② 50 − 24 = 26"],"variant_rule":{"alt":[{"stem":"60 − □ × 4 = 32에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"7","correct":true},{"t":"28","mis":"M5-1-u1-X13"},{"t":"8","mis":"M5-1-u1-X03"},{"t":"23","mis":"M5-1-u1-X13"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 32가 되어야 해요.","거꾸로 되돌리면 □ = 7이에요.","확인: 60 − 7 × 4 → ① 7 × 4 = 28 → ② 60 − 28 = 32"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_challenge#4','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',3,'mc','auto','연필 한 자루는 600원, 지우개 한 개는 400원이에요. 연필 3자루와 지우개 2개를 사고 5000원을 냈어요. 거스름돈을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u1-X09','M5-1-u1-X03']::text[],false,'{"seq":4,"concept":"M5-1-u1-C4","difficulty":3,"kind":"mc","stem":"연필 한 자루는 600원, 지우개 한 개는 400원이에요. 연필 3자루와 지우개 2개를 사고 5000원을 냈어요. 거스름돈을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"5000 − 600 × 3 − 400 × 2","correct":true},{"t":"5000 − 600 × 3 + 400 × 2","mis":"M5-1-u1-X09"},{"t":"5000 − 600 + 400 × 3 × 2","mis":"M5-1-u1-X09"},{"t":"(5000 − 600) × 3 − 400 × 2","mis":"M5-1-u1-X03"}],"explanation":["연필 값은 600 × 3, 지우개 값은 400 × 2예요.","두 값을 모두 5000원에서 빼요.","5000 − 600 × 3 − 400 × 2 = 5000 − 1800 − 800 = 2400원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_challenge#5','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',3,'mc','auto','5000 − 600 × 3 − 400 × 2를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X10','M5-1-u1-X03']::text[],false,'{"seq":5,"concept":"M5-1-u1-C4","difficulty":3,"kind":"mc","stem":"5000 − 600 × 3 − 400 × 2를 계산하면 얼마인가요?","options":[{"t":"2400","correct":true},{"t":"3200","mis":"M5-1-u1-X10"},{"t":"8400","mis":"M5-1-u1-X03"},{"t":"4000","mis":"M5-1-u1-X10"}],"explanation":["곱셈 둘을 먼저 — 600 × 3 = 1800, 400 × 2 = 800.","그다음 앞에서부터 — 5000 − 1800 = 3200, 3200 − 800 = 2400.","거스름돈은 2400원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_challenge#6','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',3,'error','auto','「7 + 6 × 5」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X14']::text[],false,'{"seq":6,"concept":"M5-1-u1-C4","difficulty":3,"kind":"error","stem":"「7 + 6 × 5」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「7 + 6 = 13을 먼저 하고 5를 곱하면 65야.」","correct":true,"mis_target":"M5-1-u1-X03"},{"t":"유나 — 「6 × 5는 하나의 덩어리라 먼저 해.」","mis":"M5-1-u1-X14"},{"t":"건우 — 「6 × 5 = 30, 7 + 30 = 37이야.」","mis":"M5-1-u1-X14"}],"explanation":["덧셈에 곱셈이 섞이면 곱셈을 먼저 해요.","6 × 5 = 30, 7 + 30 = 37이에요.","지안이는 앞에서부터 해서 65가 나왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_challenge#7','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',3,'mc','auto','8 + 4 × 6과 (8 + 4) × 6의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],true,'{"seq":7,"concept":"M5-1-u1-C4","difficulty":3,"kind":"mc","stem":"8 + 4 × 6과 (8 + 4) × 6의 계산 결과의 차는 얼마인가요?","options":[{"t":"40","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"32","mis":"M5-1-u1-X14"},{"t":"72","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","8 + 4 × 6 = 32 · (8 + 4) × 6 = 72","두 결과의 차는 72 − 32 = 40이에요."],"variant_rule":{"alt":[{"stem":"9 + 3 × 7과 (9 + 3) × 7의 계산 결과의 차는 얼마인가요?","options":[{"t":"54","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"30","mis":"M5-1-u1-X14"},{"t":"84","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","9 + 3 × 7 = 30 · (9 + 3) × 7 = 84","두 결과의 차는 84 − 30 = 54예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_challenge#8','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',4,'essay','teacher','1000 − 350 × 2를 앞에서부터 계산하면 1300이 나와요. 지우개 이야기(1000원으로 350원짜리 지우개 2개를 삼)를 들어 이 답이 왜 이상한지, 바른 계산은 무엇인지 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u1-C4","difficulty":4,"kind":"essay","stem":"1000 − 350 × 2를 앞에서부터 계산하면 1300이 나와요. 지우개 이야기(1000원으로 350원짜리 지우개 2개를 삼)를 들어 이 답이 왜 이상한지, 바른 계산은 무엇인지 설명하세요.","answer_guide":{"answer":"예: 앞에서부터 하면 1000 − 350 = 650, 650 × 2 = 1300으로 가진 돈 1000원보다 많아져 이상하다. 350 × 2는 지우개 2개 값이라는 하나의 양이므로 먼저 구한다. 350 × 2 = 700, 1000 − 700 = 300원이 남는다.","scoring_points":["1300이 가진 돈보다 많아 이상함을 썼는가","350 × 2가 하나의 양(덩어리)임을 설명했는가","바른 답 300원을 구했는가"]},"explanation":["앞에서부터 하면 가진 돈보다 많은 1300이 나와요.","350 × 2는 지우개 값이라는 하나의 양이에요.","1000 − 700 = 300원이 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_challenge#9','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',4,'essay','teacher','「사과 3개씩 5봉지에서 4개를 먹었다」를 식으로 나타내 계산하고, 곱셈을 먼저 하는 까닭을 이 상황에 맞게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u1-C4","difficulty":4,"kind":"essay","stem":"「사과 3개씩 5봉지에서 4개를 먹었다」를 식으로 나타내 계산하고, 곱셈을 먼저 하는 까닭을 이 상황에 맞게 쓰세요.","answer_guide":{"answer":"예: 3 × 5 − 4 = 15 − 4 = 11개. 3 × 5는 봉지에 든 사과 전체라는 하나의 양이어서, 그 양을 먼저 구한 다음 먹은 4개를 빼야 한다.","scoring_points":["3 × 5 − 4로 식을 세웠는가","11개를 구했는가","곱셈 부분이 전체 양(덩어리)이라는 까닭을 썼는가"]},"explanation":["식은 3 × 5 − 4예요.","3 × 5 = 15, 15 − 4 = 11개예요.","3 × 5는 사과 전체라는 하나의 양이라 먼저 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L04_challenge#10','math',5,1,'u1','L04','g5_1_math_u1_L04_challenge','lesson_challenge','M5-1-u1-C4',4,'mc','auto','어떤 수에 6을 곱한 다음 25를 더해야 할 것을 잘못하여 어떤 수에 25를 더한 다음 6을 곱했더니 192가 되었어요. 바르게 계산하면 얼마인가요?',ARRAY['M5-1-u1-X14','M5-1-u1-X13']::text[],false,'{"seq":10,"concept":"M5-1-u1-C4","difficulty":4,"kind":"mc","stem":"어떤 수에 6을 곱한 다음 25를 더해야 할 것을 잘못하여 어떤 수에 25를 더한 다음 6을 곱했더니 192가 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"67","correct":true},{"t":"192","mis":"M5-1-u1-X14"},{"t":"42","mis":"M5-1-u1-X13"},{"t":"7","mis":"M5-1-u1-X13"}],"explanation":["잘못 계산한 식은 (□ + 25) × 6 = 192 — 거꾸로 192 ÷ 6 = 32, 32 − 25 = 7이에요.","어떤 수는 7이에요.","바르게 계산하면 7 × 6 + 25 = 42 + 25 = 67이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_basic#1','math',5,1,'u1','L05','g5_1_math_u1_L05_basic','lesson_basic','M5-1-u1-C5',1,'mc','auto','30 − 24 ÷ 6에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X04']::text[],true,'{"seq":1,"concept":"M5-1-u1-C5","difficulty":1,"kind":"mc","stem":"30 − 24 ÷ 6에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"24 ÷ 6","correct":true},{"t":"30 − 24","mis":"M5-1-u1-X04"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X04"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","그래서 가장 먼저 계산할 것은 24 ÷ 6이에요.","① 24 ÷ 6 = 4 → ② 30 − 4 = 26이에요."],"variant_rule":{"alt":[{"stem":"18 + 12 ÷ 3에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"12 ÷ 3","correct":true},{"t":"18 + 12","mis":"M5-1-u1-X04"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X04"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","가장 먼저 계산할 것은 12 ÷ 3이에요.","① 12 ÷ 3 = 4 → ② 18 + 4 = 22예요."]},{"stem":"40 − 16 ÷ 4에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"16 ÷ 4","correct":true},{"t":"40 − 16","mis":"M5-1-u1-X04"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X04"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","가장 먼저 계산할 것은 16 ÷ 4예요.","① 16 ÷ 4 = 4 → ② 40 − 4 = 36이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_basic#2','math',5,1,'u1','L05','g5_1_math_u1_L05_basic','lesson_basic','M5-1-u1-C5',1,'sa','auto','30 − 24 ÷ 6을 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u1-C5","difficulty":1,"kind":"sa","stem":"30 − 24 ÷ 6을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 24 ÷ 6 = 4 → ② 30 − 4 = 26이에요.","그래서 30 − 24 ÷ 6 = 26이에요."],"variant_rule":{"alt":[{"stem":"50 − 32 ÷ 4를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 32 ÷ 4 = 8 → ② 50 − 8 = 42예요.","그래서 50 − 32 ÷ 4 = 42예요."]},{"stem":"27 + 36 ÷ 9를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 36 ÷ 9 = 4 → ② 27 + 4 = 31이에요.","그래서 27 + 36 ÷ 9 = 31이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_basic#3','math',5,1,'u1','L05','g5_1_math_u1_L05_basic','lesson_basic','M5-1-u1-C5',1,'mc','auto','18 + 12 ÷ 3을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X04','M5-1-u1-X10']::text[],true,'{"seq":3,"concept":"M5-1-u1-C5","difficulty":1,"kind":"mc","stem":"18 + 12 ÷ 3을 계산하면 얼마인가요?","options":[{"t":"22","correct":true},{"t":"10","mis":"M5-1-u1-X04"},{"t":"32","mis":"M5-1-u1-X10"},{"t":"12","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 12 ÷ 3 = 4 → ② 18 + 4 = 22예요.","그래서 18 + 12 ÷ 3 = 22예요."],"variant_rule":{"alt":[{"stem":"25 + 40 ÷ 8을 계산하면 얼마인가요?","options":[{"t":"30","correct":true},{"t":"40","mis":"M5-1-u1-X10"},{"t":"20","mis":"M5-1-u1-X10"},{"t":"32","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 40 ÷ 8 = 5 → ② 25 + 5 = 30이에요.","그래서 25 + 40 ÷ 8 = 30이에요."]},{"stem":"14 + 63 ÷ 7을 계산하면 얼마인가요?","options":[{"t":"23","correct":true},{"t":"11","mis":"M5-1-u1-X04"},{"t":"33","mis":"M5-1-u1-X10"},{"t":"13","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 63 ÷ 7 = 9 → ② 14 + 9 = 23이에요.","그래서 14 + 63 ÷ 7 = 23이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_basic#4','math',5,1,'u1','L05','g5_1_math_u1_L05_basic','lesson_basic','M5-1-u1-C5',1,'mc','auto','리본 50 cm 가운데 32 cm를 4조각으로 똑같이 잘라 한 조각을 썼어요. 남은 리본의 길이를 구하는 식은 어느 것인가요?',ARRAY['M5-1-u1-X04','M5-1-u1-X09']::text[],true,'{"seq":4,"concept":"M5-1-u1-C5","difficulty":1,"kind":"mc","stem":"리본 50 cm 가운데 32 cm를 4조각으로 똑같이 잘라 한 조각을 썼어요. 남은 리본의 길이를 구하는 식은 어느 것인가요?","options":[{"t":"50 − 32 ÷ 4","correct":true},{"t":"(50 − 32) ÷ 4","mis":"M5-1-u1-X04"},{"t":"50 − 32 × 4","mis":"M5-1-u1-X09"},{"t":"50 ÷ 4 − 32","mis":"M5-1-u1-X09"}],"explanation":["쓴 한 조각은 32 ÷ 4예요.","그것을 50 cm에서 빼요.","50 − 32 ÷ 4예요."],"variant_rule":{"alt":[{"stem":"끈 60 cm 가운데 36 cm를 6조각으로 똑같이 잘라 한 조각을 썼어요. 남은 끈의 길이를 구하는 식은 어느 것인가요?","options":[{"t":"60 − 36 ÷ 6","correct":true},{"t":"(60 − 36) ÷ 6","mis":"M5-1-u1-X04"},{"t":"60 − 36 × 6","mis":"M5-1-u1-X09"},{"t":"60 ÷ 6 − 36","mis":"M5-1-u1-X09"}],"explanation":["쓴 한 조각은 36 ÷ 6이에요.","60 cm에서 빼요.","60 − 36 ÷ 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_basic#5','math',5,1,'u1','L05','g5_1_math_u1_L05_basic','lesson_basic','M5-1-u1-C5',2,'sa','auto','리본 50 cm 가운데 32 cm를 4조각으로 똑같이 잘라 한 조각을 썼어요. 남은 리본은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-1-u1-C5","difficulty":2,"kind":"sa","stem":"리본 50 cm 가운데 32 cm를 4조각으로 똑같이 잘라 한 조각을 썼어요. 남은 리본은 몇 cm인가요? 숫자로 쓰세요.","answer":["42","42cm","42 cm"],"explanation":["50 − 32 ÷ 4에서 나눗셈을 먼저 해요.","32 ÷ 4 = 8, 50 − 8 = 42.","남은 리본은 42 cm예요."],"variant_rule":{"alt":[{"stem":"끈 60 cm 가운데 36 cm를 6조각으로 똑같이 잘라 한 조각을 썼어요. 남은 끈은 몇 cm인가요? 숫자로 쓰세요.","answer":["54","54cm","54 cm"],"explanation":["60 − 36 ÷ 6에서 나눗셈을 먼저 해요.","36 ÷ 6 = 6, 60 − 6 = 54.","54 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_basic#6','math',5,1,'u1','L05','g5_1_math_u1_L05_basic','lesson_basic','M5-1-u1-C5',2,'error','auto','민재는 18 + 12 ÷ 3을 계산해 10이라고 답했어요. 민재가 잘못한 것은 무엇인가요?',ARRAY['M5-1-u1-X04','M5-1-u1-X10','M5-1-u1-X14']::text[],true,'{"seq":6,"concept":"M5-1-u1-C5","difficulty":2,"kind":"error","stem":"민재는 18 + 12 ÷ 3을 계산해 10이라고 답했어요. 민재가 잘못한 것은 무엇인가요?","options":[{"t":"앞의 18 + 12를 먼저 했다","correct":true,"mis_target":"M5-1-u1-X04"},{"t":"12 ÷ 3을 잘못 나눴다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["덧셈에 나눗셈이 섞이면 나눗셈을 먼저 해요.","12 ÷ 3 = 4, 18 + 4 = 22가 맞아요.","민재는 18 + 12 = 30을 먼저 해서 30 ÷ 3 = 10이 나왔어요."],"variant_rule":{"alt":[{"stem":"소율이는 20 + 16 ÷ 4를 계산해 9라고 답했어요. 소율이가 잘못한 것은 무엇인가요?","options":[{"t":"앞의 20 + 16을 먼저 했다","correct":true,"mis_target":"M5-1-u1-X04"},{"t":"16 ÷ 4를 잘못 나눴다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["나눗셈을 먼저 해요.","16 ÷ 4 = 4, 20 + 4 = 24가 맞아요.","소율이는 20 + 16 = 36을 먼저 해서 36 ÷ 4 = 9가 나왔어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_basic#7','math',5,1,'u1','L05','g5_1_math_u1_L05_basic','lesson_basic','M5-1-u1-C5',2,'ox','auto','덧셈·뺄셈에 곱셈이 섞이면 곱셈이 먼저지만, 나눗셈은 덧셈·뺄셈보다 나중에 계산해요.',ARRAY['M5-1-u1-X05']::text[],false,'{"seq":7,"concept":"M5-1-u1-C5","difficulty":2,"kind":"ox","stem":"덧셈·뺄셈에 곱셈이 섞이면 곱셈이 먼저지만, 나눗셈은 덧셈·뺄셈보다 나중에 계산해요.","answer":"X","reason_options":[{"t":"곱셈과 나눗셈은 같은 자리라서 덧셈·뺄셈보다 함께 먼저 계산해서","correct":true},{"t":"나눗셈은 언제나 가장 나중에 하는 계산이라서","mis":"M5-1-u1-X05"}],"mis":"M5-1-u1-X05","explanation":["곱셈과 나눗셈은 서로를 되돌리는 같은 자리의 계산이에요.","그래서 덧셈·뺄셈보다 함께 먼저 와요.","예: 30 − 24 ÷ 6 = 30 − 4 = 26이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_basic#8','math',5,1,'u1','L05','g5_1_math_u1_L05_basic','lesson_basic','M5-1-u1-C5',2,'match','auto','계산식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u1-C5","difficulty":2,"kind":"match","stem":"계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"40 − 28 ÷ 4","r":"33"},{"l":"15 + 54 ÷ 9","r":"21"},{"l":"72 ÷ 8 + 6","r":"15"}],"mis":"M5-1-u1-X04","explanation":["식마다 계산 순서를 지켜 셈해요.","40 − 28 ÷ 4 = 33 · 15 + 54 ÷ 9 = 21 · 72 ÷ 8 + 6 = 15","곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"36 − 42 ÷ 7","r":"30"},{"l":"19 + 48 ÷ 6","r":"27"},{"l":"64 ÷ 8 − 5","r":"3"}],"explanation":["식마다 계산 순서를 지켜 셈해요.","36 − 42 ÷ 7 = 30 · 19 + 48 ÷ 6 = 27 · 64 ÷ 8 − 5 = 3","곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_basic#9','math',5,1,'u1','L05','g5_1_math_u1_L05_basic','lesson_basic','M5-1-u1-C5',2,'mc','auto','56 − 42 ÷ 7 + 9를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X04','M5-1-u1-X01','M5-1-u1-X10']::text[],true,'{"seq":9,"concept":"M5-1-u1-C5","difficulty":2,"kind":"mc","stem":"56 − 42 ÷ 7 + 9를 계산하면 얼마인가요?","options":[{"t":"59","correct":true},{"t":"11","mis":"M5-1-u1-X04"},{"t":"41","mis":"M5-1-u1-X01"},{"t":"69","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 42 ÷ 7 = 6 → ② 56 − 6 = 50 → ③ 50 + 9 = 59예요.","그래서 56 − 42 ÷ 7 + 9 = 59예요."],"variant_rule":{"alt":[{"stem":"63 + 81 ÷ 9 − 20을 계산하면 얼마인가요?","options":[{"t":"52","correct":true},{"t":"62","mis":"M5-1-u1-X10"},{"t":"42","mis":"M5-1-u1-X10"},{"t":"54","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 81 ÷ 9 = 9 → ② 63 + 9 = 72 → ③ 72 − 20 = 52예요.","그래서 63 + 81 ÷ 9 − 20 = 52예요."]},{"stem":"45 − 36 ÷ 4 + 8을 계산하면 얼마인가요?","options":[{"t":"44","correct":true},{"t":"28","mis":"M5-1-u1-X01"},{"t":"54","mis":"M5-1-u1-X10"},{"t":"34","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 36 ÷ 4 = 9 → ② 45 − 9 = 36 → ③ 36 + 8 = 44예요.","그래서 45 − 36 ÷ 4 + 8 = 44예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_basic#10','math',5,1,'u1','L05','g5_1_math_u1_L05_basic','lesson_basic','M5-1-u1-C5',3,'mc','auto','40 − 16 ÷ 4와 (40 − 16) ÷ 4의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],true,'{"seq":10,"concept":"M5-1-u1-C5","difficulty":3,"kind":"mc","stem":"40 − 16 ÷ 4와 (40 − 16) ÷ 4의 계산 결과의 차는 얼마인가요?","options":[{"t":"30","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"36","mis":"M5-1-u1-X14"},{"t":"6","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","40 − 16 ÷ 4 = 36 · (40 − 16) ÷ 4 = 6","두 결과의 차는 36 − 6 = 30이에요."],"variant_rule":{"alt":[{"stem":"50 − 20 ÷ 5와 (50 − 20) ÷ 5의 계산 결과의 차는 얼마인가요?","options":[{"t":"40","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"46","mis":"M5-1-u1-X14"},{"t":"6","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","50 − 20 ÷ 5 = 46 · (50 − 20) ÷ 5 = 6","두 결과의 차는 46 − 6 = 40이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_challenge#1','math',5,1,'u1','L05','g5_1_math_u1_L05_challenge','lesson_challenge','M5-1-u1-C5',2,'mc','auto','84 ÷ 7 + 96 ÷ 8 − 5를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X10']::text[],true,'{"seq":1,"concept":"M5-1-u1-C5","difficulty":2,"kind":"mc","stem":"84 ÷ 7 + 96 ÷ 8 − 5를 계산하면 얼마인가요?","options":[{"t":"19","correct":true},{"t":"29","mis":"M5-1-u1-X10"},{"t":"9","mis":"M5-1-u1-X10"},{"t":"21","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 84 ÷ 7 = 12 → ② 96 ÷ 8 = 12 → ③ 12 + 12 = 24 → ④ 24 − 5 = 19예요.","그래서 84 ÷ 7 + 96 ÷ 8 − 5 = 19예요."],"variant_rule":{"alt":[{"stem":"72 ÷ 6 + 45 ÷ 9 − 8을 계산하면 얼마인가요?","options":[{"t":"9","correct":true},{"t":"19","mis":"M5-1-u1-X10"},{"t":"11","mis":"M5-1-u1-X10"},{"t":"7","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 72 ÷ 6 = 12 → ② 45 ÷ 9 = 5 → ③ 12 + 5 = 17 → ④ 17 − 8 = 9예요.","그래서 72 ÷ 6 + 45 ÷ 9 − 8 = 9예요."]},{"stem":"60 ÷ 4 − 36 ÷ 6 + 11을 계산하면 얼마인가요?","options":[{"t":"20","correct":true},{"t":"30","mis":"M5-1-u1-X10"},{"t":"10","mis":"M5-1-u1-X10"},{"t":"22","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 60 ÷ 4 = 15 → ② 36 ÷ 6 = 6 → ③ 15 − 6 = 9 → ④ 9 + 11 = 20이에요.","그래서 60 ÷ 4 − 36 ÷ 6 + 11 = 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_challenge#2','math',5,1,'u1','L05','g5_1_math_u1_L05_challenge','lesson_challenge','M5-1-u1-C5',2,'mc','auto','「곱셈은 먼저지만 나눗셈은 나중이야.」라는 말을 바르게 판단한 것은 어느 것인가요?',ARRAY['M5-1-u1-X05','M5-1-u1-X04']::text[],false,'{"seq":2,"concept":"M5-1-u1-C5","difficulty":2,"kind":"mc","stem":"「곱셈은 먼저지만 나눗셈은 나중이야.」라는 말을 바르게 판단한 것은 어느 것인가요?","options":[{"t":"틀리다 · 곱셈과 나눗셈은 함께 먼저다","correct":true},{"t":"맞다 · 나눗셈은 가장 나중이다","mis":"M5-1-u1-X05"},{"t":"맞다 · 나눗셈은 앞에서부터 순서대로다","mis":"M5-1-u1-X04"},{"t":"틀리다 · 나눗셈이 곱셈보다 먼저다","mis":"M5-1-u1-X05"}],"explanation":["곱셈과 나눗셈은 같은 자리의 계산이에요.","덧셈·뺄셈과 섞이면 둘이 함께 먼저 와요.","둘끼리는 앞에서부터 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_challenge#3','math',5,1,'u1','L05','g5_1_math_u1_L05_challenge','lesson_challenge','M5-1-u1-C5',3,'mc','auto','□ − 36 ÷ 9 = 20에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X04']::text[],true,'{"seq":3,"concept":"M5-1-u1-C5","difficulty":3,"kind":"mc","stem":"□ − 36 ÷ 9 = 20에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"24","correct":true},{"t":"56","mis":"M5-1-u1-X13"},{"t":"16","mis":"M5-1-u1-X13"},{"t":"216","mis":"M5-1-u1-X04"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 20이 되어야 해요.","거꾸로 되돌리면 □ = 24예요.","확인: 24 − 36 ÷ 9 → ① 36 ÷ 9 = 4 → ② 24 − 4 = 20"],"variant_rule":{"alt":[{"stem":"□ − 28 ÷ 7 = 15에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"19","correct":true},{"t":"43","mis":"M5-1-u1-X13"},{"t":"11","mis":"M5-1-u1-X13"},{"t":"133","mis":"M5-1-u1-X04"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 15가 되어야 해요.","거꾸로 되돌리면 □ = 19예요.","확인: 19 − 28 ÷ 7 → ① 28 ÷ 7 = 4 → ② 19 − 4 = 15"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_challenge#4','math',5,1,'u1','L05','g5_1_math_u1_L05_challenge','lesson_challenge','M5-1-u1-C5',3,'mc','auto','사과 48개를 6상자에 똑같이 나누어 담았어요. 한 상자에서 사과 3개를 꺼냈다면 그 상자에 남은 사과는 몇 개인가요?',ARRAY['M5-1-u1-X09','M5-1-u1-X04','M5-1-u1-X10']::text[],true,'{"seq":4,"concept":"M5-1-u1-C5","difficulty":3,"kind":"mc","stem":"사과 48개를 6상자에 똑같이 나누어 담았어요. 한 상자에서 사과 3개를 꺼냈다면 그 상자에 남은 사과는 몇 개인가요?","options":[{"t":"5개","correct":true},{"t":"15개","mis":"M5-1-u1-X09"},{"t":"45개","mis":"M5-1-u1-X04"},{"t":"7개","mis":"M5-1-u1-X10"}],"explanation":["한 상자의 사과는 48 ÷ 6이에요.","거기서 3개를 빼니 48 ÷ 6 − 3이에요.","나눗셈 먼저 — 48 ÷ 6 = 8, 8 − 3 = 5개예요."],"variant_rule":{"alt":[{"stem":"구슬 63개를 7봉지에 똑같이 나누어 담았어요. 한 봉지에서 구슬 4개를 꺼냈다면 그 봉지에 남은 구슬은 몇 개인가요?","options":[{"t":"5개","correct":true},{"t":"23개","mis":"M5-1-u1-X09"},{"t":"59개","mis":"M5-1-u1-X04"},{"t":"7개","mis":"M5-1-u1-X10"}],"explanation":["한 봉지의 구슬은 63 ÷ 7이에요.","거기서 4개를 빼니 63 ÷ 7 − 4예요.","63 ÷ 7 = 9, 9 − 4 = 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_challenge#5','math',5,1,'u1','L05','g5_1_math_u1_L05_challenge','lesson_challenge','M5-1-u1-C5',3,'error','auto','「50 − 32 ÷ 4」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u1-X04','M5-1-u1-X14']::text[],false,'{"seq":5,"concept":"M5-1-u1-C5","difficulty":3,"kind":"error","stem":"「50 − 32 ÷ 4」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「50 − 32 = 18을 먼저 하고 4로 나누면 돼.」","correct":true,"mis_target":"M5-1-u1-X04"},{"t":"채아 — 「32 ÷ 4는 한 조각의 길이라 먼저 구해.」","mis":"M5-1-u1-X14"},{"t":"시우 — 「32 ÷ 4 = 8, 50 − 8 = 42야.」","mis":"M5-1-u1-X14"}],"explanation":["덧셈·뺄셈에 나눗셈이 섞이면 나눗셈이 먼저예요.","32 ÷ 4 = 8, 50 − 8 = 42예요.","하준이처럼 하면 18 ÷ 4로 나누어떨어지지도 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_challenge#6','math',5,1,'u1','L05','g5_1_math_u1_L05_challenge','lesson_challenge','M5-1-u1-C5',3,'mc','auto','36 + 24 ÷ 6과 (36 + 24) ÷ 6의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],true,'{"seq":6,"concept":"M5-1-u1-C5","difficulty":3,"kind":"mc","stem":"36 + 24 ÷ 6과 (36 + 24) ÷ 6의 계산 결과의 차는 얼마인가요?","options":[{"t":"30","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"40","mis":"M5-1-u1-X14"},{"t":"10","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","36 + 24 ÷ 6 = 40 · (36 + 24) ÷ 6 = 10","두 결과의 차는 40 − 10 = 30이에요."],"variant_rule":{"alt":[{"stem":"45 + 27 ÷ 9와 (45 + 27) ÷ 9의 계산 결과의 차는 얼마인가요?","options":[{"t":"40","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"48","mis":"M5-1-u1-X14"},{"t":"8","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","45 + 27 ÷ 9 = 48 · (45 + 27) ÷ 9 = 8","두 결과의 차는 48 − 8 = 40이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_challenge#7','math',5,1,'u1','L05','g5_1_math_u1_L05_challenge','lesson_challenge','M5-1-u1-C5',3,'mc','auto','다음 중 계산 결과가 가장 작은 것은 어느 것인가요?',ARRAY['M5-1-u1-X14']::text[],false,'{"seq":7,"concept":"M5-1-u1-C5","difficulty":3,"kind":"mc","stem":"다음 중 계산 결과가 가장 작은 것은 어느 것인가요?","options":[{"t":"(40 − 16) ÷ 4","correct":true},{"t":"40 − 16 ÷ 4","mis":"M5-1-u1-X14"},{"t":"40 ÷ 4 + 16","mis":"M5-1-u1-X14"},{"t":"16 ÷ 4 + 40","mis":"M5-1-u1-X14"}],"explanation":["식마다 계산 순서를 지켜 셈해요.","(40 − 16) ÷ 4 = 6 · 40 − 16 ÷ 4 = 36 · 40 ÷ 4 + 16 = 26 · 16 ÷ 4 + 40 = 44.","가장 작은 것은 (40 − 16) ÷ 4 = 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_challenge#8','math',5,1,'u1','L05','g5_1_math_u1_L05_challenge','lesson_challenge','M5-1-u1-C5',4,'essay','teacher','리본 50 cm 가운데 32 cm를 4조각으로 똑같이 잘라 한 조각을 썼어요. 50 − 32 ÷ 4를 앞에서부터 계산하면 왜 이야기와 맞지 않는지, 바른 답은 무엇인지 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u1-C5","difficulty":4,"kind":"essay","stem":"리본 50 cm 가운데 32 cm를 4조각으로 똑같이 잘라 한 조각을 썼어요. 50 − 32 ÷ 4를 앞에서부터 계산하면 왜 이야기와 맞지 않는지, 바른 답은 무엇인지 설명하세요.","answer_guide":{"answer":"예: 앞에서부터 하면 50 − 32 = 18, 18 ÷ 4로 나누어떨어지지도 않고 이야기와 맞지 않는다. 32 ÷ 4는 잘라 쓴 한 조각의 길이 8 cm라는 하나의 양이므로 먼저 구한다. 50 − 8 = 42 cm가 남는다.","scoring_points":["앞에서부터 하면 이야기와 맞지 않음을 보였는가","32 ÷ 4가 하나의 양(한 조각의 길이)임을 설명했는가","42 cm를 구했는가"]},"explanation":["앞에서부터 하면 18 ÷ 4가 되어 이상해요.","32 ÷ 4 = 8 cm는 쓴 한 조각의 길이예요.","50 − 8 = 42 cm가 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_challenge#9','math',5,1,'u1','L05','g5_1_math_u1_L05_challenge','lesson_challenge','M5-1-u1-C5',4,'essay','teacher','30 − 24 ÷ 6과 (30 − 24) ÷ 6을 각각 계산하고, 두 식이 어떤 상황을 나타내는지 하나씩 지어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u1-C5","difficulty":4,"kind":"essay","stem":"30 − 24 ÷ 6과 (30 − 24) ÷ 6을 각각 계산하고, 두 식이 어떤 상황을 나타내는지 하나씩 지어 쓰세요.","answer_guide":{"answer":"예: 30 − 24 ÷ 6 = 30 − 4 = 26, (30 − 24) ÷ 6 = 6 ÷ 6 = 1. 첫째 식은 「구슬 30개 가운데, 24개를 6명에게 나눈 한 사람 몫만큼 덜어 냈다」, 둘째 식은 「구슬 30개 가운데 24개를 쓰고 남은 것을 6명이 똑같이 나눴다」를 나타낸다.","scoring_points":["26을 구했는가","1을 구했는가","두 식에 맞는 상황을 각각 지었는가"]},"explanation":["30 − 24 ÷ 6 = 30 − 4 = 26이에요.","(30 − 24) ÷ 6 = 6 ÷ 6 = 1이에요.","( )가 있으면 묶인 것이 한 덩어리인 상황이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L05_challenge#10','math',5,1,'u1','L05','g5_1_math_u1_L05_challenge','lesson_challenge','M5-1-u1-C5',4,'mc','auto','어떤 수를 8로 나눈 다음 16을 더해야 할 것을 잘못하여 16을 더한 다음 8로 나누었더니 7이 되었어요. 바르게 계산하면 얼마인가요?',ARRAY['M5-1-u1-X14','M5-1-u1-X13']::text[],false,'{"seq":10,"concept":"M5-1-u1-C5","difficulty":4,"kind":"mc","stem":"어떤 수를 8로 나눈 다음 16을 더해야 할 것을 잘못하여 16을 더한 다음 8로 나누었더니 7이 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"21","correct":true},{"t":"7","mis":"M5-1-u1-X14"},{"t":"40","mis":"M5-1-u1-X13"},{"t":"56","mis":"M5-1-u1-X13"}],"explanation":["잘못 계산한 식은 (□ + 16) ÷ 8 = 7 — 거꾸로 7 × 8 = 56, 56 − 16 = 40이에요.","어떤 수는 40이에요.","바르게 계산하면 40 ÷ 8 + 16 = 5 + 16 = 21이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_basic#1','math',5,1,'u1','L06','g5_1_math_u1_L06_basic','lesson_basic','M5-1-u1-C6',1,'mc','auto','100 − (30 + 45)에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X01']::text[],true,'{"seq":1,"concept":"M5-1-u1-C6","difficulty":1,"kind":"mc","stem":"100 − (30 + 45)에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"30 + 45","correct":true},{"t":"100 − 30","mis":"M5-1-u1-X06"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X01"}],"explanation":["( ) 안을 가장 먼저 계산해요.","그래서 가장 먼저 계산할 것은 30 + 45예요.","① 30 + 45 = 75 → ② 100 − 75 = 25예요."],"variant_rule":{"alt":[{"stem":"60 − (18 + 22)에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"18 + 22","correct":true},{"t":"60 − 18","mis":"M5-1-u1-X06"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X01"}],"explanation":["( ) 안을 가장 먼저 계산해요.","가장 먼저 계산할 것은 18 + 22예요.","① 18 + 22 = 40 → ② 60 − 40 = 20이에요."]},{"stem":"80 − (35 − 15)에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"35 − 15","correct":true},{"t":"80 − 35","mis":"M5-1-u1-X06"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X01"}],"explanation":["( ) 안을 가장 먼저 계산해요.","가장 먼저 계산할 것은 35 − 15예요.","① 35 − 15 = 20 → ② 80 − 20 = 60이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_basic#2','math',5,1,'u1','L06','g5_1_math_u1_L06_basic','lesson_basic','M5-1-u1-C6',1,'mc','auto','100 − (30 + 45)를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X10']::text[],true,'{"seq":2,"concept":"M5-1-u1-C6","difficulty":1,"kind":"mc","stem":"100 − (30 + 45)를 계산하면 얼마인가요?","options":[{"t":"25","correct":true},{"t":"115","mis":"M5-1-u1-X06"},{"t":"35","mis":"M5-1-u1-X10"},{"t":"15","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요.","① 30 + 45 = 75 → ② 100 − 75 = 25예요.","그래서 100 − (30 + 45) = 25예요."],"variant_rule":{"alt":[{"stem":"90 − (27 + 38)을 계산하면 얼마인가요?","options":[{"t":"25","correct":true},{"t":"101","mis":"M5-1-u1-X06"},{"t":"35","mis":"M5-1-u1-X10"},{"t":"15","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요.","① 27 + 38 = 65 → ② 90 − 65 = 25예요.","그래서 90 − (27 + 38) = 25예요."]},{"stem":"75 − (40 − 16)을 계산하면 얼마인가요?","options":[{"t":"51","correct":true},{"t":"19","mis":"M5-1-u1-X06"},{"t":"61","mis":"M5-1-u1-X10"},{"t":"41","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요.","① 40 − 16 = 24 → ② 75 − 24 = 51이에요.","그래서 75 − (40 − 16) = 51이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_basic#3','math',5,1,'u1','L06','g5_1_math_u1_L06_basic','lesson_basic','M5-1-u1-C6',1,'sa','auto','(12 + 8) ÷ 5를 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-1-u1-C6","difficulty":1,"kind":"sa","stem":"(12 + 8) ÷ 5를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 12 + 8 = 20 → ② 20 ÷ 5 = 4예요.","그래서 (12 + 8) ÷ 5 = 4예요."],"variant_rule":{"alt":[{"stem":"(15 + 21) ÷ 4를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 15 + 21 = 36 → ② 36 ÷ 4 = 9예요.","그래서 (15 + 21) ÷ 4 = 9예요."]},{"stem":"(30 − 6) ÷ 8을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 30 − 6 = 24 → ② 24 ÷ 8 = 3이에요.","그래서 (30 − 6) ÷ 8 = 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_basic#4','math',5,1,'u1','L06','g5_1_math_u1_L06_basic','lesson_basic','M5-1-u1-C6',1,'mc','auto','예서는 3000원을 들고 편의점에 가서 800원짜리 우유와 700원짜리 빵을 함께 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u1-X09','M5-1-u1-X06']::text[],true,'{"seq":4,"concept":"M5-1-u1-C6","difficulty":1,"kind":"mc","stem":"예서는 3000원을 들고 편의점에 가서 800원짜리 우유와 700원짜리 빵을 함께 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3000 − (800 + 700)","correct":true},{"t":"3000 − 800 + 700","mis":"M5-1-u1-X09"},{"t":"3000 + (800 − 700)","mis":"M5-1-u1-X09"},{"t":"(3000 − 800) + 700","mis":"M5-1-u1-X06"}],"explanation":["우유와 빵을 함께 샀으니 물건값은 800 + 700 — 한 묶음이에요.","그 묶음을 3000원에서 빼요.","묶음은 ( )로 나타내 3000 − (800 + 700)이에요."],"variant_rule":{"alt":[{"stem":"도윤이는 5000원으로 1200원짜리 공책과 900원짜리 연필을 함께 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"5000 − (1200 + 900)","correct":true},{"t":"5000 − 1200 + 900","mis":"M5-1-u1-X09"},{"t":"5000 + (1200 − 900)","mis":"M5-1-u1-X09"},{"t":"(5000 − 1200) + 900","mis":"M5-1-u1-X06"}],"explanation":["함께 산 두 물건값 1200 + 900이 한 묶음이에요.","그 묶음을 5000원에서 빼요.","5000 − (1200 + 900)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_basic#5','math',5,1,'u1','L06','g5_1_math_u1_L06_basic','lesson_basic','M5-1-u1-C6',2,'mc','auto','3000 − (800 + 700)을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X10']::text[],false,'{"seq":5,"concept":"M5-1-u1-C6","difficulty":2,"kind":"mc","stem":"3000 − (800 + 700)을 계산하면 얼마인가요?","options":[{"t":"1500","correct":true},{"t":"2900","mis":"M5-1-u1-X06"},{"t":"3100","mis":"M5-1-u1-X10"},{"t":"1600","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 — 800 + 700 = 1500.","3000 − 1500 = 1500이에요.","( )를 빼고 앞에서부터 하면 2900으로 빵값을 더해 버린 셈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_basic#6','math',5,1,'u1','L06','g5_1_math_u1_L06_basic','lesson_basic','M5-1-u1-C6',2,'mc','auto','두 식의 계산 결과가 서로 다른 것은 어느 것인가요?',ARRAY['M5-1-u1-X14']::text[],false,'{"seq":6,"concept":"M5-1-u1-C6","difficulty":2,"kind":"mc","stem":"두 식의 계산 결과가 서로 다른 것은 어느 것인가요?","options":[{"t":"24 ÷ (4 + 2)와 24 ÷ 4 + 2","correct":true},{"t":"12 + (5 + 3)과 12 + 5 + 3","mis":"M5-1-u1-X14"},{"t":"20 − (6 − 1)과 20 − 6 + 1","mis":"M5-1-u1-X14"},{"t":"9 × (2 × 3)과 9 × 2 × 3","mis":"M5-1-u1-X14"}],"explanation":["24 ÷ (4 + 2) = 4, 24 ÷ 4 + 2 = 8로 서로 달라요.","12 + 8 = 20 = 12 + 5 + 3, 20 − 5 = 15 = 20 − 6 + 1, 9 × 6 = 54 = 9 × 2 × 3은 같아요.","그래서 다른 것은 24 ÷ (4 + 2)와 24 ÷ 4 + 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_basic#7','math',5,1,'u1','L06','g5_1_math_u1_L06_basic','lesson_basic','M5-1-u1-C6',2,'ox','auto','( )는 그냥 외워야 하는 규칙이라서, ( )가 있어도 곱셈·나눗셈을 먼저 해요.',ARRAY['M5-1-u1-X07']::text[],false,'{"seq":7,"concept":"M5-1-u1-C6","difficulty":2,"kind":"ox","stem":"( )는 그냥 외워야 하는 규칙이라서, ( )가 있어도 곱셈·나눗셈을 먼저 해요.","answer":"X","reason_options":[{"t":"( )는 여기까지가 한 덩어리라는 표현이라 곱셈·나눗셈보다도 먼저 계산해서","correct":true},{"t":"( ) 안은 곱셈·나눗셈 다음에 하는 계산이라서","mis":"M5-1-u1-X07"}],"mis":"M5-1-u1-X07","explanation":["( )는 상황이 이미 그렇게 묶여 있다는 것을 식에 그려 넣은 표현이에요.","그래서 ( ) 안을 가장 먼저 계산해요.","곱셈·나눗셈보다도 ( )가 앞이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_basic#8','math',5,1,'u1','L06','g5_1_math_u1_L06_basic','lesson_basic','M5-1-u1-C6',2,'match','auto','계산식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u1-C6","difficulty":2,"kind":"match","stem":"계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"(7 + 5) × 3","r":"36"},{"l":"7 + 5 × 3","r":"22"},{"l":"(20 − 8) ÷ 4","r":"3"}],"mis":"M5-1-u1-X06","explanation":["식마다 계산 순서를 지켜 셈해요.","(7 + 5) × 3 = 36 · 7 + 5 × 3 = 22 · (20 − 8) ÷ 4 = 3","( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"(9 + 3) × 4","r":"48"},{"l":"9 + 3 × 4","r":"21"},{"l":"(30 − 6) ÷ 6","r":"4"}],"explanation":["식마다 계산 순서를 지켜 셈해요.","(9 + 3) × 4 = 48 · 9 + 3 × 4 = 21 · (30 − 6) ÷ 6 = 4","( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_basic#9','math',5,1,'u1','L06','g5_1_math_u1_L06_basic','lesson_basic','M5-1-u1-C6',2,'mc','auto','6 × (13 − 5)를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X10']::text[],true,'{"seq":9,"concept":"M5-1-u1-C6","difficulty":2,"kind":"mc","stem":"6 × (13 − 5)를 계산하면 얼마인가요?","options":[{"t":"48","correct":true},{"t":"73","mis":"M5-1-u1-X06"},{"t":"58","mis":"M5-1-u1-X10"},{"t":"38","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 13 − 5 = 8 → ② 6 × 8 = 48이에요.","그래서 6 × (13 − 5) = 48이에요."],"variant_rule":{"alt":[{"stem":"8 × (11 − 4)를 계산하면 얼마인가요?","options":[{"t":"56","correct":true},{"t":"84","mis":"M5-1-u1-X06"},{"t":"66","mis":"M5-1-u1-X10"},{"t":"46","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 11 − 4 = 7 → ② 8 × 7 = 56이에요.","그래서 8 × (11 − 4) = 56이에요."]},{"stem":"7 × (12 − 9)를 계산하면 얼마인가요?","options":[{"t":"21","correct":true},{"t":"75","mis":"M5-1-u1-X06"},{"t":"31","mis":"M5-1-u1-X10"},{"t":"11","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 12 − 9 = 3 → ② 7 × 3 = 21이에요.","그래서 7 × (12 − 9) = 21이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_basic#10','math',5,1,'u1','L06','g5_1_math_u1_L06_basic','lesson_basic','M5-1-u1-C6',3,'mc','auto','24 ÷ (4 + 2)와 24 ÷ 4 + 2의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14','M5-1-u1-X10']::text[],true,'{"seq":10,"concept":"M5-1-u1-C6","difficulty":3,"kind":"mc","stem":"24 ÷ (4 + 2)와 24 ÷ 4 + 2의 계산 결과의 차는 얼마인가요?","options":[{"t":"4","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"8","mis":"M5-1-u1-X14"},{"t":"14","mis":"M5-1-u1-X10"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","24 ÷ (4 + 2) = 4 · 24 ÷ 4 + 2 = 8","두 결과의 차는 8 − 4 = 4예요."],"variant_rule":{"alt":[{"stem":"36 ÷ (6 + 3)과 36 ÷ 6 + 3의 계산 결과의 차는 얼마인가요?","options":[{"t":"5","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"4","mis":"M5-1-u1-X14"},{"t":"9","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","36 ÷ (6 + 3) = 4 · 36 ÷ 6 + 3 = 9","두 결과의 차는 9 − 4 = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_challenge#1','math',5,1,'u1','L06','g5_1_math_u1_L06_challenge','lesson_challenge','M5-1-u1-C6',2,'mc','auto','72 ÷ (3 × 4) + 5를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X10']::text[],true,'{"seq":1,"concept":"M5-1-u1-C6","difficulty":2,"kind":"mc","stem":"72 ÷ (3 × 4) + 5를 계산하면 얼마인가요?","options":[{"t":"11","correct":true},{"t":"101","mis":"M5-1-u1-X06"},{"t":"21","mis":"M5-1-u1-X10"},{"t":"1","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 3 × 4 = 12 → ② 72 ÷ 12 = 6 → ③ 6 + 5 = 11이에요.","그래서 72 ÷ (3 × 4) + 5 = 11이에요."],"variant_rule":{"alt":[{"stem":"96 ÷ (2 × 8) + 7을 계산하면 얼마인가요?","options":[{"t":"13","correct":true},{"t":"391","mis":"M5-1-u1-X06"},{"t":"23","mis":"M5-1-u1-X10"},{"t":"3","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 2 × 8 = 16 → ② 96 ÷ 16 = 6 → ③ 6 + 7 = 13이에요.","그래서 96 ÷ (2 × 8) + 7 = 13이에요."]},{"stem":"84 ÷ (2 × 6) − 3을 계산하면 얼마인가요?","options":[{"t":"4","correct":true},{"t":"249","mis":"M5-1-u1-X06"},{"t":"14","mis":"M5-1-u1-X10"},{"t":"6","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 2 × 6 = 12 → ② 84 ÷ 12 = 7 → ③ 7 − 3 = 4예요.","그래서 84 ÷ (2 × 6) − 3 = 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_challenge#2','math',5,1,'u1','L06','g5_1_math_u1_L06_challenge','lesson_challenge','M5-1-u1-C6',2,'mc','auto','「( )는 그냥 먼저 하라는 규칙일 뿐이야.」라는 말을 가장 알맞게 설명한 것은 어느 것인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X07']::text[],false,'{"seq":2,"concept":"M5-1-u1-C6","difficulty":2,"kind":"mc","stem":"「( )는 그냥 먼저 하라는 규칙일 뿐이야.」라는 말을 가장 알맞게 설명한 것은 어느 것인가요?","options":[{"t":"틀리다 · ( )는 한 덩어리임을 알려 주는 표현이다","correct":true},{"t":"맞다 · 외워 두면 되는 규칙이다","mis":"M5-1-u1-X06"},{"t":"맞다 · ( ) 안은 곱셈보다 나중이다","mis":"M5-1-u1-X07"},{"t":"틀리다 · ( )가 있어도 답은 같다","mis":"M5-1-u1-X06"}],"explanation":["( )는 새로 외울 규칙이 아니에요.","「여기까지가 한 덩어리」라는 것을 식에 그려 넣은 표현이에요.","그래서 ( ) 안을 가장 먼저 계산해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_challenge#3','math',5,1,'u1','L06','g5_1_math_u1_L06_challenge','lesson_challenge','M5-1-u1-C6',3,'mc','auto','30 − 12 ÷ 3에 ( )를 넣어 계산 결과가 6이 되게 하려면 어떻게 넣어야 하나요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],true,'{"seq":3,"concept":"M5-1-u1-C6","difficulty":3,"kind":"mc","stem":"30 − 12 ÷ 3에 ( )를 넣어 계산 결과가 6이 되게 하려면 어떻게 넣어야 하나요?","options":[{"t":"(30 − 12) ÷ 3","correct":true},{"t":"30 − (12 ÷ 3)","mis":"M5-1-u1-X06"},{"t":"(30) − 12 ÷ 3","mis":"M5-1-u1-X06"},{"t":"( )를 넣을 수 없다","mis":"M5-1-u1-X14"}],"explanation":["30 − (12 ÷ 3) = 26이고 ( )가 없을 때와 같아요.","(30 − 12) ÷ 3 = 18 ÷ 3 = 6이에요.","그래서 30 − 12를 묶어야 해요."],"variant_rule":{"alt":[{"stem":"40 − 16 ÷ 4에 ( )를 넣어 계산 결과가 6이 되게 하려면 어떻게 넣어야 하나요?","options":[{"t":"(40 − 16) ÷ 4","correct":true},{"t":"40 − (16 ÷ 4)","mis":"M5-1-u1-X06"},{"t":"(40) − 16 ÷ 4","mis":"M5-1-u1-X06"},{"t":"( )를 넣을 수 없다","mis":"M5-1-u1-X14"}],"explanation":["40 − (16 ÷ 4) = 36이에요.","(40 − 16) ÷ 4 = 24 ÷ 4 = 6이에요.","40 − 16을 묶어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_challenge#4','math',5,1,'u1','L06','g5_1_math_u1_L06_challenge','lesson_challenge','M5-1-u1-C6',3,'mc','auto','(□ + 7) × 4 = 60에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X07']::text[],true,'{"seq":4,"concept":"M5-1-u1-C6","difficulty":3,"kind":"mc","stem":"(□ + 7) × 4 = 60에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"53","mis":"M5-1-u1-X13"},{"t":"15","mis":"M5-1-u1-X13"},{"t":"2","mis":"M5-1-u1-X07"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 60이 되어야 해요.","거꾸로 되돌리면 □ = 8이에요.","확인: (8 + 7) × 4 → ① 8 + 7 = 15 → ② 15 × 4 = 60"],"variant_rule":{"alt":[{"stem":"(□ + 5) × 6 = 66에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"6","correct":true},{"t":"55","mis":"M5-1-u1-X13"},{"t":"11","mis":"M5-1-u1-X13"},{"t":"1","mis":"M5-1-u1-X07"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 66이 되어야 해요.","거꾸로 되돌리면 □ = 6이에요.","확인: (6 + 5) × 6 → ① 6 + 5 = 11 → ② 11 × 6 = 66"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_challenge#5','math',5,1,'u1','L06','g5_1_math_u1_L06_challenge','lesson_challenge','M5-1-u1-C6',3,'mc','auto','한 봉지에 사탕 6개와 초콜릿 4개를 넣어 8봉지를 만들려고 해요. 필요한 간식은 모두 몇 개인지 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X09']::text[],false,'{"seq":5,"concept":"M5-1-u1-C6","difficulty":3,"kind":"mc","stem":"한 봉지에 사탕 6개와 초콜릿 4개를 넣어 8봉지를 만들려고 해요. 필요한 간식은 모두 몇 개인지 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(6 + 4) × 8","correct":true},{"t":"6 + 4 × 8","mis":"M5-1-u1-X06"},{"t":"6 × 4 + 8","mis":"M5-1-u1-X09"},{"t":"(6 × 4) × 8","mis":"M5-1-u1-X09"}],"explanation":["한 봉지에 든 간식은 6 + 4 — 한 묶음이에요.","그 묶음이 8봉지예요.","(6 + 4) × 8 = 10 × 8 = 80개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_challenge#6','math',5,1,'u1','L06','g5_1_math_u1_L06_challenge','lesson_challenge','M5-1-u1-C6',3,'error','auto','「3000 − (800 + 700)」을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],false,'{"seq":6,"concept":"M5-1-u1-C6","difficulty":3,"kind":"error","stem":"「3000 − (800 + 700)」을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「( )는 없어도 같아. 3000 − 800 + 700으로 하면 돼.」","correct":true,"mis_target":"M5-1-u1-X06"},{"t":"예서 — 「우유와 빵을 한 묶음으로 본다는 뜻이야.」","mis":"M5-1-u1-X14"},{"t":"나윤 — 「800 + 700 = 1500을 먼저 빼면 1500원이 남아.」","mis":"M5-1-u1-X14"}],"explanation":["( )는 우유와 빵을 함께 산 한 묶음이라는 표현이에요.","800 + 700 = 1500, 3000 − 1500 = 1500원이에요.","서준이처럼 ( )를 빼면 2900으로 빵값을 더해 버려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_challenge#7','math',5,1,'u1','L06','g5_1_math_u1_L06_challenge','lesson_challenge','M5-1-u1-C6',3,'mc','auto','60 − (15 + 25)와 60 − 15 + 25의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],true,'{"seq":7,"concept":"M5-1-u1-C6","difficulty":3,"kind":"mc","stem":"60 − (15 + 25)와 60 − 15 + 25의 계산 결과의 차는 얼마인가요?","options":[{"t":"50","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"20","mis":"M5-1-u1-X14"},{"t":"70","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","60 − (15 + 25) = 20 · 60 − 15 + 25 = 70","두 결과의 차는 70 − 20 = 50이에요."],"variant_rule":{"alt":[{"stem":"80 − (24 + 16)과 80 − 24 + 16의 계산 결과의 차는 얼마인가요?","options":[{"t":"32","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"40","mis":"M5-1-u1-X14"},{"t":"72","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","80 − (24 + 16) = 40 · 80 − 24 + 16 = 72","두 결과의 차는 72 − 40 = 32예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_challenge#8','math',5,1,'u1','L06','g5_1_math_u1_L06_challenge','lesson_challenge','M5-1-u1-C6',4,'essay','teacher','3000 − 800 + 700과 3000 − (800 + 700)을 각각 계산하고, 「우유와 빵을 함께 샀다」는 이야기에 맞는 식은 어느 것인지 ( )의 뜻을 들어 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u1-C6","difficulty":4,"kind":"essay","stem":"3000 − 800 + 700과 3000 − (800 + 700)을 각각 계산하고, 「우유와 빵을 함께 샀다」는 이야기에 맞는 식은 어느 것인지 ( )의 뜻을 들어 설명하세요.","answer_guide":{"answer":"예: 3000 − 800 + 700 = 2200 + 700 = 2900, 3000 − (800 + 700) = 3000 − 1500 = 1500. 우유와 빵을 함께 샀으니 두 물건값이 한 묶음이고, ( )는 여기까지가 한 덩어리라는 표현이므로 3000 − (800 + 700) = 1500원이 맞다.","scoring_points":["2900을 구했는가","1500을 구했는가","( )가 한 덩어리를 나타내는 표현임을 들어 맞는 식을 골랐는가"]},"explanation":["( ) 없이 하면 2900, ( )가 있으면 1500이에요.","함께 산 두 물건값이 한 묶음이에요.","그래서 3000 − (800 + 700) = 1500원이 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_challenge#9','math',5,1,'u1','L06','g5_1_math_u1_L06_challenge','lesson_challenge','M5-1-u1-C6',4,'essay','teacher','4, 6, 3을 한 번씩 쓰고 + 와 × 와 ( )를 넣어 계산 결과가 가장 큰 식을 만들고, 그렇게 만든 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u1-C6","difficulty":4,"kind":"essay","stem":"4, 6, 3을 한 번씩 쓰고 + 와 × 와 ( )를 넣어 계산 결과가 가장 큰 식을 만들고, 그렇게 만든 까닭을 쓰세요.","answer_guide":{"answer":"예: (4 + 6) × 3 = 30, (6 + 3) × 4 = 36, (4 + 3) × 6 = 42, 4 × 6 + 3 = 27이다. 가장 큰 수 6을 곱하는 수로 두고 나머지 두 수 4와 3을 ( )로 묶어 더하면 (4 + 3) × 6 = 42로 가장 크다.","scoring_points":["만든 식을 바르게 계산했는가","결과가 가장 큰 식 (4 + 3) × 6 = 42를 찾았는가","가장 큰 수를 곱하고 나머지를 ( )로 묶어 더하는 까닭을 썼는가"]},"explanation":["(4 + 6) × 3 = 30, (4 + 3) × 6 = 42, (6 + 3) × 4 = 36이에요.","세 식을 견주면 (4 + 3) × 6 = 42가 가장 커요.","가장 큰 수를 곱하는 수로 두고 나머지 둘을 묶어 더하면 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L06_challenge#10','math',5,1,'u1','L06','g5_1_math_u1_L06_challenge','lesson_challenge','M5-1-u1-C6',4,'mc','auto','(□ − 9) ÷ 3 = 8에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13']::text[],true,'{"seq":10,"concept":"M5-1-u1-C6","difficulty":4,"kind":"mc","stem":"(□ − 9) ÷ 3 = 8에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"33","correct":true},{"t":"15","mis":"M5-1-u1-X13"},{"t":"11","mis":"M5-1-u1-X13"},{"t":"27","mis":"M5-1-u1-X13"}],"explanation":["( ) 안을 먼저 했으니 거꾸로 되돌릴 때는 ÷ 3부터 되돌려요.","8 × 3 = 24, 24 + 9 = 33이에요.","확인: (33 − 9) ÷ 3 = 24 ÷ 3 = 8이에요."],"variant_rule":{"alt":[{"stem":"(□ − 6) ÷ 4 = 9에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"42","correct":true},{"t":"30","mis":"M5-1-u1-X13"},{"t":"12","mis":"M5-1-u1-X13"},{"t":"36","mis":"M5-1-u1-X13"}],"explanation":["÷ 4부터 되돌려요 — 9 × 4 = 36.","36 + 6 = 42예요.","확인: (42 − 6) ÷ 4 = 36 ÷ 4 = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_basic#1','math',5,1,'u1','L07','g5_1_math_u1_L07_basic','lesson_basic','M5-1-u1-C7',1,'mc','auto','12 + 3 × 4 − 6에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X03']::text[],true,'{"seq":1,"concept":"M5-1-u1-C7","difficulty":1,"kind":"mc","stem":"12 + 3 × 4 − 6에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"3 × 4","correct":true},{"t":"12 + 3","mis":"M5-1-u1-X03"},{"t":"4 − 6","mis":"M5-1-u1-X03"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X03"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","그래서 가장 먼저 계산할 것은 3 × 4예요.","① 3 × 4 = 12 → ② 12 + 12 = 24 → ③ 24 − 6 = 18이에요."],"variant_rule":{"alt":[{"stem":"20 − 8 ÷ 2 + 5에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"8 ÷ 2","correct":true},{"t":"20 − 8","mis":"M5-1-u1-X04"},{"t":"2 + 5","mis":"M5-1-u1-X04"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X04"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","가장 먼저 계산할 것은 8 ÷ 2예요.","① 8 ÷ 2 = 4 → ② 20 − 4 = 16 → ③ 16 + 5 = 21이에요."]},{"stem":"15 + 6 × 3 − 9에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"6 × 3","correct":true},{"t":"15 + 6","mis":"M5-1-u1-X03"},{"t":"3 − 9","mis":"M5-1-u1-X03"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X03"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","가장 먼저 계산할 것은 6 × 3이에요.","① 6 × 3 = 18 → ② 15 + 18 = 33 → ③ 33 − 9 = 24예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_basic#2','math',5,1,'u1','L07','g5_1_math_u1_L07_basic','lesson_basic','M5-1-u1-C7',1,'sa','auto','12 + 3 × 4 − 6을 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-1-u1-C7","difficulty":1,"kind":"sa","stem":"12 + 3 × 4 − 6을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 3 × 4 = 12 → ② 12 + 12 = 24 → ③ 24 − 6 = 18이에요.","그래서 12 + 3 × 4 − 6 = 18이에요."],"variant_rule":{"alt":[{"stem":"20 − 8 ÷ 2 + 5를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 8 ÷ 2 = 4 → ② 20 − 4 = 16 → ③ 16 + 5 = 21이에요.","그래서 20 − 8 ÷ 2 + 5 = 21이에요."]},{"stem":"15 + 6 × 3 − 9를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 6 × 3 = 18 → ② 15 + 18 = 33 → ③ 33 − 9 = 24예요.","그래서 15 + 6 × 3 − 9 = 24예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_basic#3','math',5,1,'u1','L07','g5_1_math_u1_L07_basic','lesson_basic','M5-1-u1-C7',1,'mc','auto','(12 + 3) × 4 − 6에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X06']::text[],true,'{"seq":3,"concept":"M5-1-u1-C7","difficulty":1,"kind":"mc","stem":"(12 + 3) × 4 − 6에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"12 + 3","correct":true},{"t":"3 × 4","mis":"M5-1-u1-X06"},{"t":"4 − 6","mis":"M5-1-u1-X06"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X06"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","그래서 가장 먼저 계산할 것은 12 + 3이에요.","① 12 + 3 = 15 → ② 15 × 4 = 60 → ③ 60 − 6 = 54예요."],"variant_rule":{"alt":[{"stem":"(20 − 8) ÷ 2 + 5에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"20 − 8","correct":true},{"t":"8 ÷ 2","mis":"M5-1-u1-X06"},{"t":"2 + 5","mis":"M5-1-u1-X06"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X06"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","가장 먼저 계산할 것은 20 − 8이에요.","① 20 − 8 = 12 → ② 12 ÷ 2 = 6 → ③ 6 + 5 = 11이에요."]},{"stem":"(15 + 6) ÷ 3 − 2에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"15 + 6","correct":true},{"t":"6 ÷ 3","mis":"M5-1-u1-X06"},{"t":"3 − 2","mis":"M5-1-u1-X06"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X06"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","가장 먼저 계산할 것은 15 + 6이에요.","① 15 + 6 = 21 → ② 21 ÷ 3 = 7 → ③ 7 − 2 = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_basic#4','math',5,1,'u1','L07','g5_1_math_u1_L07_basic','lesson_basic','M5-1-u1-C7',1,'mc','auto','계산 순서를 바르게 나열한 것은 어느 것인가요?',ARRAY['M5-1-u1-X07','M5-1-u1-X03','M5-1-u1-X08']::text[],false,'{"seq":4,"concept":"M5-1-u1-C7","difficulty":1,"kind":"mc","stem":"계산 순서를 바르게 나열한 것은 어느 것인가요?","options":[{"t":"( ) 안 → 곱셈·나눗셈 → 덧셈·뺄셈","correct":true},{"t":"곱셈·나눗셈 → ( ) 안 → 덧셈·뺄셈","mis":"M5-1-u1-X07"},{"t":"언제나 왼쪽부터 차례로","mis":"M5-1-u1-X03"},{"t":"덧셈·뺄셈 → 곱셈·나눗셈 → ( ) 안","mis":"M5-1-u1-X08"}],"explanation":["( )가 가장 큰 묶음이에요.","그다음이 곱셈·나눗셈, 마지막이 덧셈·뺄셈이에요.","같은 층끼리는 앞에서부터 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_basic#5','math',5,1,'u1','L07','g5_1_math_u1_L07_basic','lesson_basic','M5-1-u1-C7',2,'mc','auto','(12 + 3) × 4 − 6을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X10']::text[],true,'{"seq":5,"concept":"M5-1-u1-C7","difficulty":2,"kind":"mc","stem":"(12 + 3) × 4 − 6을 계산하면 얼마인가요?","options":[{"t":"54","correct":true},{"t":"18","mis":"M5-1-u1-X06"},{"t":"64","mis":"M5-1-u1-X10"},{"t":"44","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 12 + 3 = 15 → ② 15 × 4 = 60 → ③ 60 − 6 = 54예요.","그래서 (12 + 3) × 4 − 6 = 54예요."],"variant_rule":{"alt":[{"stem":"(20 − 8) ÷ 2 + 5를 계산하면 얼마인가요?","options":[{"t":"11","correct":true},{"t":"21","mis":"M5-1-u1-X06"},{"t":"1","mis":"M5-1-u1-X10"},{"t":"13","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 20 − 8 = 12 → ② 12 ÷ 2 = 6 → ③ 6 + 5 = 11이에요.","그래서 (20 − 8) ÷ 2 + 5 = 11이에요."]},{"stem":"(15 + 6) ÷ 3 + 4를 계산하면 얼마인가요?","options":[{"t":"11","correct":true},{"t":"21","mis":"M5-1-u1-X06"},{"t":"1","mis":"M5-1-u1-X10"},{"t":"13","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 15 + 6 = 21 → ② 21 ÷ 3 = 7 → ③ 7 + 4 = 11이에요.","그래서 (15 + 6) ÷ 3 + 4 = 11이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_basic#6','math',5,1,'u1','L07','g5_1_math_u1_L07_basic','lesson_basic','M5-1-u1-C7',2,'mc','auto','학급 문고에 책 12권이 있었는데 3권씩 4묶음을 더 받고 6권을 다른 반에 빌려주었어요. 지금 책은 몇 권인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X09','M5-1-u1-X01']::text[],true,'{"seq":6,"concept":"M5-1-u1-C7","difficulty":2,"kind":"mc","stem":"학급 문고에 책 12권이 있었는데 3권씩 4묶음을 더 받고 6권을 다른 반에 빌려주었어요. 지금 책은 몇 권인가요?","options":[{"t":"18권","correct":true},{"t":"54권","mis":"M5-1-u1-X03"},{"t":"30권","mis":"M5-1-u1-X09"},{"t":"6권","mis":"M5-1-u1-X01"}],"explanation":["받은 책은 3 × 4, 빌려준 책은 6권 — 12 + 3 × 4 − 6.","곱셈 먼저 3 × 4 = 12, 남은 12 + 12 − 6은 앞에서부터 = 18.","지금 책은 18권이에요."],"variant_rule":{"alt":[{"stem":"교실에 색종이 20장이 있었는데 5장씩 3묶음을 더 받고 8장을 썼어요. 지금 색종이는 몇 장인가요?","options":[{"t":"27장","correct":true},{"t":"67장","mis":"M5-1-u1-X03"},{"t":"43장","mis":"M5-1-u1-X09"},{"t":"11장","mis":"M5-1-u1-X01"}],"explanation":["20 + 5 × 3 − 8로 나타내요.","5 × 3 = 15, 20 + 15 − 8 = 27.","27장이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_basic#7','math',5,1,'u1','L07','g5_1_math_u1_L07_basic','lesson_basic','M5-1-u1-C7',2,'mc','auto','5000원으로 900원짜리 공책 3권을 사고, 심부름을 하고 500원을 받았어요. 지금 가진 돈은 얼마인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X03','M5-1-u1-X10']::text[],false,'{"seq":7,"concept":"M5-1-u1-C7","difficulty":2,"kind":"mc","stem":"5000원으로 900원짜리 공책 3권을 사고, 심부름을 하고 500원을 받았어요. 지금 가진 돈은 얼마인가요?","options":[{"t":"2800원","correct":true},{"t":"1800원","mis":"M5-1-u1-X01"},{"t":"12500원","mis":"M5-1-u1-X03"},{"t":"3800원","mis":"M5-1-u1-X10"}],"explanation":["5000 − 900 × 3 + 500으로 나타내요.","곱셈 먼저 900 × 3 = 2700, 그다음 앞에서부터 5000 − 2700 = 2300, 2300 + 500 = 2800.","지금 가진 돈은 2800원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_basic#8','math',5,1,'u1','L07','g5_1_math_u1_L07_basic','lesson_basic','M5-1-u1-C7',2,'ox','auto','네 가지 계산이 섞인 식에서 곱셈과 나눗셈이 둘 다 있으면 곱셈을 먼저 해요.',ARRAY['M5-1-u1-X05']::text[],false,'{"seq":8,"concept":"M5-1-u1-C7","difficulty":2,"kind":"ox","stem":"네 가지 계산이 섞인 식에서 곱셈과 나눗셈이 둘 다 있으면 곱셈을 먼저 해요.","answer":"X","reason_options":[{"t":"곱셈과 나눗셈은 같은 층이라 앞에서부터 계산해서","correct":true},{"t":"곱셈이 나눗셈보다 높은 층이라서","mis":"M5-1-u1-X05"}],"mis":"M5-1-u1-X05","explanation":["세 층은 ( ) 안 → 곱셈·나눗셈 → 덧셈·뺄셈이에요.","곱셈과 나눗셈은 같은 층이에요.","같은 층끼리는 앞에서부터 — 예: 20 − 12 ÷ 4 × 2 = 20 − 3 × 2 = 14예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_basic#9','math',5,1,'u1','L07','g5_1_math_u1_L07_basic','lesson_basic','M5-1-u1-C7',2,'match','auto','계산식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M5-1-u1-C7","difficulty":2,"kind":"match","stem":"계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"18 + 24 ÷ 6 × 2","r":"26"},{"l":"(18 + 24) ÷ 6 × 2","r":"14"},{"l":"18 + 24 ÷ (6 × 2)","r":"20"}],"mis":"M5-1-u1-X08","explanation":["식마다 계산 순서를 지켜 셈해요.","18 + 24 ÷ 6 × 2 = 26 · (18 + 24) ÷ 6 × 2 = 14 · 18 + 24 ÷ (6 × 2) = 20","( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"30 − 12 ÷ 4 × 3","r":"21"},{"l":"(30 − 12) ÷ 6 × 3","r":"9"},{"l":"30 − 12 ÷ (4 × 3)","r":"29"}],"explanation":["식마다 계산 순서를 지켜 셈해요.","30 − 12 ÷ 4 × 3 = 21 · (30 − 12) ÷ 6 × 3 = 9 · 30 − 12 ÷ (4 × 3) = 29","( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_basic#10','math',5,1,'u1','L07','g5_1_math_u1_L07_basic','lesson_basic','M5-1-u1-C7',3,'mc','auto','40 − (6 + 2) × 3과 40 − 6 + 2 × 3의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],true,'{"seq":10,"concept":"M5-1-u1-C7","difficulty":3,"kind":"mc","stem":"40 − (6 + 2) × 3과 40 − 6 + 2 × 3의 계산 결과의 차는 얼마인가요?","options":[{"t":"24","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"16","mis":"M5-1-u1-X14"},{"t":"40","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","40 − (6 + 2) × 3 = 16 · 40 − 6 + 2 × 3 = 40","두 결과의 차는 40 − 16 = 24예요."],"variant_rule":{"alt":[{"stem":"50 − (4 + 3) × 5와 50 − 4 + 3 × 5의 계산 결과의 차는 얼마인가요?","options":[{"t":"46","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"15","mis":"M5-1-u1-X14"},{"t":"61","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","50 − (4 + 3) × 5 = 15 · 50 − 4 + 3 × 5 = 61","두 결과의 차는 61 − 15 = 46이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_challenge#1','math',5,1,'u1','L07','g5_1_math_u1_L07_challenge','lesson_challenge','M5-1-u1-C7',2,'mc','auto','36 ÷ (9 − 5) + 7 × 3 − 8을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X10']::text[],true,'{"seq":1,"concept":"M5-1-u1-C7","difficulty":2,"kind":"mc","stem":"36 ÷ (9 − 5) + 7 × 3 − 8을 계산하면 얼마인가요?","options":[{"t":"22","correct":true},{"t":"40","mis":"M5-1-u1-X03"},{"t":"32","mis":"M5-1-u1-X10"},{"t":"12","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 9 − 5 = 4 → ② 36 ÷ 4 = 9 → ③ 7 × 3 = 21 → ④ 9 + 21 = 30 → ⑤ 30 − 8 = 22예요.","그래서 36 ÷ (9 − 5) + 7 × 3 − 8 = 22예요."],"variant_rule":{"alt":[{"stem":"48 ÷ (11 − 5) + 6 × 4 − 9를 계산하면 얼마인가요?","options":[{"t":"23","correct":true},{"t":"47","mis":"M5-1-u1-X03"},{"t":"33","mis":"M5-1-u1-X10"},{"t":"13","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 11 − 5 = 6 → ② 48 ÷ 6 = 8 → ③ 6 × 4 = 24 → ④ 8 + 24 = 32 → ⑤ 32 − 9 = 23이에요.","그래서 48 ÷ (11 − 5) + 6 × 4 − 9 = 23이에요."]},{"stem":"42 ÷ (2 + 5) × 3 − 4 + 10을 계산하면 얼마인가요?","options":[{"t":"24","correct":true},{"t":"42","mis":"M5-1-u1-X06"},{"t":"4","mis":"M5-1-u1-X01"},{"t":"84","mis":"M5-1-u1-X07"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 2 + 5 = 7 → ② 42 ÷ 7 = 6 → ③ 6 × 3 = 18 → ④ 18 − 4 = 14 → ⑤ 14 + 10 = 24예요.","그래서 42 ÷ (2 + 5) × 3 − 4 + 10 = 24예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_challenge#2','math',5,1,'u1','L07','g5_1_math_u1_L07_challenge','lesson_challenge','M5-1-u1-C7',2,'mc','auto','64 − (13 + 5) ÷ 3 × 4를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X10']::text[],true,'{"seq":2,"concept":"M5-1-u1-C7","difficulty":2,"kind":"mc","stem":"64 − (13 + 5) ÷ 3 × 4를 계산하면 얼마인가요?","options":[{"t":"40","correct":true},{"t":"50","mis":"M5-1-u1-X10"},{"t":"30","mis":"M5-1-u1-X10"},{"t":"42","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 13 + 5 = 18 → ② 18 ÷ 3 = 6 → ③ 6 × 4 = 24 → ④ 64 − 24 = 40이에요.","그래서 64 − (13 + 5) ÷ 3 × 4 = 40이에요."],"variant_rule":{"alt":[{"stem":"90 − (16 + 8) ÷ 4 × 7을 계산하면 얼마인가요?","options":[{"t":"48","correct":true},{"t":"88","mis":"M5-1-u1-X06"},{"t":"58","mis":"M5-1-u1-X10"},{"t":"38","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 16 + 8 = 24 → ② 24 ÷ 4 = 6 → ③ 6 × 7 = 42 → ④ 90 − 42 = 48이에요.","그래서 90 − (16 + 8) ÷ 4 × 7 = 48이에요."]},{"stem":"75 − (12 − 3) × 6 ÷ 2를 계산하면 얼마인가요?","options":[{"t":"48","correct":true},{"t":"54","mis":"M5-1-u1-X06"},{"t":"198","mis":"M5-1-u1-X03"},{"t":"180","mis":"M5-1-u1-X07"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 12 − 3 = 9 → ② 9 × 6 = 54 → ③ 54 ÷ 2 = 27 → ④ 75 − 27 = 48이에요.","그래서 75 − (12 − 3) × 6 ÷ 2 = 48이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_challenge#3','math',5,1,'u1','L07','g5_1_math_u1_L07_challenge','lesson_challenge','M5-1-u1-C7',3,'mc','auto','(8 + □) × 2 − 6 = 20에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X08']::text[],true,'{"seq":3,"concept":"M5-1-u1-C7","difficulty":3,"kind":"mc","stem":"(8 + □) × 2 − 6 = 20에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"5","correct":true},{"t":"13","mis":"M5-1-u1-X13"},{"t":"3","mis":"M5-1-u1-X13"},{"t":"1","mis":"M5-1-u1-X08"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 20이 되어야 해요.","거꾸로 되돌리면 □ = 5예요.","확인: (8 + 5) × 2 − 6 → ① 8 + 5 = 13 → ② 13 × 2 = 26 → ③ 26 − 6 = 20"],"variant_rule":{"alt":[{"stem":"(6 + □) × 3 − 9 = 30에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"7","correct":true},{"t":"13","mis":"M5-1-u1-X13"},{"t":"4","mis":"M5-1-u1-X13"},{"t":"5","mis":"M5-1-u1-X08"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 30이 되어야 해요.","거꾸로 되돌리면 □ = 7이에요.","확인: (6 + 7) × 3 − 9 → ① 6 + 7 = 13 → ② 13 × 3 = 39 → ③ 39 − 9 = 30"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_challenge#4','math',5,1,'u1','L07','g5_1_math_u1_L07_challenge','lesson_challenge','M5-1-u1-C7',3,'mc','auto','연우네 모둠은 사과 4개씩 3바구니와 배 15개를 샀어요. 이 과일을 9명이 똑같이 나누면 한 명이 몇 개씩 받나요?',ARRAY['M5-1-u1-X06','M5-1-u1-X09','M5-1-u1-X10']::text[],false,'{"seq":4,"concept":"M5-1-u1-C7","difficulty":3,"kind":"mc","stem":"연우네 모둠은 사과 4개씩 3바구니와 배 15개를 샀어요. 이 과일을 9명이 똑같이 나누면 한 명이 몇 개씩 받나요?","options":[{"t":"3개","correct":true},{"t":"17개","mis":"M5-1-u1-X06"},{"t":"49개","mis":"M5-1-u1-X09"},{"t":"9개","mis":"M5-1-u1-X10"}],"explanation":["과일은 모두 4 × 3 + 15개이고 그것을 9명이 나눠요 — (4 × 3 + 15) ÷ 9.","( ) 안에서 곱셈 먼저 4 × 3 = 12, 12 + 15 = 27, 27 ÷ 9 = 3.","한 명이 3개씩 받아요. ( ) 없이 4 × 3 + 15 ÷ 9로 쓰면 나누어떨어지지도 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_challenge#5','math',5,1,'u1','L07','g5_1_math_u1_L07_challenge','lesson_challenge','M5-1-u1-C7',3,'error','auto','「12 + 3 × 4 − 6」을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X14']::text[],false,'{"seq":5,"concept":"M5-1-u1-C7","difficulty":3,"kind":"error","stem":"「12 + 3 × 4 − 6」을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라희 — 「12 + 3 = 15, 15 × 4 = 60, 60 − 6 = 54야.」","correct":true,"mis_target":"M5-1-u1-X03"},{"t":"현우 — 「3 × 4 = 12를 먼저 하고 12 + 12 − 6 = 18이야.」","mis":"M5-1-u1-X14"},{"t":"민지 — 「곱셈 다음에 덧셈·뺄셈은 앞에서부터야.」","mis":"M5-1-u1-X14"}],"explanation":["곱셈을 먼저 해요 — 3 × 4 = 12.","남은 12 + 12 − 6은 앞에서부터 = 18이에요.","라희는 앞에서부터만 해서 54가 나왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_challenge#6','math',5,1,'u1','L07','g5_1_math_u1_L07_challenge','lesson_challenge','M5-1-u1-C7',3,'mc','auto','6 + 18 ÷ 3 × 2 − 4에 ( )를 한 번 넣어 계산 결과가 5가 되게 하려면 어디를 묶어야 하나요?',ARRAY['M5-1-u1-X06']::text[],false,'{"seq":6,"concept":"M5-1-u1-C7","difficulty":3,"kind":"mc","stem":"6 + 18 ÷ 3 × 2 − 4에 ( )를 한 번 넣어 계산 결과가 5가 되게 하려면 어디를 묶어야 하나요?","options":[{"t":"6 + 18 ÷ (3 × 2) − 4","correct":true},{"t":"(6 + 18) ÷ 3 × 2 − 4","mis":"M5-1-u1-X06"},{"t":"6 + (18 ÷ 3) × 2 − 4","mis":"M5-1-u1-X06"},{"t":"( )를 넣지 않아도 5이다","mis":"M5-1-u1-X06"}],"explanation":["( )가 없으면 6 + 6 × 2 − 4 = 14예요. (18 ÷ 3)을 묶어도 같은 14예요.","(6 + 18)을 묶으면 24 ÷ 3 × 2 − 4 = 12예요.","3 × 2를 묶으면 6 + 18 ÷ 6 − 4 = 6 + 3 − 4 = 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_challenge#7','math',5,1,'u1','L07','g5_1_math_u1_L07_challenge','lesson_challenge','M5-1-u1-C7',3,'mc','auto','(30 − 6) ÷ 4 + 2 × 5와 30 − 6 ÷ 2 + 4 × 5의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],true,'{"seq":7,"concept":"M5-1-u1-C7","difficulty":3,"kind":"mc","stem":"(30 − 6) ÷ 4 + 2 × 5와 30 − 6 ÷ 2 + 4 × 5의 계산 결과의 차는 얼마인가요?","options":[{"t":"31","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"16","mis":"M5-1-u1-X14"},{"t":"47","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","(30 − 6) ÷ 4 + 2 × 5 = 16 · 30 − 6 ÷ 2 + 4 × 5 = 47","두 결과의 차는 47 − 16 = 31이에요."],"variant_rule":{"alt":[{"stem":"(28 − 4) ÷ 6 + 3 × 4와 28 − 4 ÷ 2 + 6 × 4의 계산 결과의 차는 얼마인가요?","options":[{"t":"34","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"16","mis":"M5-1-u1-X14"},{"t":"50","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","(28 − 4) ÷ 6 + 3 × 4 = 16 · 28 − 4 ÷ 2 + 6 × 4 = 50","두 결과의 차는 50 − 16 = 34예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_challenge#8','math',5,1,'u1','L07','g5_1_math_u1_L07_challenge','lesson_challenge','M5-1-u1-C7',4,'essay','teacher','12 + 3 × 4 − 6을 계산하는 순서를 ①, ②, ③으로 쓰고, 왜 그 순서로 계산하는지 「덩어리」라는 말을 넣어 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u1-C7","difficulty":4,"kind":"essay","stem":"12 + 3 × 4 − 6을 계산하는 순서를 ①, ②, ③으로 쓰고, 왜 그 순서로 계산하는지 「덩어리」라는 말을 넣어 설명하세요.","answer_guide":{"answer":"예: ① 3 × 4 = 12 ② 12 + 12 = 24 ③ 24 − 6 = 18. 3 × 4는 3권씩 4묶음이라는 하나의 양(덩어리)이라 먼저 구하고, 남은 덧셈과 뺄셈은 같은 층이라 앞에서부터 계산한다.","scoring_points":["3 × 4를 먼저 계산했는가","덧셈·뺄셈을 앞에서부터 해 18을 구했는가","곱셈 부분이 하나의 덩어리라는 까닭을 썼는가"]},"explanation":["① 3 × 4 = 12 ② 12 + 12 = 24 ③ 24 − 6 = 18이에요.","3 × 4는 이미 하나의 덩어리예요.","덧셈과 뺄셈은 같은 층이라 앞에서부터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_challenge#9','math',5,1,'u1','L07','g5_1_math_u1_L07_challenge','lesson_challenge','M5-1-u1-C7',4,'essay','teacher','「공책 3권을 한 권에 800원씩, 연필 한 다스를 1200원에 사고 5000원을 냈어요.」 거스름돈을 구하는 식을 ( )를 써서 하나로 세우고 계산 과정과 함께 답을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u1-C7","difficulty":4,"kind":"essay","stem":"「공책 3권을 한 권에 800원씩, 연필 한 다스를 1200원에 사고 5000원을 냈어요.」 거스름돈을 구하는 식을 ( )를 써서 하나로 세우고 계산 과정과 함께 답을 쓰세요.","answer_guide":{"answer":"예: 5000 − (800 × 3 + 1200) = 5000 − (2400 + 1200) = 5000 − 3600 = 1400원.","scoring_points":["5000 − (800 × 3 + 1200)처럼 한 식으로 세웠는가","( ) 안에서 곱셈을 먼저 해 3600을 구했는가","거스름돈 1400원을 구했는가"]},"explanation":["산 물건값 800 × 3 + 1200이 한 묶음이에요.","( ) 안에서 곱셈 먼저 — 2400 + 1200 = 3600.","5000 − 3600 = 1400원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L07_challenge#10','math',5,1,'u1','L07','g5_1_math_u1_L07_challenge','lesson_challenge','M5-1-u1-C7',4,'mc','auto','어떤 수에서 4를 뺀 다음 3을 곱하고 6으로 나누어야 할 것을 잘못하여 4를 더한 다음 3을 곱하고 6으로 나누었더니 8이 되었어요. 바르게 계산하면 얼마인가요?',ARRAY['M5-1-u1-X14','M5-1-u1-X13']::text[],false,'{"seq":10,"concept":"M5-1-u1-C7","difficulty":4,"kind":"mc","stem":"어떤 수에서 4를 뺀 다음 3을 곱하고 6으로 나누어야 할 것을 잘못하여 4를 더한 다음 3을 곱하고 6으로 나누었더니 8이 되었어요. 바르게 계산하면 얼마인가요?","options":[{"t":"4","correct":true},{"t":"8","mis":"M5-1-u1-X14"},{"t":"12","mis":"M5-1-u1-X13"},{"t":"16","mis":"M5-1-u1-X13"}],"explanation":["잘못 계산한 식은 (□ + 4) × 3 ÷ 6 = 8 — 거꾸로 8 × 6 = 48, 48 ÷ 3 = 16, 16 − 4 = 12예요.","어떤 수는 12예요.","바르게 계산하면 (12 − 4) × 3 ÷ 6 = 8 × 3 ÷ 6 = 24 ÷ 6 = 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_basic#1','math',5,1,'u1','L08','g5_1_math_u1_L08_basic','lesson_basic','M5-1-u1-C8',1,'mc','auto','우리나라에서 부가 가치세는 어떻게 구하나요?',ARRAY['M5-1-u1-X11']::text[],false,'{"seq":1,"concept":"M5-1-u1-C8","difficulty":1,"kind":"mc","stem":"우리나라에서 부가 가치세는 어떻게 구하나요?","options":[{"t":"공급 가격을 10으로 나눈 몫","correct":true},{"t":"공급 가격에 10을 곱한 값","mis":"M5-1-u1-X11"},{"t":"공급 가격에서 10을 뺀 값","mis":"M5-1-u1-X11"},{"t":"공급 가격을 100으로 나눈 몫","mis":"M5-1-u1-X11"}],"explanation":["영수증에는 공급 가격과 부가 가치세 줄이 있어요.","부가 가치세는 공급 가격을 10으로 나눈 몫만큼 내요.","공급 가격이 1000원이면 세금은 100원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_basic#2','math',5,1,'u1','L08','g5_1_math_u1_L08_basic','lesson_basic','M5-1-u1-C8',1,'mc','auto','공급 가격이 3200원인 물건을 샀어요. 이때 낸 부가 가치세는 얼마인가요?',ARRAY['M5-1-u1-X11','M5-1-u1-X12']::text[],true,'{"seq":2,"concept":"M5-1-u1-C8","difficulty":1,"kind":"mc","stem":"공급 가격이 3200원인 물건을 샀어요. 이때 낸 부가 가치세는 얼마인가요?","options":[{"t":"320원","correct":true},{"t":"32000원","mis":"M5-1-u1-X11"},{"t":"32원","mis":"M5-1-u1-X11"},{"t":"3520원","mis":"M5-1-u1-X12"}],"explanation":["부가 가치세는 공급 가격 ÷ 10이에요.","3200 ÷ 10 = 320이에요.","낸 부가 가치세는 320원이에요."],"variant_rule":{"alt":[{"stem":"공급 가격이 4500원인 물건을 샀어요. 이때 낸 부가 가치세는 얼마인가요?","options":[{"t":"450원","correct":true},{"t":"45000원","mis":"M5-1-u1-X11"},{"t":"45원","mis":"M5-1-u1-X11"},{"t":"4950원","mis":"M5-1-u1-X12"}],"explanation":["공급 가격 ÷ 10이에요.","4500 ÷ 10 = 450이에요.","450원이에요."]},{"stem":"공급 가격이 1800원인 물건을 샀어요. 이때 낸 부가 가치세는 얼마인가요?","options":[{"t":"180원","correct":true},{"t":"18000원","mis":"M5-1-u1-X11"},{"t":"18원","mis":"M5-1-u1-X11"},{"t":"1980원","mis":"M5-1-u1-X12"}],"explanation":["공급 가격 ÷ 10이에요.","1800 ÷ 10 = 180이에요.","180원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_basic#3','math',5,1,'u1','L08','g5_1_math_u1_L08_basic','lesson_basic','M5-1-u1-C8',1,'mc','auto','아이스크림 1통(공급 가격 2400원)과 과자 3봉지(1봉지 800원)를 샀어요. 낸 세금을 나타낸 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u1-X09']::text[],false,'{"seq":3,"concept":"M5-1-u1-C8","difficulty":1,"kind":"mc","stem":"아이스크림 1통(공급 가격 2400원)과 과자 3봉지(1봉지 800원)를 샀어요. 낸 세금을 나타낸 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(2400 + 800 × 3) ÷ 10","correct":true},{"t":"(2400 + 800) ÷ 10 × 3","mis":"M5-1-u1-X09"},{"t":"2400 ÷ 10 + 800 × 3","mis":"M5-1-u1-X09"},{"t":"2400 × 3 + 800 ÷ 10","mis":"M5-1-u1-X09"}],"explanation":["공급 가격은 모두 2400 + 800 × 3이에요.","그 전체를 10으로 나눠요.","( )로 묶어 (2400 + 800 × 3) ÷ 10이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_basic#4','math',5,1,'u1','L08','g5_1_math_u1_L08_basic','lesson_basic','M5-1-u1-C8',1,'mc','auto','(2400 + 800 × 3) ÷ 10을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X11','M5-1-u1-X10']::text[],false,'{"seq":4,"concept":"M5-1-u1-C8","difficulty":1,"kind":"mc","stem":"(2400 + 800 × 3) ÷ 10을 계산하면 얼마인가요?","options":[{"t":"480","correct":true},{"t":"960","mis":"M5-1-u1-X06"},{"t":"4800","mis":"M5-1-u1-X11"},{"t":"240","mis":"M5-1-u1-X10"}],"explanation":["( ) 안에서 곱셈 먼저 — 800 × 3 = 2400, 2400 + 2400 = 4800.","4800 ÷ 10 = 480이에요.","낸 세금은 480원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_basic#5','math',5,1,'u1','L08','g5_1_math_u1_L08_basic','lesson_basic','M5-1-u1-C8',2,'mc','auto','같은 문제를 시연이는 (2400 + 800 × 3) ÷ 10, 재윤이는 2400 ÷ 10 + 800 ÷ 10 × 3으로 풀었어요. 바르게 판단한 것은 어느 것인가요?',ARRAY['M5-1-u1-X09','M5-1-u1-X14']::text[],false,'{"seq":5,"concept":"M5-1-u1-C8","difficulty":2,"kind":"mc","stem":"같은 문제를 시연이는 (2400 + 800 × 3) ÷ 10, 재윤이는 2400 ÷ 10 + 800 ÷ 10 × 3으로 풀었어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"두 식 모두 맞다","correct":true},{"t":"시연이만 맞다","mis":"M5-1-u1-X09"},{"t":"재윤이만 맞다","mis":"M5-1-u1-X09"},{"t":"둘 다 계산이 잘못됐다","mis":"M5-1-u1-X14"}],"explanation":["시연: 4800 ÷ 10 = 480 · 재윤: 240 + 80 × 3 = 240 + 240 = 480.","모두 모아 10등분하든, 각각 10등분해 모으든 같은 전체를 같은 크기로 나눈 거예요.","식을 세우는 방법은 여러 가지일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_basic#6','math',5,1,'u1','L08','g5_1_math_u1_L08_basic','lesson_basic','M5-1-u1-C8',2,'mc','auto','색연필 1세트(공급 가격 5000원)와 색종이 2묶음(1묶음 600원)을 샀어요. 낸 부가 가치세는 얼마인가요?',ARRAY['M5-1-u1-X11','M5-1-u1-X06']::text[],true,'{"seq":6,"concept":"M5-1-u1-C8","difficulty":2,"kind":"mc","stem":"색연필 1세트(공급 가격 5000원)와 색종이 2묶음(1묶음 600원)을 샀어요. 낸 부가 가치세는 얼마인가요?","options":[{"t":"620원","correct":true},{"t":"6200원","mis":"M5-1-u1-X11"},{"t":"560원","mis":"M5-1-u1-X06"},{"t":"62원","mis":"M5-1-u1-X11"}],"explanation":["식은 (5000 + 600 × 2) ÷ 10이에요.","( ) 안 — 600 × 2 = 1200, 5000 + 1200 = 6200.","6200 ÷ 10 = 620원이에요."],"variant_rule":{"alt":[{"stem":"필통 1개(공급 가격 3000원)와 공책 4권(1권 500원)을 샀어요. 낸 부가 가치세는 얼마인가요?","options":[{"t":"500원","correct":true},{"t":"5000원","mis":"M5-1-u1-X11"},{"t":"350원","mis":"M5-1-u1-X06"},{"t":"50원","mis":"M5-1-u1-X11"}],"explanation":["식은 (3000 + 500 × 4) ÷ 10이에요.","500 × 4 = 2000, 3000 + 2000 = 5000.","5000 ÷ 10 = 500원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_basic#7','math',5,1,'u1','L08','g5_1_math_u1_L08_basic','lesson_basic','M5-1-u1-C8',2,'mc','auto','공급 가격이 2000원인 물건 하나를 살 때 실제로 내는 돈은 얼마인가요?',ARRAY['M5-1-u1-X12','M5-1-u1-X11']::text[],true,'{"seq":7,"concept":"M5-1-u1-C8","difficulty":2,"kind":"mc","stem":"공급 가격이 2000원인 물건 하나를 살 때 실제로 내는 돈은 얼마인가요?","options":[{"t":"2200원","correct":true},{"t":"2000원","mis":"M5-1-u1-X12"},{"t":"1800원","mis":"M5-1-u1-X12"},{"t":"2010원","mis":"M5-1-u1-X11"}],"explanation":["부가 가치세는 2000 ÷ 10 = 200원이에요.","실제로 내는 돈은 공급 가격과 세금을 더한 것이에요.","2000 + 200 = 2200원이에요."],"variant_rule":{"alt":[{"stem":"공급 가격이 3500원인 물건 하나를 살 때 실제로 내는 돈은 얼마인가요?","options":[{"t":"3850원","correct":true},{"t":"3500원","mis":"M5-1-u1-X12"},{"t":"3150원","mis":"M5-1-u1-X12"},{"t":"3510원","mis":"M5-1-u1-X11"}],"explanation":["세금은 3500 ÷ 10 = 350원이에요.","공급 가격과 세금을 더해요.","3500 + 350 = 3850원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_basic#8','math',5,1,'u1','L08','g5_1_math_u1_L08_basic','lesson_basic','M5-1-u1-C8',2,'ox','auto','물건마다 부가 가치세를 따로 구해 더한 값과, 공급 가격을 모두 더한 뒤 10으로 나눈 값은 서로 달라요.',ARRAY['M5-1-u1-X09']::text[],false,'{"seq":8,"concept":"M5-1-u1-C8","difficulty":2,"kind":"ox","stem":"물건마다 부가 가치세를 따로 구해 더한 값과, 공급 가격을 모두 더한 뒤 10으로 나눈 값은 서로 달라요.","answer":"X","reason_options":[{"t":"모두 모아 10등분하든 각각 10등분해 모으든 같은 전체를 같은 크기로 나눈 것이라서","correct":true},{"t":"나누는 차례가 다르면 답도 달라서","mis":"M5-1-u1-X09"}],"mis":"M5-1-u1-X09","explanation":["예: 2400 ÷ 10 + 2400 ÷ 10 = 240 + 240 = 480이에요.","(2400 + 2400) ÷ 10 = 4800 ÷ 10 = 480이에요.","두 값은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_basic#9','math',5,1,'u1','L08','g5_1_math_u1_L08_basic','lesson_basic','M5-1-u1-C8',2,'mc','auto','어떤 물건에 붙은 부가 가치세가 750원이었어요. 이 물건의 공급 가격은 얼마인가요?',ARRAY['M5-1-u1-X12','M5-1-u1-X13']::text[],false,'{"seq":9,"concept":"M5-1-u1-C8","difficulty":2,"kind":"mc","stem":"어떤 물건에 붙은 부가 가치세가 750원이었어요. 이 물건의 공급 가격은 얼마인가요?","options":[{"t":"7500원","correct":true},{"t":"750원","mis":"M5-1-u1-X12"},{"t":"75원","mis":"M5-1-u1-X13"},{"t":"8250원","mis":"M5-1-u1-X12"}],"explanation":["부가 가치세 = 공급 가격 ÷ 10이에요.","거꾸로 되돌리면 공급 가격 = 750 × 10이에요.","공급 가격은 7500원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_basic#10','math',5,1,'u1','L08','g5_1_math_u1_L08_basic','lesson_basic','M5-1-u1-C8',3,'mc','auto','빵 2개(1개 공급 가격 1500원)와 우유 1개(공급 가격 1000원)를 샀어요. 낸 돈은 공급 가격과 부가 가치세를 합한 것이에요. 낸 돈은 모두 얼마인가요?',ARRAY['M5-1-u1-X12','M5-1-u1-X06']::text[],false,'{"seq":10,"concept":"M5-1-u1-C8","difficulty":3,"kind":"mc","stem":"빵 2개(1개 공급 가격 1500원)와 우유 1개(공급 가격 1000원)를 샀어요. 낸 돈은 공급 가격과 부가 가치세를 합한 것이에요. 낸 돈은 모두 얼마인가요?","options":[{"t":"4400원","correct":true},{"t":"4000원","mis":"M5-1-u1-X12"},{"t":"400원","mis":"M5-1-u1-X12"},{"t":"2750원","mis":"M5-1-u1-X06"}],"explanation":["공급 가격은 1500 × 2 + 1000 = 4000원이에요.","부가 가치세는 4000 ÷ 10 = 400원이에요.","낸 돈은 4000 + 400 = 4400원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_challenge#1','math',5,1,'u1','L08','g5_1_math_u1_L08_challenge','lesson_challenge','M5-1-u1-C8',2,'mc','auto','공급 가격이 1200원인 음료 4병을 샀어요. 낸 부가 가치세를 구하는 식으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M5-1-u1-X14']::text[],false,'{"seq":1,"concept":"M5-1-u1-C8","difficulty":2,"kind":"mc","stem":"공급 가격이 1200원인 음료 4병을 샀어요. 낸 부가 가치세를 구하는 식으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"1200 × 4 ÷ 100","correct":true},{"t":"1200 × 4 ÷ 10","mis":"M5-1-u1-X14"},{"t":"1200 ÷ 10 × 4","mis":"M5-1-u1-X14"},{"t":"(1200 × 4) ÷ 10","mis":"M5-1-u1-X14"}],"explanation":["부가 가치세는 공급 가격 ÷ 10이에요.","1200 × 4 ÷ 10 = 480 · 1200 ÷ 10 × 4 = 480 · (1200 × 4) ÷ 10 = 480으로 모두 같아요.","100으로 나누면 48로 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_challenge#2','math',5,1,'u1','L08','g5_1_math_u1_L08_challenge','lesson_challenge','M5-1-u1-C8',2,'mc','auto','공급 가격이 2500원인 공책 2권과 1500원인 펜 1자루를 샀어요. 낸 부가 가치세는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X11','M5-1-u1-X10']::text[],false,'{"seq":2,"concept":"M5-1-u1-C8","difficulty":2,"kind":"mc","stem":"공급 가격이 2500원인 공책 2권과 1500원인 펜 1자루를 샀어요. 낸 부가 가치세는 얼마인가요?","options":[{"t":"650원","correct":true},{"t":"400원","mis":"M5-1-u1-X06"},{"t":"6500원","mis":"M5-1-u1-X11"},{"t":"550원","mis":"M5-1-u1-X10"}],"explanation":["식은 (2500 × 2 + 1500) ÷ 10이에요.","2500 × 2 = 5000, 5000 + 1500 = 6500.","6500 ÷ 10 = 650원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_challenge#3','math',5,1,'u1','L08','g5_1_math_u1_L08_challenge','lesson_challenge','M5-1-u1-C8',3,'mc','auto','낸 돈(공급 가격과 부가 가치세의 합)이 3300원인 물건의 공급 가격은 얼마인가요?',ARRAY['M5-1-u1-X12','M5-1-u1-X11','M5-1-u1-X13']::text[],false,'{"seq":3,"concept":"M5-1-u1-C8","difficulty":3,"kind":"mc","stem":"낸 돈(공급 가격과 부가 가치세의 합)이 3300원인 물건의 공급 가격은 얼마인가요?","options":[{"t":"3000원","correct":true},{"t":"3300원","mis":"M5-1-u1-X12"},{"t":"330원","mis":"M5-1-u1-X11"},{"t":"2970원","mis":"M5-1-u1-X13"}],"explanation":["낸 돈 = 공급 가격 + 공급 가격 ÷ 10이에요.","공급 가격을 10칸으로 보면 세금은 1칸 — 낸 돈은 11칸이에요.","3300 ÷ 11 = 300이 한 칸, 공급 가격은 300 × 10 = 3000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_challenge#4','math',5,1,'u1','L08','g5_1_math_u1_L08_challenge','lesson_challenge','M5-1-u1-C8',3,'mc','auto','공급 가격이 같은 과자 3봉지를 사고 부가 가치세로 270원을 냈어요. 과자 1봉지의 공급 가격은 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X11']::text[],false,'{"seq":4,"concept":"M5-1-u1-C8","difficulty":3,"kind":"mc","stem":"공급 가격이 같은 과자 3봉지를 사고 부가 가치세로 270원을 냈어요. 과자 1봉지의 공급 가격은 얼마인가요?","options":[{"t":"900원","correct":true},{"t":"2700원","mis":"M5-1-u1-X13"},{"t":"90원","mis":"M5-1-u1-X11"},{"t":"810원","mis":"M5-1-u1-X13"}],"explanation":["세 봉지 공급 가격의 합은 270 × 10 = 2700원이에요.","한 봉지는 2700 ÷ 3이에요.","900원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_challenge#5','math',5,1,'u1','L08','g5_1_math_u1_L08_challenge','lesson_challenge','M5-1-u1-C8',3,'error','auto','아이스크림 1통(2400원)과 과자 3봉지(1봉지 800원)를 산 세금을 두고 친구들이 식을 세웠어요. 잘못 세운 친구는 누구인가요?',ARRAY['M5-1-u1-X09','M5-1-u1-X14']::text[],false,'{"seq":5,"concept":"M5-1-u1-C8","difficulty":3,"kind":"error","stem":"아이스크림 1통(2400원)과 과자 3봉지(1봉지 800원)를 산 세금을 두고 친구들이 식을 세웠어요. 잘못 세운 친구는 누구인가요?","options":[{"t":"하람 — 「(2400 + 800) ÷ 10 × 3」","correct":true,"mis_target":"M5-1-u1-X09"},{"t":"시연 — 「(2400 + 800 × 3) ÷ 10」","mis":"M5-1-u1-X14"},{"t":"재윤 — 「2400 ÷ 10 + 800 ÷ 10 × 3」","mis":"M5-1-u1-X14"}],"explanation":["과자 3봉지의 값은 800 × 3이에요.","하람이의 식은 아이스크림 값까지 3번 곱해 960이 나와요.","시연·재윤의 식은 둘 다 480이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_challenge#6','math',5,1,'u1','L08','g5_1_math_u1_L08_challenge','lesson_challenge','M5-1-u1-C8',3,'mc','auto','1000원으로 공급 가격 400원인 지우개 2개를 사려고 해요. 부가 가치세까지 내고 남는 돈은 얼마인가요?',ARRAY['M5-1-u1-X12','M5-1-u1-X09','M5-1-u1-X10']::text[],false,'{"seq":6,"concept":"M5-1-u1-C8","difficulty":3,"kind":"mc","stem":"1000원으로 공급 가격 400원인 지우개 2개를 사려고 해요. 부가 가치세까지 내고 남는 돈은 얼마인가요?","options":[{"t":"120원","correct":true},{"t":"200원","mis":"M5-1-u1-X12"},{"t":"920원","mis":"M5-1-u1-X09"},{"t":"280원","mis":"M5-1-u1-X10"}],"explanation":["공급 가격 400 × 2 = 800원, 세금 800 ÷ 10 = 80원이에요.","낸 돈은 800 + 80 = 880원이에요.","남는 돈은 1000 − 880 = 120원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_challenge#7','math',5,1,'u1','L08','g5_1_math_u1_L08_challenge','lesson_challenge','M5-1-u1-C8',3,'mc','auto','다음 중 식의 값이 나머지와 다른 것은 어느 것인가요?',ARRAY['M5-1-u1-X14']::text[],false,'{"seq":7,"concept":"M5-1-u1-C8","difficulty":3,"kind":"mc","stem":"다음 중 식의 값이 나머지와 다른 것은 어느 것인가요?","options":[{"t":"3000 + 2000 ÷ 10","correct":true},{"t":"(3000 + 2000) ÷ 10","mis":"M5-1-u1-X14"},{"t":"3000 ÷ 10 + 2000 ÷ 10","mis":"M5-1-u1-X14"},{"t":"300 + 200","mis":"M5-1-u1-X14"}],"explanation":["(3000 + 2000) ÷ 10 = 500 · 3000 ÷ 10 + 2000 ÷ 10 = 500 · 300 + 200 = 500.","3000 + 2000 ÷ 10은 나눗셈 먼저 — 3000 + 200 = 3200이에요.","( )를 빼면 3000은 10으로 나누어지지 않아 값이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_challenge#8','math',5,1,'u1','L08','g5_1_math_u1_L08_challenge','lesson_challenge','M5-1-u1-C8',4,'essay','teacher','아이스크림 1통(공급 가격 2400원)과 과자 3봉지(1봉지 800원)를 샀어요. 낸 부가 가치세를 두 가지 식으로 나타내 계산하고, 두 답이 같은 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u1-C8","difficulty":4,"kind":"essay","stem":"아이스크림 1통(공급 가격 2400원)과 과자 3봉지(1봉지 800원)를 샀어요. 낸 부가 가치세를 두 가지 식으로 나타내 계산하고, 두 답이 같은 까닭을 쓰세요.","answer_guide":{"answer":"예: (2400 + 800 × 3) ÷ 10 = 4800 ÷ 10 = 480, 2400 ÷ 10 + 800 ÷ 10 × 3 = 240 + 240 = 480. 모두 모아 10등분하든 각각 10등분해 모으든 같은 전체를 같은 크기로 나눈 것이라 답이 같다.","scoring_points":["한 가지 식으로 480을 구했는가","다른 식으로 480을 구했는가","같은 전체를 같은 크기로 나눈 것이라는 까닭을 썼는가"]},"explanation":["묶어서 나누기 — 480이에요.","각각 나눠 더하기 — 480이에요.","같은 전체를 같은 크기로 나누어서 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_challenge#9','math',5,1,'u1','L08','g5_1_math_u1_L08_challenge','lesson_challenge','M5-1-u1-C8',4,'essay','teacher','연필 5자루(1자루 공급 가격 600원)와 지우개 2개(1개 공급 가격 500원)를 사고 5000원을 냈어요. 부가 가치세까지 낸 뒤 받을 거스름돈을 하나의 식으로 세워 구하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-1-u1-C8","difficulty":4,"kind":"essay","stem":"연필 5자루(1자루 공급 가격 600원)와 지우개 2개(1개 공급 가격 500원)를 사고 5000원을 냈어요. 부가 가치세까지 낸 뒤 받을 거스름돈을 하나의 식으로 세워 구하세요.","answer_guide":{"answer":"예: 공급 가격은 600 × 5 + 500 × 2 = 4000원, 세금은 400원이다. 하나의 식: 5000 − (600 × 5 + 500 × 2 + (600 × 5 + 500 × 2) ÷ 10) = 5000 − (4000 + 400) = 600원.","scoring_points":["공급 가격 4000원을 구했는가","부가 가치세 400원을 구했는가","거스름돈 600원을 구하고 식을 세웠는가"]},"explanation":["공급 가격 600 × 5 + 500 × 2 = 4000원이에요.","세금 4000 ÷ 10 = 400원이에요.","거스름돈 5000 − 4400 = 600원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_L08_challenge#10','math',5,1,'u1','L08','g5_1_math_u1_L08_challenge','lesson_challenge','M5-1-u1-C8',4,'mc','auto','공급 가격이 각각 1800원, 2200원인 물건 두 개를 샀어요. 낸 부가 가치세가 가장 바르게 구해진 것은 어느 것인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X11']::text[],false,'{"seq":10,"concept":"M5-1-u1-C8","difficulty":4,"kind":"mc","stem":"공급 가격이 각각 1800원, 2200원인 물건 두 개를 샀어요. 낸 부가 가치세가 가장 바르게 구해진 것은 어느 것인가요?","options":[{"t":"(1800 + 2200) ÷ 10 = 400원","correct":true},{"t":"1800 + 2200 ÷ 10 = 2020원","mis":"M5-1-u1-X06"},{"t":"(1800 + 2200) × 10 = 40000원","mis":"M5-1-u1-X11"},{"t":"(1800 + 2200) ÷ 100 = 40원","mis":"M5-1-u1-X11"}],"explanation":["공급 가격 전체를 ( )로 묶어 10으로 나눠요.","(1800 + 2200) ÷ 10 = 4000 ÷ 10 = 400원이에요.","( )를 빼면 2200만 10으로 나누어져 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#1','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C1',1,'mc','auto','3000원으로 500원짜리 지우개 2개를 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u1-X09']::text[],false,'{"seq":1,"concept":"M5-1-u1-C1","difficulty":1,"kind":"mc","stem":"3000원으로 500원짜리 지우개 2개를 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3000 − 500 × 2","correct":true},{"t":"3000 + 500 × 2","mis":"M5-1-u1-X09"},{"t":"3000 × 2 − 500","mis":"M5-1-u1-X09"},{"t":"3000 − 500 + 2","mis":"M5-1-u1-X09"}],"explanation":["지우개 값은 500 × 2예요.","가진 돈에서 지우개 값을 빼요.","한 줄로 이으면 3000 − 500 × 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#2','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C2',1,'sa','auto','24 − 9 + 3을 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M5-1-u1-C2","difficulty":1,"kind":"sa","stem":"24 − 9 + 3을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 24 − 9 = 15 → ② 15 + 3 = 18이에요.","그래서 24 − 9 + 3 = 18이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#3','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C2',2,'error','auto','준서는 40 − 15 + 5를 계산해 20이라고 답했어요. 준서가 잘못한 것은 무엇인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X10','M5-1-u1-X14']::text[],true,'{"seq":3,"concept":"M5-1-u1-C2","difficulty":2,"kind":"error","stem":"준서는 40 − 15 + 5를 계산해 20이라고 답했어요. 준서가 잘못한 것은 무엇인가요?","options":[{"t":"뒤의 15 + 5를 먼저 했다","correct":true,"mis_target":"M5-1-u1-X01"},{"t":"40 − 15를 잘못 뺐다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["덧셈과 뺄셈만 있으면 앞에서부터 계산해요.","40 − 15 = 25, 25 + 5 = 30이 맞아요.","준서는 15 + 5 = 20을 먼저 해서 40 − 20 = 20이 나왔어요."],"variant_rule":{"alt":[{"stem":"하윤이는 52 − 17 + 9를 계산해 26이라고 답했어요. 하윤이가 잘못한 것은 무엇인가요?","options":[{"t":"뒤의 17 + 9를 먼저 했다","correct":true,"mis_target":"M5-1-u1-X01"},{"t":"52 − 17을 잘못 뺐다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["앞에서부터 계산해요.","52 − 17 = 35, 35 + 9 = 44가 맞아요.","하윤이는 17 + 9 = 26을 먼저 해서 52 − 26 = 26이 나왔어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#4','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C3',1,'mc','auto','24 ÷ 4 × 3을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X02','M5-1-u1-X10']::text[],false,'{"seq":4,"concept":"M5-1-u1-C3","difficulty":1,"kind":"mc","stem":"24 ÷ 4 × 3을 계산하면 얼마인가요?","options":[{"t":"18","correct":true},{"t":"2","mis":"M5-1-u1-X02"},{"t":"28","mis":"M5-1-u1-X10"},{"t":"8","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 24 ÷ 4 = 6 → ② 6 × 3 = 18이에요.","그래서 24 ÷ 4 × 3 = 18이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#5','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C3',2,'sa','auto','쿠키 24개를 접시 4개에 똑같이 나누어 담고, 그중 3접시를 교실로 가져가요. 가져가는 쿠키는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M5-1-u1-C3","difficulty":2,"kind":"sa","stem":"쿠키 24개를 접시 4개에 똑같이 나누어 담고, 그중 3접시를 교실로 가져가요. 가져가는 쿠키는 몇 개인가요? 숫자로 쓰세요.","answer":["18","18개"],"explanation":["24 ÷ 4 × 3을 앞에서부터 계산해요.","24 ÷ 4 = 6, 6 × 3 = 18.","18개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#6','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C3',3,'mc','auto','48 ÷ 4 × 2와 48 ÷ (4 × 2)의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],false,'{"seq":6,"concept":"M5-1-u1-C3","difficulty":3,"kind":"mc","stem":"48 ÷ 4 × 2와 48 ÷ (4 × 2)의 계산 결과의 차는 얼마인가요?","options":[{"t":"18","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"24","mis":"M5-1-u1-X14"},{"t":"6","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","48 ÷ 4 × 2 = 24 · 48 ÷ (4 × 2) = 6","두 결과의 차는 24 − 6 = 18이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#7','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C4',1,'mc','auto','1000 − 350 × 2에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X03']::text[],false,'{"seq":7,"concept":"M5-1-u1-C4","difficulty":1,"kind":"mc","stem":"1000 − 350 × 2에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"350 × 2","correct":true},{"t":"1000 − 350","mis":"M5-1-u1-X03"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X03"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","그래서 가장 먼저 계산할 것은 350 × 2예요.","① 350 × 2 = 700 → ② 1000 − 700 = 300이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#8','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C4',2,'sa','auto','7 + 6 × 5를 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u1-C4","difficulty":2,"kind":"sa","stem":"7 + 6 × 5를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 6 × 5 = 30 → ② 7 + 30 = 37이에요.","그래서 7 + 6 × 5 = 37이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#9','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C4',3,'mc','auto','50 − □ × 3 = 26에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X03']::text[],false,'{"seq":9,"concept":"M5-1-u1-C4","difficulty":3,"kind":"mc","stem":"50 − □ × 3 = 26에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"24","mis":"M5-1-u1-X13"},{"t":"12","mis":"M5-1-u1-X03"},{"t":"6","mis":"M5-1-u1-X13"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 26이 되어야 해요.","거꾸로 되돌리면 □ = 8이에요.","확인: 50 − 8 × 3 → ① 8 × 3 = 24 → ② 50 − 24 = 26"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#10','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C5',1,'mc','auto','30 − 24 ÷ 6을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X04','M5-1-u1-X10']::text[],false,'{"seq":10,"concept":"M5-1-u1-C5","difficulty":1,"kind":"mc","stem":"30 − 24 ÷ 6을 계산하면 얼마인가요?","options":[{"t":"26","correct":true},{"t":"1","mis":"M5-1-u1-X04"},{"t":"36","mis":"M5-1-u1-X10"},{"t":"16","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 24 ÷ 6 = 4 → ② 30 − 4 = 26이에요.","그래서 30 − 24 ÷ 6 = 26이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#11','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C5',2,'error','auto','민재는 18 + 12 ÷ 3을 계산해 10이라고 답했어요. 민재가 잘못한 것은 무엇인가요?',ARRAY['M5-1-u1-X04','M5-1-u1-X10','M5-1-u1-X14']::text[],false,'{"seq":11,"concept":"M5-1-u1-C5","difficulty":2,"kind":"error","stem":"민재는 18 + 12 ÷ 3을 계산해 10이라고 답했어요. 민재가 잘못한 것은 무엇인가요?","options":[{"t":"앞의 18 + 12를 먼저 했다","correct":true,"mis_target":"M5-1-u1-X04"},{"t":"12 ÷ 3을 잘못 나눴다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["나눗셈을 먼저 해요.","12 ÷ 3 = 4, 18 + 4 = 22가 맞아요.","민재는 18 + 12 = 30을 먼저 해서 30 ÷ 3 = 10이 나왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#12','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C5',3,'mc','auto','사과 48개를 6상자에 똑같이 나누어 담았어요. 한 상자에서 사과 3개를 꺼냈다면 그 상자에 남은 사과는 몇 개인가요?',ARRAY['M5-1-u1-X09','M5-1-u1-X04','M5-1-u1-X10']::text[],false,'{"seq":12,"concept":"M5-1-u1-C5","difficulty":3,"kind":"mc","stem":"사과 48개를 6상자에 똑같이 나누어 담았어요. 한 상자에서 사과 3개를 꺼냈다면 그 상자에 남은 사과는 몇 개인가요?","options":[{"t":"5개","correct":true},{"t":"15개","mis":"M5-1-u1-X09"},{"t":"45개","mis":"M5-1-u1-X04"},{"t":"7개","mis":"M5-1-u1-X10"}],"explanation":["48 ÷ 6 − 3이에요.","48 ÷ 6 = 8, 8 − 3 = 5.","5개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#13','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C6',1,'mc','auto','100 − (30 + 45)를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X10']::text[],false,'{"seq":13,"concept":"M5-1-u1-C6","difficulty":1,"kind":"mc","stem":"100 − (30 + 45)를 계산하면 얼마인가요?","options":[{"t":"25","correct":true},{"t":"115","mis":"M5-1-u1-X06"},{"t":"35","mis":"M5-1-u1-X10"},{"t":"15","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요.","① 30 + 45 = 75 → ② 100 − 75 = 25예요.","그래서 100 − (30 + 45) = 25예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#14','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C6',2,'sa','auto','(12 + 8) ÷ 5를 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M5-1-u1-C6","difficulty":2,"kind":"sa","stem":"(12 + 8) ÷ 5를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 12 + 8 = 20 → ② 20 ÷ 5 = 4예요.","그래서 (12 + 8) ÷ 5 = 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#15','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C6',3,'mc','auto','24 ÷ (4 + 2)와 24 ÷ 4 + 2의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14','M5-1-u1-X10']::text[],false,'{"seq":15,"concept":"M5-1-u1-C6","difficulty":3,"kind":"mc","stem":"24 ÷ (4 + 2)와 24 ÷ 4 + 2의 계산 결과의 차는 얼마인가요?","options":[{"t":"4","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"8","mis":"M5-1-u1-X14"},{"t":"14","mis":"M5-1-u1-X10"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","24 ÷ (4 + 2) = 4 · 24 ÷ 4 + 2 = 8","두 결과의 차는 8 − 4 = 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#16','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C7',1,'mc','auto','12 + 3 × 4 − 6에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X03']::text[],false,'{"seq":16,"concept":"M5-1-u1-C7","difficulty":1,"kind":"mc","stem":"12 + 3 × 4 − 6에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"3 × 4","correct":true},{"t":"12 + 3","mis":"M5-1-u1-X03"},{"t":"4 − 6","mis":"M5-1-u1-X03"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X03"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","그래서 가장 먼저 계산할 것은 3 × 4예요.","① 3 × 4 = 12 → ② 12 + 12 = 24 → ③ 24 − 6 = 18이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#17','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C7',2,'mc','auto','12 + 3 × 4 − 6을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X10']::text[],false,'{"seq":17,"concept":"M5-1-u1-C7","difficulty":2,"kind":"mc","stem":"12 + 3 × 4 − 6을 계산하면 얼마인가요?","options":[{"t":"18","correct":true},{"t":"54","mis":"M5-1-u1-X03"},{"t":"28","mis":"M5-1-u1-X10"},{"t":"8","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 3 × 4 = 12 → ② 12 + 12 = 24 → ③ 24 − 6 = 18이에요.","그래서 12 + 3 × 4 − 6 = 18이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#18','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C7',2,'match','auto','계산식과 계산 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":18,"concept":"M5-1-u1-C7","difficulty":2,"kind":"match","stem":"계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"18 + 24 ÷ 6 × 2","r":"26"},{"l":"(18 + 24) ÷ 6 × 2","r":"14"},{"l":"18 + 24 ÷ (6 × 2)","r":"20"}],"mis":"M5-1-u1-X08","explanation":["식마다 계산 순서를 지켜 셈해요.","18 + 24 ÷ 6 × 2 = 26 · (18 + 24) ÷ 6 × 2 = 14 · 18 + 24 ÷ (6 × 2) = 20","( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#19','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C7',3,'mc','auto','36 ÷ (9 − 5) + 7 × 3 − 8을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X10']::text[],false,'{"seq":19,"concept":"M5-1-u1-C7","difficulty":3,"kind":"mc","stem":"36 ÷ (9 − 5) + 7 × 3 − 8을 계산하면 얼마인가요?","options":[{"t":"22","correct":true},{"t":"40","mis":"M5-1-u1-X03"},{"t":"32","mis":"M5-1-u1-X10"},{"t":"12","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 9 − 5 = 4 → ② 36 ÷ 4 = 9 → ③ 7 × 3 = 21 → ④ 9 + 21 = 30 → ⑤ 30 − 8 = 22예요.","그래서 36 ÷ (9 − 5) + 7 × 3 − 8 = 22예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#20','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C7',4,'mc','auto','(8 + □) × 2 − 6 = 20에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X08']::text[],false,'{"seq":20,"concept":"M5-1-u1-C7","difficulty":4,"kind":"mc","stem":"(8 + □) × 2 − 6 = 20에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"5","correct":true},{"t":"13","mis":"M5-1-u1-X13"},{"t":"3","mis":"M5-1-u1-X13"},{"t":"1","mis":"M5-1-u1-X08"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 20이 되어야 해요.","거꾸로 되돌리면 □ = 5예요.","확인: (8 + 5) × 2 − 6 → ① 8 + 5 = 13 → ② 13 × 2 = 26 → ③ 26 − 6 = 20"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#21','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C8',1,'mc','auto','공급 가격이 3200원인 물건을 샀어요. 이때 낸 부가 가치세는 얼마인가요?',ARRAY['M5-1-u1-X11','M5-1-u1-X12']::text[],false,'{"seq":21,"concept":"M5-1-u1-C8","difficulty":1,"kind":"mc","stem":"공급 가격이 3200원인 물건을 샀어요. 이때 낸 부가 가치세는 얼마인가요?","options":[{"t":"320원","correct":true},{"t":"32000원","mis":"M5-1-u1-X11"},{"t":"32원","mis":"M5-1-u1-X11"},{"t":"3520원","mis":"M5-1-u1-X12"}],"explanation":["부가 가치세는 공급 가격 ÷ 10이에요.","3200 ÷ 10 = 320이에요.","320원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#22','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C8',2,'mc','auto','색연필 1세트(공급 가격 5000원)와 색종이 2묶음(1묶음 600원)을 샀어요. 낸 부가 가치세는 얼마인가요?',ARRAY['M5-1-u1-X11','M5-1-u1-X06']::text[],false,'{"seq":22,"concept":"M5-1-u1-C8","difficulty":2,"kind":"mc","stem":"색연필 1세트(공급 가격 5000원)와 색종이 2묶음(1묶음 600원)을 샀어요. 낸 부가 가치세는 얼마인가요?","options":[{"t":"620원","correct":true},{"t":"6200원","mis":"M5-1-u1-X11"},{"t":"560원","mis":"M5-1-u1-X06"},{"t":"62원","mis":"M5-1-u1-X11"}],"explanation":["(5000 + 600 × 2) ÷ 10이에요.","600 × 2 = 1200, 5000 + 1200 = 6200.","6200 ÷ 10 = 620원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#23','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C8',3,'mc','auto','공급 가격이 2000원인 물건 하나를 살 때 실제로 내는 돈은 얼마인가요?',ARRAY['M5-1-u1-X12','M5-1-u1-X11']::text[],false,'{"seq":23,"concept":"M5-1-u1-C8","difficulty":3,"kind":"mc","stem":"공급 가격이 2000원인 물건 하나를 살 때 실제로 내는 돈은 얼마인가요?","options":[{"t":"2200원","correct":true},{"t":"2000원","mis":"M5-1-u1-X12"},{"t":"1800원","mis":"M5-1-u1-X12"},{"t":"2010원","mis":"M5-1-u1-X11"}],"explanation":["세금은 2000 ÷ 10 = 200원이에요.","공급 가격과 세금을 더해요.","2200원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#24','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C7',4,'essay','teacher','12 + 3 × 4 − 6을 계산하는 순서를 ①, ②, ③으로 쓰고, 왜 그 순서로 계산하는지 「덩어리」라는 말을 넣어 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"M5-1-u1-C7","difficulty":4,"kind":"essay","stem":"12 + 3 × 4 − 6을 계산하는 순서를 ①, ②, ③으로 쓰고, 왜 그 순서로 계산하는지 「덩어리」라는 말을 넣어 설명하세요.","answer_guide":{"answer":"예: ① 3 × 4 = 12 ② 12 + 12 = 24 ③ 24 − 6 = 18. 3 × 4는 하나의 양(덩어리)이라 먼저 구하고, 남은 덧셈과 뺄셈은 같은 층이라 앞에서부터 계산한다.","scoring_points":["3 × 4를 먼저 계산했는가","앞에서부터 해 18을 구했는가","곱셈 부분이 덩어리라는 까닭을 썼는가"]},"explanation":["① 3 × 4 = 12 ② 24 ③ 18이에요.","3 × 4는 하나의 덩어리예요.","덧셈·뺄셈은 앞에서부터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_a#25','math',5,1,'u1','','g5_1_math_u1_review_a','unit_review','M5-1-u1-C6',4,'essay','teacher','「3000원으로 800원짜리 우유와 700원짜리 빵을 함께 샀다」를 ( )를 써서 하나의 식으로 나타내 남은 돈을 구하고, ( )를 쓴 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-1-u1-C6","difficulty":4,"kind":"essay","stem":"「3000원으로 800원짜리 우유와 700원짜리 빵을 함께 샀다」를 ( )를 써서 하나의 식으로 나타내 남은 돈을 구하고, ( )를 쓴 까닭을 쓰세요.","answer_guide":{"answer":"예: 3000 − (800 + 700) = 3000 − 1500 = 1500원. 우유와 빵을 함께 샀으니 두 물건값이 한 묶음이라 ( )로 나타냈다.","scoring_points":["3000 − (800 + 700)으로 식을 세웠는가","1500원을 구했는가","함께 산 물건값이 한 덩어리라는 까닭을 썼는가"]},"explanation":["함께 산 물건값 800 + 700이 한 묶음이에요.","3000 − 1500 = 1500원이에요.","( )는 한 덩어리를 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#1','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C1',1,'mc','auto','5000원으로 800원짜리 공책 3개를 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u1-X09']::text[],false,'{"seq":1,"concept":"M5-1-u1-C1","difficulty":1,"kind":"mc","stem":"5000원으로 800원짜리 공책 3개를 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"5000 − 800 × 3","correct":true},{"t":"5000 + 800 × 3","mis":"M5-1-u1-X09"},{"t":"5000 × 3 − 800","mis":"M5-1-u1-X09"},{"t":"5000 − 800 + 3","mis":"M5-1-u1-X09"}],"explanation":["공책 값은 800 × 3이에요.","가진 돈에서 공책 값을 빼요.","한 줄로 이으면 5000 − 800 × 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#2','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C2',1,'sa','auto','40 − 15 + 7을 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M5-1-u1-C2","difficulty":1,"kind":"sa","stem":"40 − 15 + 7을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 40 − 15 = 25 → ② 25 + 7 = 32예요.","그래서 40 − 15 + 7 = 32예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#3','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C2',2,'error','auto','은호는 61 − 24 + 13을 계산해 24라고 답했어요. 은호가 잘못한 것은 무엇인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X10','M5-1-u1-X14']::text[],false,'{"seq":3,"concept":"M5-1-u1-C2","difficulty":2,"kind":"error","stem":"은호는 61 − 24 + 13을 계산해 24라고 답했어요. 은호가 잘못한 것은 무엇인가요?","options":[{"t":"뒤의 24 + 13을 먼저 했다","correct":true,"mis_target":"M5-1-u1-X01"},{"t":"61 − 24를 잘못 뺐다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["앞에서부터 계산해요.","61 − 24 = 37, 37 + 13 = 50이 맞아요.","은호는 24 + 13 = 37을 먼저 해서 61 − 37 = 24가 나왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#4','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C3',1,'mc','auto','36 ÷ 9 × 7을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X10']::text[],false,'{"seq":4,"concept":"M5-1-u1-C3","difficulty":1,"kind":"mc","stem":"36 ÷ 9 × 7을 계산하면 얼마인가요?","options":[{"t":"28","correct":true},{"t":"38","mis":"M5-1-u1-X10"},{"t":"18","mis":"M5-1-u1-X10"},{"t":"30","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 36 ÷ 9 = 4 → ② 4 × 7 = 28이에요.","그래서 36 ÷ 9 × 7 = 28이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#5','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C3',2,'sa','auto','귤 40개를 바구니 5개에 똑같이 나누어 담고, 그중 2바구니를 할머니께 드려요. 드리는 귤은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M5-1-u1-C3","difficulty":2,"kind":"sa","stem":"귤 40개를 바구니 5개에 똑같이 나누어 담고, 그중 2바구니를 할머니께 드려요. 드리는 귤은 몇 개인가요? 숫자로 쓰세요.","answer":["16","16개"],"explanation":["40 ÷ 5 × 2를 앞에서부터 계산해요.","40 ÷ 5 = 8, 8 × 2 = 16.","16개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#6','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C3',3,'mc','auto','60 ÷ 5 × 3과 60 ÷ (5 × 3)의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],false,'{"seq":6,"concept":"M5-1-u1-C3","difficulty":3,"kind":"mc","stem":"60 ÷ 5 × 3과 60 ÷ (5 × 3)의 계산 결과의 차는 얼마인가요?","options":[{"t":"32","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"36","mis":"M5-1-u1-X14"},{"t":"4","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","60 ÷ 5 × 3 = 36 · 60 ÷ (5 × 3) = 4","두 결과의 차는 36 − 4 = 32예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#7','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C4',1,'mc','auto','5 + 3 × 4에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X03']::text[],false,'{"seq":7,"concept":"M5-1-u1-C4","difficulty":1,"kind":"mc","stem":"5 + 3 × 4에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"3 × 4","correct":true},{"t":"5 + 3","mis":"M5-1-u1-X03"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X03"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","그래서 가장 먼저 계산할 것은 3 × 4예요.","① 3 × 4 = 12 → ② 5 + 12 = 17이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#8','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C4',2,'sa','auto','50 − 4 × 6을 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u1-C4","difficulty":2,"kind":"sa","stem":"50 − 4 × 6을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 4 × 6 = 24 → ② 50 − 24 = 26이에요.","그래서 50 − 4 × 6 = 26이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#9','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C4',3,'mc','auto','60 − □ × 4 = 32에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X03']::text[],false,'{"seq":9,"concept":"M5-1-u1-C4","difficulty":3,"kind":"mc","stem":"60 − □ × 4 = 32에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"7","correct":true},{"t":"28","mis":"M5-1-u1-X13"},{"t":"8","mis":"M5-1-u1-X03"},{"t":"23","mis":"M5-1-u1-X13"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 32가 되어야 해요.","거꾸로 되돌리면 □ = 7이에요.","확인: 60 − 7 × 4 → ① 7 × 4 = 28 → ② 60 − 28 = 32"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#10','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C5',1,'mc','auto','18 + 12 ÷ 3을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X04','M5-1-u1-X10']::text[],false,'{"seq":10,"concept":"M5-1-u1-C5","difficulty":1,"kind":"mc","stem":"18 + 12 ÷ 3을 계산하면 얼마인가요?","options":[{"t":"22","correct":true},{"t":"10","mis":"M5-1-u1-X04"},{"t":"32","mis":"M5-1-u1-X10"},{"t":"12","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 12 ÷ 3 = 4 → ② 18 + 4 = 22예요.","그래서 18 + 12 ÷ 3 = 22예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#11','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C5',2,'error','auto','소율이는 20 + 16 ÷ 4를 계산해 9라고 답했어요. 소율이가 잘못한 것은 무엇인가요?',ARRAY['M5-1-u1-X04','M5-1-u1-X10','M5-1-u1-X14']::text[],false,'{"seq":11,"concept":"M5-1-u1-C5","difficulty":2,"kind":"error","stem":"소율이는 20 + 16 ÷ 4를 계산해 9라고 답했어요. 소율이가 잘못한 것은 무엇인가요?","options":[{"t":"앞의 20 + 16을 먼저 했다","correct":true,"mis_target":"M5-1-u1-X04"},{"t":"16 ÷ 4를 잘못 나눴다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["나눗셈을 먼저 해요.","16 ÷ 4 = 4, 20 + 4 = 24가 맞아요.","소율이는 20 + 16 = 36을 먼저 해서 36 ÷ 4 = 9가 나왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#12','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C5',3,'mc','auto','구슬 63개를 7봉지에 똑같이 나누어 담았어요. 한 봉지에서 구슬 4개를 꺼냈다면 그 봉지에 남은 구슬은 몇 개인가요?',ARRAY['M5-1-u1-X09','M5-1-u1-X04','M5-1-u1-X10']::text[],false,'{"seq":12,"concept":"M5-1-u1-C5","difficulty":3,"kind":"mc","stem":"구슬 63개를 7봉지에 똑같이 나누어 담았어요. 한 봉지에서 구슬 4개를 꺼냈다면 그 봉지에 남은 구슬은 몇 개인가요?","options":[{"t":"5개","correct":true},{"t":"23개","mis":"M5-1-u1-X09"},{"t":"59개","mis":"M5-1-u1-X04"},{"t":"7개","mis":"M5-1-u1-X10"}],"explanation":["63 ÷ 7 − 4예요.","63 ÷ 7 = 9, 9 − 4 = 5.","5개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#13','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C6',1,'mc','auto','90 − (27 + 38)을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X10']::text[],false,'{"seq":13,"concept":"M5-1-u1-C6","difficulty":1,"kind":"mc","stem":"90 − (27 + 38)을 계산하면 얼마인가요?","options":[{"t":"25","correct":true},{"t":"101","mis":"M5-1-u1-X06"},{"t":"35","mis":"M5-1-u1-X10"},{"t":"15","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요.","① 27 + 38 = 65 → ② 90 − 65 = 25예요.","그래서 90 − (27 + 38) = 25예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#14','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C6',2,'sa','auto','(15 + 21) ÷ 4를 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M5-1-u1-C6","difficulty":2,"kind":"sa","stem":"(15 + 21) ÷ 4를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 15 + 21 = 36 → ② 36 ÷ 4 = 9예요.","그래서 (15 + 21) ÷ 4 = 9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#15','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C6',3,'mc','auto','36 ÷ (6 + 3)과 36 ÷ 6 + 3의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],false,'{"seq":15,"concept":"M5-1-u1-C6","difficulty":3,"kind":"mc","stem":"36 ÷ (6 + 3)과 36 ÷ 6 + 3의 계산 결과의 차는 얼마인가요?","options":[{"t":"5","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"4","mis":"M5-1-u1-X14"},{"t":"9","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","36 ÷ (6 + 3) = 4 · 36 ÷ 6 + 3 = 9","두 결과의 차는 9 − 4 = 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#16','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C7',1,'mc','auto','(12 + 3) × 4 − 6에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X06']::text[],false,'{"seq":16,"concept":"M5-1-u1-C7","difficulty":1,"kind":"mc","stem":"(12 + 3) × 4 − 6에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"12 + 3","correct":true},{"t":"3 × 4","mis":"M5-1-u1-X06"},{"t":"4 − 6","mis":"M5-1-u1-X06"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X06"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","그래서 가장 먼저 계산할 것은 12 + 3이에요.","① 12 + 3 = 15 → ② 15 × 4 = 60 → ③ 60 − 6 = 54예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#17','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C7',2,'mc','auto','(12 + 3) × 4 − 6을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X10']::text[],false,'{"seq":17,"concept":"M5-1-u1-C7","difficulty":2,"kind":"mc","stem":"(12 + 3) × 4 − 6을 계산하면 얼마인가요?","options":[{"t":"54","correct":true},{"t":"18","mis":"M5-1-u1-X06"},{"t":"64","mis":"M5-1-u1-X10"},{"t":"44","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 12 + 3 = 15 → ② 15 × 4 = 60 → ③ 60 − 6 = 54예요.","그래서 (12 + 3) × 4 − 6 = 54예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#18','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C7',2,'match','auto','계산식과 계산 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":18,"concept":"M5-1-u1-C7","difficulty":2,"kind":"match","stem":"계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"30 − 12 ÷ 4 × 3","r":"21"},{"l":"(30 − 12) ÷ 6 × 3","r":"9"},{"l":"30 − 12 ÷ (4 × 3)","r":"29"}],"mis":"M5-1-u1-X08","explanation":["식마다 계산 순서를 지켜 셈해요.","30 − 12 ÷ 4 × 3 = 21 · (30 − 12) ÷ 6 × 3 = 9 · 30 − 12 ÷ (4 × 3) = 29","( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#19','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C7',3,'mc','auto','48 ÷ (11 − 5) + 6 × 4 − 9를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X03','M5-1-u1-X10']::text[],false,'{"seq":19,"concept":"M5-1-u1-C7","difficulty":3,"kind":"mc","stem":"48 ÷ (11 − 5) + 6 × 4 − 9를 계산하면 얼마인가요?","options":[{"t":"23","correct":true},{"t":"47","mis":"M5-1-u1-X03"},{"t":"33","mis":"M5-1-u1-X10"},{"t":"13","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 11 − 5 = 6 → ② 48 ÷ 6 = 8 → ③ 6 × 4 = 24 → ④ 8 + 24 = 32 → ⑤ 32 − 9 = 23이에요.","그래서 48 ÷ (11 − 5) + 6 × 4 − 9 = 23이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#20','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C7',4,'mc','auto','(6 + □) × 3 − 9 = 30에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X08']::text[],false,'{"seq":20,"concept":"M5-1-u1-C7","difficulty":4,"kind":"mc","stem":"(6 + □) × 3 − 9 = 30에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"7","correct":true},{"t":"13","mis":"M5-1-u1-X13"},{"t":"4","mis":"M5-1-u1-X13"},{"t":"5","mis":"M5-1-u1-X08"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 30이 되어야 해요.","거꾸로 되돌리면 □ = 7이에요.","확인: (6 + 7) × 3 − 9 → ① 6 + 7 = 13 → ② 13 × 3 = 39 → ③ 39 − 9 = 30"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#21','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C8',1,'mc','auto','공급 가격이 4500원인 물건을 샀어요. 이때 낸 부가 가치세는 얼마인가요?',ARRAY['M5-1-u1-X11','M5-1-u1-X12']::text[],false,'{"seq":21,"concept":"M5-1-u1-C8","difficulty":1,"kind":"mc","stem":"공급 가격이 4500원인 물건을 샀어요. 이때 낸 부가 가치세는 얼마인가요?","options":[{"t":"450원","correct":true},{"t":"45000원","mis":"M5-1-u1-X11"},{"t":"45원","mis":"M5-1-u1-X11"},{"t":"4950원","mis":"M5-1-u1-X12"}],"explanation":["공급 가격 ÷ 10이에요.","4500 ÷ 10 = 450이에요.","450원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#22','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C8',2,'mc','auto','필통 1개(공급 가격 3000원)와 공책 4권(1권 500원)을 샀어요. 낸 부가 가치세는 얼마인가요?',ARRAY['M5-1-u1-X11','M5-1-u1-X06']::text[],false,'{"seq":22,"concept":"M5-1-u1-C8","difficulty":2,"kind":"mc","stem":"필통 1개(공급 가격 3000원)와 공책 4권(1권 500원)을 샀어요. 낸 부가 가치세는 얼마인가요?","options":[{"t":"500원","correct":true},{"t":"5000원","mis":"M5-1-u1-X11"},{"t":"350원","mis":"M5-1-u1-X06"},{"t":"50원","mis":"M5-1-u1-X11"}],"explanation":["(3000 + 500 × 4) ÷ 10이에요.","500 × 4 = 2000, 3000 + 2000 = 5000.","5000 ÷ 10 = 500원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#23','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C8',3,'mc','auto','공급 가격이 3500원인 물건 하나를 살 때 실제로 내는 돈은 얼마인가요?',ARRAY['M5-1-u1-X12','M5-1-u1-X11']::text[],false,'{"seq":23,"concept":"M5-1-u1-C8","difficulty":3,"kind":"mc","stem":"공급 가격이 3500원인 물건 하나를 살 때 실제로 내는 돈은 얼마인가요?","options":[{"t":"3850원","correct":true},{"t":"3500원","mis":"M5-1-u1-X12"},{"t":"3150원","mis":"M5-1-u1-X12"},{"t":"3510원","mis":"M5-1-u1-X11"}],"explanation":["세금은 3500 ÷ 10 = 350원이에요.","공급 가격과 세금을 더해요.","3850원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#24','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C7',4,'essay','teacher','20 − 8 ÷ 2 + 5를 계산하는 순서를 ①, ②, ③으로 쓰고, 왜 그 순서로 계산하는지 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"M5-1-u1-C7","difficulty":4,"kind":"essay","stem":"20 − 8 ÷ 2 + 5를 계산하는 순서를 ①, ②, ③으로 쓰고, 왜 그 순서로 계산하는지 설명하세요.","answer_guide":{"answer":"예: ① 8 ÷ 2 = 4 ② 20 − 4 = 16 ③ 16 + 5 = 21. 8 ÷ 2는 이미 하나의 양이라 먼저 구하고, 남은 뺄셈과 덧셈은 같은 층이라 앞에서부터 계산한다.","scoring_points":["8 ÷ 2를 먼저 계산했는가","앞에서부터 해 21을 구했는가","나눗셈 부분이 하나의 양이라는 까닭을 썼는가"]},"explanation":["① 8 ÷ 2 = 4 ② 16 ③ 21이에요.","8 ÷ 2는 하나의 양이에요.","나머지는 앞에서부터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_b#25','math',5,1,'u1','','g5_1_math_u1_review_b','unit_review','M5-1-u1-C6',4,'essay','teacher','「5000원으로 1200원짜리 공책과 900원짜리 연필을 함께 샀다」를 ( )를 써서 하나의 식으로 나타내 남은 돈을 구하고, ( )를 쓴 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-1-u1-C6","difficulty":4,"kind":"essay","stem":"「5000원으로 1200원짜리 공책과 900원짜리 연필을 함께 샀다」를 ( )를 써서 하나의 식으로 나타내 남은 돈을 구하고, ( )를 쓴 까닭을 쓰세요.","answer_guide":{"answer":"예: 5000 − (1200 + 900) = 5000 − 2100 = 2900원. 공책과 연필을 함께 샀으니 두 물건값이 한 묶음이라 ( )로 나타냈다.","scoring_points":["5000 − (1200 + 900)으로 식을 세웠는가","2900원을 구했는가","한 덩어리라는 까닭을 썼는가"]},"explanation":["물건값 1200 + 900이 한 묶음이에요.","5000 − 2100 = 2900원이에요.","( )는 한 덩어리를 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#1','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C1',1,'mc','auto','2000원으로 300원짜리 연필 4개를 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u1-X09']::text[],false,'{"seq":1,"concept":"M5-1-u1-C1","difficulty":1,"kind":"mc","stem":"2000원으로 300원짜리 연필 4개를 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2000 − 300 × 4","correct":true},{"t":"2000 + 300 × 4","mis":"M5-1-u1-X09"},{"t":"2000 × 4 − 300","mis":"M5-1-u1-X09"},{"t":"2000 − 300 + 4","mis":"M5-1-u1-X09"}],"explanation":["연필 값은 300 × 4예요.","가진 돈에서 연필 값을 빼요.","한 줄로 이으면 2000 − 300 × 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#2','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C2',1,'sa','auto','52 − 17 + 9를 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M5-1-u1-C2","difficulty":1,"kind":"sa","stem":"52 − 17 + 9를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["44"],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 52 − 17 = 35 → ② 35 + 9 = 44예요.","그래서 52 − 17 + 9 = 44예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#3','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C2',2,'error','auto','지우는 75 − 32 + 18을 계산해 25라고 답했어요. 지우가 잘못한 것은 무엇인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X10','M5-1-u1-X14']::text[],false,'{"seq":3,"concept":"M5-1-u1-C2","difficulty":2,"kind":"error","stem":"지우는 75 − 32 + 18을 계산해 25라고 답했어요. 지우가 잘못한 것은 무엇인가요?","options":[{"t":"뒤의 32 + 18을 먼저 했다","correct":true,"mis_target":"M5-1-u1-X01"},{"t":"75 − 32를 잘못 뺐다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["앞에서부터 계산해요.","75 − 32 = 43, 43 + 18 = 61이 맞아요.","지우는 32 + 18 = 50을 먼저 해서 75 − 50 = 25가 나왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#4','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C3',1,'mc','auto','45 ÷ 5 × 6을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X10']::text[],false,'{"seq":4,"concept":"M5-1-u1-C3","difficulty":1,"kind":"mc","stem":"45 ÷ 5 × 6을 계산하면 얼마인가요?","options":[{"t":"54","correct":true},{"t":"64","mis":"M5-1-u1-X10"},{"t":"44","mis":"M5-1-u1-X10"},{"t":"56","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 45 ÷ 5 = 9 → ② 9 × 6 = 54예요.","그래서 45 ÷ 5 × 6 = 54예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#5','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C3',2,'sa','auto','구슬 42개를 7봉지에 똑같이 나누어 담고, 그중 4봉지를 동생에게 주었어요. 동생에게 준 구슬은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M5-1-u1-C3","difficulty":2,"kind":"sa","stem":"구슬 42개를 7봉지에 똑같이 나누어 담고, 그중 4봉지를 동생에게 주었어요. 동생에게 준 구슬은 몇 개인가요? 숫자로 쓰세요.","answer":["24","24개"],"explanation":["42 ÷ 7 × 4를 앞에서부터 계산해요.","42 ÷ 7 = 6, 6 × 4 = 24.","24개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#6','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C3',3,'mc','auto','72 ÷ 6 × 2와 72 ÷ (6 × 2)의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],false,'{"seq":6,"concept":"M5-1-u1-C3","difficulty":3,"kind":"mc","stem":"72 ÷ 6 × 2와 72 ÷ (6 × 2)의 계산 결과의 차는 얼마인가요?","options":[{"t":"18","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"24","mis":"M5-1-u1-X14"},{"t":"6","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","72 ÷ 6 × 2 = 24 · 72 ÷ (6 × 2) = 6","두 결과의 차는 24 − 6 = 18이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#7','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C4',1,'mc','auto','20 − 3 × 4에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X03']::text[],false,'{"seq":7,"concept":"M5-1-u1-C4","difficulty":1,"kind":"mc","stem":"20 − 3 × 4에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"3 × 4","correct":true},{"t":"20 − 3","mis":"M5-1-u1-X03"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X03"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","그래서 가장 먼저 계산할 것은 3 × 4예요.","① 3 × 4 = 12 → ② 20 − 12 = 8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#8','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C4',2,'sa','auto','9 + 4 × 8을 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u1-C4","difficulty":2,"kind":"sa","stem":"9 + 4 × 8을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["41"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 4 × 8 = 32 → ② 9 + 32 = 41이에요.","그래서 9 + 4 × 8 = 41이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#9','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C4',3,'mc','auto','45 − □ × 5 = 10에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X03']::text[],false,'{"seq":9,"concept":"M5-1-u1-C4","difficulty":3,"kind":"mc","stem":"45 − □ × 5 = 10에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"7","correct":true},{"t":"35","mis":"M5-1-u1-X13"},{"t":"11","mis":"M5-1-u1-X03"},{"t":"2","mis":"M5-1-u1-X13"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 10이 되어야 해요.","거꾸로 되돌리면 □ = 7이에요.","확인: 45 − 7 × 5 → ① 7 × 5 = 35 → ② 45 − 35 = 10"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#10','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C5',1,'mc','auto','50 − 32 ÷ 4를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X10']::text[],false,'{"seq":10,"concept":"M5-1-u1-C5","difficulty":1,"kind":"mc","stem":"50 − 32 ÷ 4를 계산하면 얼마인가요?","options":[{"t":"42","correct":true},{"t":"52","mis":"M5-1-u1-X10"},{"t":"32","mis":"M5-1-u1-X10"},{"t":"44","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 32 ÷ 4 = 8 → ② 50 − 8 = 42예요.","그래서 50 − 32 ÷ 4 = 42예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#11','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C5',2,'error','auto','건우는 34 + 22 ÷ 2를 계산해 28이라고 답했어요. 건우가 잘못한 것은 무엇인가요?',ARRAY['M5-1-u1-X04','M5-1-u1-X10','M5-1-u1-X14']::text[],false,'{"seq":11,"concept":"M5-1-u1-C5","difficulty":2,"kind":"error","stem":"건우는 34 + 22 ÷ 2를 계산해 28이라고 답했어요. 건우가 잘못한 것은 무엇인가요?","options":[{"t":"앞의 34 + 22를 먼저 했다","correct":true,"mis_target":"M5-1-u1-X04"},{"t":"22 ÷ 2를 잘못 나눴다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["나눗셈을 먼저 해요.","22 ÷ 2 = 11, 34 + 11 = 45가 맞아요.","건우는 34 + 22 = 56을 먼저 해서 56 ÷ 2 = 28이 나왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#12','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C5',3,'mc','auto','리본 50 cm 가운데 32 cm를 4조각으로 똑같이 잘라 한 조각을 썼어요. 남은 리본은 몇 cm인가요?',ARRAY['M5-1-u1-X09','M5-1-u1-X10']::text[],false,'{"seq":12,"concept":"M5-1-u1-C5","difficulty":3,"kind":"mc","stem":"리본 50 cm 가운데 32 cm를 4조각으로 똑같이 잘라 한 조각을 썼어요. 남은 리본은 몇 cm인가요?","options":[{"t":"42 cm","correct":true},{"t":"18 cm","mis":"M5-1-u1-X09"},{"t":"8 cm","mis":"M5-1-u1-X09"},{"t":"32 cm","mis":"M5-1-u1-X10"}],"explanation":["50 − 32 ÷ 4예요.","32 ÷ 4 = 8, 50 − 8 = 42.","42 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#13','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C6',1,'mc','auto','75 − (40 − 16)을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X10']::text[],false,'{"seq":13,"concept":"M5-1-u1-C6","difficulty":1,"kind":"mc","stem":"75 − (40 − 16)을 계산하면 얼마인가요?","options":[{"t":"51","correct":true},{"t":"19","mis":"M5-1-u1-X06"},{"t":"61","mis":"M5-1-u1-X10"},{"t":"41","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요.","① 40 − 16 = 24 → ② 75 − 24 = 51이에요.","그래서 75 − (40 − 16) = 51이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#14','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C6',2,'sa','auto','6 × (13 − 5)를 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M5-1-u1-C6","difficulty":2,"kind":"sa","stem":"6 × (13 − 5)를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 13 − 5 = 8 → ② 6 × 8 = 48이에요.","그래서 6 × (13 − 5) = 48이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#15','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C6',3,'mc','auto','60 − (15 + 25)와 60 − 15 + 25의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],false,'{"seq":15,"concept":"M5-1-u1-C6","difficulty":3,"kind":"mc","stem":"60 − (15 + 25)와 60 − 15 + 25의 계산 결과의 차는 얼마인가요?","options":[{"t":"50","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"20","mis":"M5-1-u1-X14"},{"t":"70","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","60 − (15 + 25) = 20 · 60 − 15 + 25 = 70","두 결과의 차는 70 − 20 = 50이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#16','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C7',1,'mc','auto','20 − 8 ÷ 2 + 5에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X04']::text[],false,'{"seq":16,"concept":"M5-1-u1-C7","difficulty":1,"kind":"mc","stem":"20 − 8 ÷ 2 + 5에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"8 ÷ 2","correct":true},{"t":"20 − 8","mis":"M5-1-u1-X04"},{"t":"2 + 5","mis":"M5-1-u1-X04"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X04"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","그래서 가장 먼저 계산할 것은 8 ÷ 2예요.","① 8 ÷ 2 = 4 → ② 20 − 4 = 16 → ③ 16 + 5 = 21이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#17','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C7',2,'mc','auto','20 − 8 ÷ 2 + 5를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X04','M5-1-u1-X10']::text[],false,'{"seq":17,"concept":"M5-1-u1-C7","difficulty":2,"kind":"mc","stem":"20 − 8 ÷ 2 + 5를 계산하면 얼마인가요?","options":[{"t":"21","correct":true},{"t":"11","mis":"M5-1-u1-X04"},{"t":"31","mis":"M5-1-u1-X10"},{"t":"23","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 8 ÷ 2 = 4 → ② 20 − 4 = 16 → ③ 16 + 5 = 21이에요.","그래서 20 − 8 ÷ 2 + 5 = 21이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#18','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C7',2,'match','auto','계산식과 계산 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":18,"concept":"M5-1-u1-C7","difficulty":2,"kind":"match","stem":"계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"40 − 8 × 3 + 6","r":"22"},{"l":"(40 − 8) × 3 + 6","r":"102"},{"l":"40 − 8 × (3 + 1)","r":"8"}],"mis":"M5-1-u1-X08","explanation":["식마다 계산 순서를 지켜 셈해요.","40 − 8 × 3 + 6 = 22 · (40 − 8) × 3 + 6 = 102 · 40 − 8 × (3 + 1) = 8","( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#19','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C7',3,'mc','auto','64 − (13 + 5) ÷ 3 × 4를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X10']::text[],false,'{"seq":19,"concept":"M5-1-u1-C7","difficulty":3,"kind":"mc","stem":"64 − (13 + 5) ÷ 3 × 4를 계산하면 얼마인가요?","options":[{"t":"40","correct":true},{"t":"50","mis":"M5-1-u1-X10"},{"t":"30","mis":"M5-1-u1-X10"},{"t":"42","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 13 + 5 = 18 → ② 18 ÷ 3 = 6 → ③ 6 × 4 = 24 → ④ 64 − 24 = 40이에요.","그래서 64 − (13 + 5) ÷ 3 × 4 = 40이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#20','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C7',4,'mc','auto','(5 + □) × 4 − 8 = 36에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X08']::text[],false,'{"seq":20,"concept":"M5-1-u1-C7","difficulty":4,"kind":"mc","stem":"(5 + □) × 4 − 8 = 36에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"6","correct":true},{"t":"11","mis":"M5-1-u1-X13"},{"t":"4","mis":"M5-1-u1-X13"},{"t":"3","mis":"M5-1-u1-X08"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 36이 되어야 해요.","거꾸로 되돌리면 □ = 6이에요.","확인: (5 + 6) × 4 − 8 → ① 5 + 6 = 11 → ② 11 × 4 = 44 → ③ 44 − 8 = 36"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#21','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C8',1,'mc','auto','공급 가격이 1800원인 물건을 샀어요. 이때 낸 부가 가치세는 얼마인가요?',ARRAY['M5-1-u1-X11','M5-1-u1-X12']::text[],false,'{"seq":21,"concept":"M5-1-u1-C8","difficulty":1,"kind":"mc","stem":"공급 가격이 1800원인 물건을 샀어요. 이때 낸 부가 가치세는 얼마인가요?","options":[{"t":"180원","correct":true},{"t":"18000원","mis":"M5-1-u1-X11"},{"t":"18원","mis":"M5-1-u1-X11"},{"t":"1980원","mis":"M5-1-u1-X12"}],"explanation":["공급 가격 ÷ 10이에요.","1800 ÷ 10 = 180이에요.","180원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#22','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C8',2,'mc','auto','아이스크림 1통(공급 가격 2400원)과 과자 3봉지(1봉지 800원)를 샀어요. 낸 부가 가치세는 얼마인가요?',ARRAY['M5-1-u1-X11','M5-1-u1-X06']::text[],false,'{"seq":22,"concept":"M5-1-u1-C8","difficulty":2,"kind":"mc","stem":"아이스크림 1통(공급 가격 2400원)과 과자 3봉지(1봉지 800원)를 샀어요. 낸 부가 가치세는 얼마인가요?","options":[{"t":"480원","correct":true},{"t":"4800원","mis":"M5-1-u1-X11"},{"t":"320원","mis":"M5-1-u1-X06"},{"t":"48원","mis":"M5-1-u1-X11"}],"explanation":["(2400 + 800 × 3) ÷ 10이에요.","800 × 3 = 2400, 2400 + 2400 = 4800.","4800 ÷ 10 = 480원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#23','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C8',3,'mc','auto','빵 2개(1개 공급 가격 1500원)와 우유 1개(1000원)를 샀어요. 낸 돈은 공급 가격과 부가 가치세의 합이에요. 낸 돈은 모두 얼마인가요?',ARRAY['M5-1-u1-X12','M5-1-u1-X06']::text[],false,'{"seq":23,"concept":"M5-1-u1-C8","difficulty":3,"kind":"mc","stem":"빵 2개(1개 공급 가격 1500원)와 우유 1개(1000원)를 샀어요. 낸 돈은 공급 가격과 부가 가치세의 합이에요. 낸 돈은 모두 얼마인가요?","options":[{"t":"4400원","correct":true},{"t":"4000원","mis":"M5-1-u1-X12"},{"t":"400원","mis":"M5-1-u1-X12"},{"t":"2750원","mis":"M5-1-u1-X06"}],"explanation":["공급 가격 1500 × 2 + 1000 = 4000원이에요.","세금 4000 ÷ 10 = 400원이에요.","4400원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#24','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C7',4,'essay','teacher','(12 + 3) × 4 − 6을 계산하는 순서를 ①, ②, ③으로 쓰고, ( )가 없는 12 + 3 × 4 − 6과 답이 다른 까닭을 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"M5-1-u1-C7","difficulty":4,"kind":"essay","stem":"(12 + 3) × 4 − 6을 계산하는 순서를 ①, ②, ③으로 쓰고, ( )가 없는 12 + 3 × 4 − 6과 답이 다른 까닭을 설명하세요.","answer_guide":{"answer":"예: ① 12 + 3 = 15 ② 15 × 4 = 60 ③ 60 − 6 = 54. ( )는 12 + 3이 한 덩어리라는 표현이라 가장 먼저 계산한다. ( )가 없으면 3 × 4가 먼저라 18이 되어 답이 다르다.","scoring_points":["( ) 안을 먼저 계산했는가","54를 구했는가","( ) 유무로 덩어리가 달라져 답이 다름을 설명했는가"]},"explanation":["① 15 ② 60 ③ 54예요.","( )는 12 + 3이 한 덩어리라는 뜻이에요.","( )가 없으면 18로 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_c#25','math',5,1,'u1','','g5_1_math_u1_review_c','unit_review','M5-1-u1-C8',4,'essay','teacher','아이스크림 1통(공급 가격 2400원)과 과자 3봉지(1봉지 800원)를 샀어요. 낸 부가 가치세를 두 가지 식으로 나타내 계산하고, 두 답이 같은 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-1-u1-C8","difficulty":4,"kind":"essay","stem":"아이스크림 1통(공급 가격 2400원)과 과자 3봉지(1봉지 800원)를 샀어요. 낸 부가 가치세를 두 가지 식으로 나타내 계산하고, 두 답이 같은 까닭을 쓰세요.","answer_guide":{"answer":"예: (2400 + 800 × 3) ÷ 10 = 480, 2400 ÷ 10 + 800 ÷ 10 × 3 = 240 + 240 = 480. 같은 전체를 같은 크기로 나눈 것이라 같다.","scoring_points":["한 식으로 480을 구했는가","다른 식으로 480을 구했는가","같은 전체를 같은 크기로 나눈 것이라는 까닭을 썼는가"]},"explanation":["묶어서 나누면 480이에요.","각각 나눠 더해도 480이에요.","같은 전체를 같은 크기로 나누어서 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#1','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C1',1,'mc','auto','4000원으로 700원짜리 풀 5개를 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u1-X09']::text[],false,'{"seq":1,"concept":"M5-1-u1-C1","difficulty":1,"kind":"mc","stem":"4000원으로 700원짜리 풀 5개를 샀어요. 남은 돈을 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"4000 − 700 × 5","correct":true},{"t":"4000 + 700 × 5","mis":"M5-1-u1-X09"},{"t":"4000 × 5 − 700","mis":"M5-1-u1-X09"},{"t":"4000 − 700 + 5","mis":"M5-1-u1-X09"}],"explanation":["풀 값은 700 × 5예요.","가진 돈에서 풀 값을 빼요.","한 줄로 이으면 4000 − 700 × 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#2','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C2',1,'sa','auto','63 − 28 + 14를 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M5-1-u1-C2","difficulty":1,"kind":"sa","stem":"63 − 28 + 14를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["49"],"explanation":["덧셈과 뺄셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 63 − 28 = 35 → ② 35 + 14 = 49예요.","그래서 63 − 28 + 14 = 49예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#3','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C2',2,'error','auto','아린이는 84 − 46 + 22를 계산해 16이라고 답했어요. 아린이가 잘못한 것은 무엇인가요?',ARRAY['M5-1-u1-X01','M5-1-u1-X10','M5-1-u1-X14']::text[],false,'{"seq":3,"concept":"M5-1-u1-C2","difficulty":2,"kind":"error","stem":"아린이는 84 − 46 + 22를 계산해 16이라고 답했어요. 아린이가 잘못한 것은 무엇인가요?","options":[{"t":"뒤의 46 + 22를 먼저 했다","correct":true,"mis_target":"M5-1-u1-X01"},{"t":"84 − 46을 잘못 뺐다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["앞에서부터 계산해요.","84 − 46 = 38, 38 + 22 = 60이 맞아요.","아린이는 46 + 22 = 68을 먼저 해서 84 − 68 = 16이 나왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#4','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C3',1,'mc','auto','56 ÷ 7 × 4를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X02','M5-1-u1-X10']::text[],false,'{"seq":4,"concept":"M5-1-u1-C3","difficulty":1,"kind":"mc","stem":"56 ÷ 7 × 4를 계산하면 얼마인가요?","options":[{"t":"32","correct":true},{"t":"2","mis":"M5-1-u1-X02"},{"t":"42","mis":"M5-1-u1-X10"},{"t":"22","mis":"M5-1-u1-X10"}],"explanation":["곱셈과 나눗셈만 섞여 있으니 앞에서부터 차례로 계산해요.","① 56 ÷ 7 = 8 → ② 8 × 4 = 32예요.","그래서 56 ÷ 7 × 4 = 32예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#5','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C3',2,'sa','auto','딸기 54개를 접시 6개에 똑같이 나누어 담고, 그중 5접시를 손님께 드렸어요. 드린 딸기는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M5-1-u1-C3","difficulty":2,"kind":"sa","stem":"딸기 54개를 접시 6개에 똑같이 나누어 담고, 그중 5접시를 손님께 드렸어요. 드린 딸기는 몇 개인가요? 숫자로 쓰세요.","answer":["45","45개"],"explanation":["54 ÷ 6 × 5를 앞에서부터 계산해요.","54 ÷ 6 = 9, 9 × 5 = 45.","45개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#6','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C3',3,'mc','auto','90 ÷ 3 × 5와 90 ÷ (3 × 5)의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],false,'{"seq":6,"concept":"M5-1-u1-C3","difficulty":3,"kind":"mc","stem":"90 ÷ 3 × 5와 90 ÷ (3 × 5)의 계산 결과의 차는 얼마인가요?","options":[{"t":"144","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"150","mis":"M5-1-u1-X14"},{"t":"6","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","90 ÷ 3 × 5 = 150 · 90 ÷ (3 × 5) = 6","두 결과의 차는 150 − 6 = 144예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#7','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C4',1,'mc','auto','9 + 6 × 7에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X03']::text[],false,'{"seq":7,"concept":"M5-1-u1-C4","difficulty":1,"kind":"mc","stem":"9 + 6 × 7에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"6 × 7","correct":true},{"t":"9 + 6","mis":"M5-1-u1-X03"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X03"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","그래서 가장 먼저 계산할 것은 6 × 7이에요.","① 6 × 7 = 42 → ② 9 + 42 = 51이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#8','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C4',2,'sa','auto','80 − 9 × 7을 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-1-u1-C4","difficulty":2,"kind":"sa","stem":"80 − 9 × 7을 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 9 × 7 = 63 → ② 80 − 63 = 17이에요.","그래서 80 − 9 × 7 = 17이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#9','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C4',3,'mc','auto','70 − □ × 6 = 22에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X03']::text[],false,'{"seq":9,"concept":"M5-1-u1-C4","difficulty":3,"kind":"mc","stem":"70 − □ × 6 = 22에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"48","mis":"M5-1-u1-X13"},{"t":"12","mis":"M5-1-u1-X03"},{"t":"4","mis":"M5-1-u1-X13"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 22가 되어야 해요.","거꾸로 되돌리면 □ = 8이에요.","확인: 70 − 8 × 6 → ① 8 × 6 = 48 → ② 70 − 48 = 22"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#10','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C5',1,'mc','auto','27 + 36 ÷ 9를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X04','M5-1-u1-X10']::text[],false,'{"seq":10,"concept":"M5-1-u1-C5","difficulty":1,"kind":"mc","stem":"27 + 36 ÷ 9를 계산하면 얼마인가요?","options":[{"t":"31","correct":true},{"t":"7","mis":"M5-1-u1-X04"},{"t":"41","mis":"M5-1-u1-X10"},{"t":"21","mis":"M5-1-u1-X10"}],"explanation":["곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요.","① 36 ÷ 9 = 4 → ② 27 + 4 = 31이에요.","그래서 27 + 36 ÷ 9 = 31이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#11','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C5',2,'error','auto','나은이는 26 + 30 ÷ 7을 계산해 8이라고 답했어요. 나은이가 잘못한 것은 무엇인가요?',ARRAY['M5-1-u1-X04','M5-1-u1-X10','M5-1-u1-X14']::text[],false,'{"seq":11,"concept":"M5-1-u1-C5","difficulty":2,"kind":"error","stem":"나은이는 26 + 30 ÷ 7을 계산해 8이라고 답했어요. 나은이가 잘못한 것은 무엇인가요?","options":[{"t":"앞의 26 + 30을 먼저 했다","correct":true,"mis_target":"M5-1-u1-X04"},{"t":"30 ÷ 7을 바르게 나눴다","mis":"M5-1-u1-X10"},{"t":"잘못한 곳이 없다","mis":"M5-1-u1-X14"}],"explanation":["나눗셈을 먼저 해야 하는데, 30 ÷ 7은 나누어떨어지지 않아요.","나은이는 26 + 30 = 56을 먼저 해서 56 ÷ 7 = 8이 나왔어요.","덧셈에 나눗셈이 섞이면 나눗셈이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#12','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C5',3,'mc','auto','끈 60 cm 가운데 36 cm를 6조각으로 똑같이 잘라 한 조각을 썼어요. 남은 끈은 몇 cm인가요?',ARRAY['M5-1-u1-X09','M5-1-u1-X04']::text[],false,'{"seq":12,"concept":"M5-1-u1-C5","difficulty":3,"kind":"mc","stem":"끈 60 cm 가운데 36 cm를 6조각으로 똑같이 잘라 한 조각을 썼어요. 남은 끈은 몇 cm인가요?","options":[{"t":"54 cm","correct":true},{"t":"24 cm","mis":"M5-1-u1-X09"},{"t":"6 cm","mis":"M5-1-u1-X09"},{"t":"4 cm","mis":"M5-1-u1-X04"}],"explanation":["60 − 36 ÷ 6이에요.","36 ÷ 6 = 6, 60 − 6 = 54.","54 cm예요. 앞에서부터 하면 24 ÷ 6 = 4가 되어 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#13','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C6',1,'mc','auto','60 − (18 + 22)를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X10']::text[],false,'{"seq":13,"concept":"M5-1-u1-C6","difficulty":1,"kind":"mc","stem":"60 − (18 + 22)를 계산하면 얼마인가요?","options":[{"t":"20","correct":true},{"t":"64","mis":"M5-1-u1-X06"},{"t":"30","mis":"M5-1-u1-X10"},{"t":"10","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요.","① 18 + 22 = 40 → ② 60 − 40 = 20이에요.","그래서 60 − (18 + 22) = 20이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#14','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C6',2,'sa','auto','7 × (12 − 9)를 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M5-1-u1-C6","difficulty":2,"kind":"sa","stem":"7 × (12 − 9)를 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 12 − 9 = 3 → ② 7 × 3 = 21이에요.","그래서 7 × (12 − 9) = 21이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#15','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C6',3,'mc','auto','80 − (24 + 16)과 80 − 24 + 16의 계산 결과의 차는 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X14']::text[],false,'{"seq":15,"concept":"M5-1-u1-C6","difficulty":3,"kind":"mc","stem":"80 − (24 + 16)과 80 − 24 + 16의 계산 결과의 차는 얼마인가요?","options":[{"t":"32","correct":true},{"t":"0","mis":"M5-1-u1-X06"},{"t":"40","mis":"M5-1-u1-X14"},{"t":"72","mis":"M5-1-u1-X14"}],"explanation":["두 식을 각각 계산 순서대로 셈해요.","80 − (24 + 16) = 40 · 80 − 24 + 16 = 72","두 결과의 차는 72 − 40 = 32예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#16','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C7',1,'mc','auto','(20 − 8) ÷ 2 + 5에서 가장 먼저 계산해야 할 것은 어느 것인가요?',ARRAY['M5-1-u1-X06']::text[],false,'{"seq":16,"concept":"M5-1-u1-C7","difficulty":1,"kind":"mc","stem":"(20 − 8) ÷ 2 + 5에서 가장 먼저 계산해야 할 것은 어느 것인가요?","options":[{"t":"20 − 8","correct":true},{"t":"8 ÷ 2","mis":"M5-1-u1-X06"},{"t":"2 + 5","mis":"M5-1-u1-X06"},{"t":"어느 것부터 해도 같다","mis":"M5-1-u1-X06"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","그래서 가장 먼저 계산할 것은 20 − 8이에요.","① 20 − 8 = 12 → ② 12 ÷ 2 = 6 → ③ 6 + 5 = 11이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#17','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C7',2,'mc','auto','(20 − 8) ÷ 2 + 5를 계산하면 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X10']::text[],false,'{"seq":17,"concept":"M5-1-u1-C7","difficulty":2,"kind":"mc","stem":"(20 − 8) ÷ 2 + 5를 계산하면 얼마인가요?","options":[{"t":"11","correct":true},{"t":"21","mis":"M5-1-u1-X06"},{"t":"1","mis":"M5-1-u1-X10"},{"t":"13","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 20 − 8 = 12 → ② 12 ÷ 2 = 6 → ③ 6 + 5 = 11이에요.","그래서 (20 − 8) ÷ 2 + 5 = 11이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#18','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C7',2,'match','auto','계산식과 계산 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":18,"concept":"M5-1-u1-C7","difficulty":2,"kind":"match","stem":"계산식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"36 ÷ 4 + 5 × 2","r":"19"},{"l":"36 ÷ (4 + 5) × 2","r":"8"},{"l":"36 + 4 × 5 − 2","r":"54"}],"mis":"M5-1-u1-X08","explanation":["식마다 계산 순서를 지켜 셈해요.","36 ÷ 4 + 5 × 2 = 19 · 36 ÷ (4 + 5) × 2 = 8 · 36 + 4 × 5 − 2 = 54","곱셈·나눗셈을 먼저 계산하고, 덧셈·뺄셈은 앞에서부터 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#19','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C7',3,'mc','auto','90 − (16 + 8) ÷ 4 × 7을 계산하면 얼마인가요?',ARRAY['M5-1-u1-X06','M5-1-u1-X10']::text[],false,'{"seq":19,"concept":"M5-1-u1-C7","difficulty":3,"kind":"mc","stem":"90 − (16 + 8) ÷ 4 × 7을 계산하면 얼마인가요?","options":[{"t":"48","correct":true},{"t":"88","mis":"M5-1-u1-X06"},{"t":"58","mis":"M5-1-u1-X10"},{"t":"38","mis":"M5-1-u1-X10"}],"explanation":["( ) 안을 가장 먼저 계산해요, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈이에요.","① 16 + 8 = 24 → ② 24 ÷ 4 = 6 → ③ 6 × 7 = 42 → ④ 90 − 42 = 48이에요.","그래서 90 − (16 + 8) ÷ 4 × 7 = 48이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#20','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C7',4,'mc','auto','(9 + □) × 2 − 4 = 30에서 □에 알맞은 수는 얼마인가요?',ARRAY['M5-1-u1-X13','M5-1-u1-X08']::text[],false,'{"seq":20,"concept":"M5-1-u1-C7","difficulty":4,"kind":"mc","stem":"(9 + □) × 2 − 4 = 30에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"17","mis":"M5-1-u1-X13"},{"t":"6","mis":"M5-1-u1-X13"},{"t":"4","mis":"M5-1-u1-X08"}],"explanation":["□에 수를 넣어 계산 순서대로 셈했을 때 30이 되어야 해요.","거꾸로 되돌리면 □ = 8이에요.","확인: (9 + 8) × 2 − 4 → ① 9 + 8 = 17 → ② 17 × 2 = 34 → ③ 34 − 4 = 30"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#21','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C8',1,'mc','auto','공급 가격이 6000원인 물건을 샀어요. 이때 낸 부가 가치세는 얼마인가요?',ARRAY['M5-1-u1-X11','M5-1-u1-X12']::text[],false,'{"seq":21,"concept":"M5-1-u1-C8","difficulty":1,"kind":"mc","stem":"공급 가격이 6000원인 물건을 샀어요. 이때 낸 부가 가치세는 얼마인가요?","options":[{"t":"600원","correct":true},{"t":"60000원","mis":"M5-1-u1-X11"},{"t":"60원","mis":"M5-1-u1-X11"},{"t":"6600원","mis":"M5-1-u1-X12"}],"explanation":["공급 가격 ÷ 10이에요.","6000 ÷ 10 = 600이에요.","600원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#22','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C8',2,'mc','auto','공책 2권(1권 공급 가격 2500원)과 펜 1자루(1500원)를 샀어요. 낸 부가 가치세는 얼마인가요?',ARRAY['M5-1-u1-X11','M5-1-u1-X06']::text[],false,'{"seq":22,"concept":"M5-1-u1-C8","difficulty":2,"kind":"mc","stem":"공책 2권(1권 공급 가격 2500원)과 펜 1자루(1500원)를 샀어요. 낸 부가 가치세는 얼마인가요?","options":[{"t":"650원","correct":true},{"t":"6500원","mis":"M5-1-u1-X11"},{"t":"400원","mis":"M5-1-u1-X06"},{"t":"65원","mis":"M5-1-u1-X11"}],"explanation":["(2500 × 2 + 1500) ÷ 10이에요.","2500 × 2 = 5000, 5000 + 1500 = 6500.","6500 ÷ 10 = 650원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#23','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C8',3,'mc','auto','1000원으로 공급 가격 400원인 지우개 2개를 사려고 해요. 부가 가치세까지 내고 남는 돈은 얼마인가요?',ARRAY['M5-1-u1-X12','M5-1-u1-X09','M5-1-u1-X10']::text[],false,'{"seq":23,"concept":"M5-1-u1-C8","difficulty":3,"kind":"mc","stem":"1000원으로 공급 가격 400원인 지우개 2개를 사려고 해요. 부가 가치세까지 내고 남는 돈은 얼마인가요?","options":[{"t":"120원","correct":true},{"t":"200원","mis":"M5-1-u1-X12"},{"t":"920원","mis":"M5-1-u1-X09"},{"t":"280원","mis":"M5-1-u1-X10"}],"explanation":["공급 가격 800원, 세금 80원이에요.","낸 돈은 880원이에요.","1000 − 880 = 120원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#24','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C7',4,'essay','teacher','15 + 6 × 3 − 9를 계산하는 순서를 ①, ②, ③으로 쓰고, 왜 그 순서로 계산하는지 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"M5-1-u1-C7","difficulty":4,"kind":"essay","stem":"15 + 6 × 3 − 9를 계산하는 순서를 ①, ②, ③으로 쓰고, 왜 그 순서로 계산하는지 설명하세요.","answer_guide":{"answer":"예: ① 6 × 3 = 18 ② 15 + 18 = 33 ③ 33 − 9 = 24. 6 × 3은 하나의 양이라 먼저 구하고, 남은 덧셈과 뺄셈은 같은 층이라 앞에서부터 계산한다.","scoring_points":["6 × 3을 먼저 계산했는가","앞에서부터 해 24를 구했는가","곱셈 부분이 하나의 양이라는 까닭을 썼는가"]},"explanation":["① 18 ② 33 ③ 24예요.","6 × 3은 하나의 양이에요.","나머지는 앞에서부터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u1_review_d#25','math',5,1,'u1','','g5_1_math_u1_review_d','unit_review','M5-1-u1-C6',4,'essay','teacher','「한 봉지에 사탕 6개와 초콜릿 4개를 넣어 8봉지를 만든다」를 하나의 식으로 나타내 필요한 간식 수를 구하고, ( )를 쓴 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-1-u1-C6","difficulty":4,"kind":"essay","stem":"「한 봉지에 사탕 6개와 초콜릿 4개를 넣어 8봉지를 만든다」를 하나의 식으로 나타내 필요한 간식 수를 구하고, ( )를 쓴 까닭을 쓰세요.","answer_guide":{"answer":"예: (6 + 4) × 8 = 10 × 8 = 80개. 한 봉지에 든 간식 6 + 4가 한 묶음이고 그 묶음이 8봉지이므로 ( )로 묶는다.","scoring_points":["(6 + 4) × 8로 식을 세웠는가","80개를 구했는가","한 봉지의 간식이 한 묶음이라는 까닭을 썼는가"]},"explanation":["한 봉지의 간식 6 + 4가 한 묶음이에요.","(6 + 4) × 8 = 80개예요.","( ) 없이 쓰면 6 + 32 = 38로 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
